import type { LocaleId } from './locales'

/**
 * Longer narration for stories, writings, sleep nights, short practices,
 * extras and program days, so each one fills a few real minutes when read
 * aloud. Only Turkish, English, Azerbaijani and Russian for now; the other
 * languages keep the shorter texts in content-natural.ts. copy.ts lays these
 * over NATURAL, keyed the same way: `<pack id>.<field>`.
 */
export const LONG: Record<string, Partial<Record<LocaleId, string>>> = {
  "after-wave.body": {
    tr: "Bu kısa yazı, zor bir an geçtikten sonra içindir. Bir kalem ve kâğıt al.\n\nÖnce birkaç saniye otur. Ayaklarını yere bas, sırtını yasla. Az önce yaşadığın şey geride kaldı, ama bedenin hâlâ biraz titriyor olabilir. Bu normal. Dalga çekildikten sonra su bir süre daha kıpırdar.\n\nBir nefes al ve uzun uzun ver. Bir kez daha. Kalemi eline aldığında acele etmene gerek yok. Bu sayfa kimseye gösterilmeyecek; sadece senin için.\n\nÜç başlık yaz ve her birinin altına bir iki cümle ekle.\n\nBaşlıkları büyük ve sade yazabilirsin. Güzel görünmesi gerekmiyor. İstersen kaydı burada durdur, yazmayı bitirince devam et.\n\nBir: Beden. Şu an bedeninin neresi biraz daha rahat? Küçük bir fark bile olur.\n\nBedenini baştan aşağı yavaşça tara. Belki omuzların biraz indi, belki nefesin biraz uzadı, belki ellerin artık daha sıcak. Ne bulursan onu yaz. “Ellerim ısınıyor” gibi kısa bir cümle yeter.\n\nHiçbir yer rahat değilse, “Ayaklarım yerde” yaz. Bu da gerçek ve bu da bir başlangıç.\n\nİki: Oda. Etrafında gördüğün bir eşyanın adını yaz.\n\nEtrafına bak ve gözüne ilk takılan eşyayı seç. Bir bardak, bir perde, bir kitap. Adını yaz, sonra yanına rengini ekle. “Mavi bardak.” Bu küçük cümle seni bulunduğun odaya geri bağlar.\n\nÜç: Teşekkür. Bugün sana iyi gelen küçük ve gerçek bir şey.\n\nBüyük bir şey aramana gerek yok. Bir yudum su, bir mesaj, pencereden gelen ışık, az önce aldığın rahat bir nefes. Küçük ve gerçek olsun.\n\nYazdığın şeyi bir kez daha oku. Onu yazarken yüzünde ya da göğsünde bir şey yumuşadı mı? Fark etmesen de olur.\n\nYorum yapmana, analiz etmene gerek yok. Bitirince defteri kapat. Bu bir rapor değil, sadece kısa bir mola.\n\nDefteri kapattıktan sonra elini bir süre kapağın üstünde tut. Nefes al… ve ver. Dalga geçti. Şimdi buradasın; bir odada, sağlam bir zeminde, kendi nefesinle.\n\nBu sayfayı ne zaman istersen yeniden açabilirsin. Bir dahaki zor anın ardından da aynı üç başlık seni bekliyor olacak.",
    en: "This short writing exercise is for after a difficult moment has passed. Take a pen and some paper.\n\nFirst, sit for a few seconds. Put your feet on the floor and lean back. What just happened is behind you now, but your body may still be trembling a little. That is normal. After a wave pulls back, the water keeps moving for a while.\n\nTake a breath and let it out long and slow. Once more. When you pick up the pen, there is no need to hurry. No one will see this page; it is just for you.\n\nWrite three headings, and add a sentence or two under each.\n\nYou can write the headings big and plain. It does not need to look nice. If you like, pause the recording here and come back when you have finished writing.\n\nOne: Body. Which part of your body feels a little easier right now? Even a small difference counts.\n\nSlowly scan your body from top to bottom. Perhaps your shoulders have dropped a little, perhaps your breath is a little longer, perhaps your hands are warmer now. Write down whatever you find. A short sentence like “My hands are warming up” is enough.\n\nIf nowhere feels easier, write “My feet are on the floor.” That is true too, and it is a beginning.\n\nTwo: Room. Write the name of one object you can see around you.\n\nLook around and choose the first object that catches your eye. A glass, a curtain, a book. Write its name, then add its colour. “Blue glass.” This small sentence connects you back to the room you are in.\n\nThree: Thanks. One small, real thing that did you good today.\n\nYou do not need to look for something big. A sip of water, a message, the light from the window, the easy breath you just took. Let it be small and real.\n\nRead what you wrote once more. As you wrote it, did something soften in your face or your chest? It is fine if you did not notice.\n\nThere is no need to comment or analyze. When you are done, close the notebook. This is not a report, just a short pause.\n\nAfter you close the notebook, keep your hand on the cover for a moment. Breathe in… and out. The wave has passed. Now you are here; in a room, on solid ground, with your own breath.\n\nYou can open this page again whenever you like. After your next hard moment, the same three headings will be waiting for you.",
    az: "Bu qısa yazı çətin bir an keçdikdən sonra üçündür. Qələm və kağız götür.\n\nƏvvəlcə bir neçə saniyə otur. Ayaqlarını yerə bas, kürəyini söykə. Bir az əvvəl yaşadığın şey geridə qaldı, amma bədənin hələ bir az titrəyə bilər. Bu normaldır. Dalğa çəkiləndən sonra su bir müddət də tərpənir.\n\nBir nəfəs al və uzun-uzun ver. Bir dəfə də. Qələmi əlinə götürəndə tələsməyə ehtiyac yoxdur. Bu səhifəni heç kim görməyəcək; o, yalnız sənin üçündür.\n\nÜç başlıq yaz və hər birinin altına bir-iki cümlə əlavə et.\n\nBaşlıqları iri və sadə yaza bilərsən. Gözəl görünməsi vacib deyil. İstəsən, səsi burada dayandır, yazıb bitirəndə davam et.\n\nBir: Bədən. İndi bədəninin harası bir az daha rahatdır? Kiçik bir fərq də olar.\n\nBədənini yuxarıdan aşağı yavaş-yavaş nəzərdən keçir. Bəlkə çiyinlərin bir az enib, bəlkə nəfəsin bir az uzanıb, bəlkə əllərin artıq daha istidir. Nə tapırsansa, onu yaz. “Əllərim isinir” kimi qısa bir cümlə kifayətdir.\n\nHeç bir yer rahat deyilsə, “Ayaqlarım yerdədir” yaz. Bu da həqiqətdir və bu da bir başlanğıcdır.\n\nİki: Otaq. Ətrafında gördüyün bir əşyanın adını yaz.\n\nƏtrafına bax və gözünə ilk dəyən əşyanı seç. Bir stəkan, bir pərdə, bir kitab. Adını yaz, sonra yanına rəngini əlavə et. “Mavi stəkan.” Bu kiçik cümlə səni olduğun otağa geri bağlayır.\n\nÜç: Təşəkkür. Bu gün sənə xoş gələn kiçik və həqiqi bir şey.\n\nBöyük bir şey axtarmağa ehtiyac yoxdur. Bir qurtum su, bir mesaj, pəncərədən gələn işıq, bir az əvvəl aldığın rahat nəfəs. Kiçik və həqiqi olsun.\n\nYazdığını bir dəfə də oxu. Onu yazanda üzündə və ya sinəndə nəsə yumşaldımı? Fərqinə varmasan da olar.\n\nŞərh yazmağa, təhlil etməyə ehtiyac yoxdur. Bitirəndə dəftəri bağla. Bu hesabat deyil, sadəcə qısa bir fasilədir.\n\nDəftəri bağlayandan sonra əlini bir müddət onun üstündə saxla. Nəfəs al… və ver. Dalğa keçdi. İndi buradasan; bir otaqda, möhkəm döşəmədə, öz nəfəsinlə.\n\nBu səhifəni nə vaxt istəsən, yenidən aça bilərsən. Növbəti çətin anından sonra da eyni üç başlıq səni gözləyəcək.",
    ru: "Это короткое упражнение для момента, когда трудная минута уже позади. Возьми ручку и лист бумаги.\n\nСначала посиди несколько секунд. Поставь ступни на пол, обопрись спиной. То, что только что происходило, уже позади, но тело может ещё немного дрожать. Это нормально. Когда волна отступает, вода ещё какое-то время колышется.\n\nСделай вдох и долгий медленный выдох. Ещё раз. Когда берёшь ручку, спешить не нужно. Эту страницу никто не увидит; она только для тебя.\n\nНапиши три заголовка и под каждым — одно-два предложения.\n\nЗаголовки можно написать крупно и просто. Красиво быть не должно. Если хочется, поставь запись на паузу и вернись, когда допишешь.\n\nПервое: тело. Где в теле сейчас стало чуть легче? Даже маленькая разница считается.\n\nМедленно пройдись вниманием по телу сверху вниз. Может быть, плечи немного опустились, дыхание стало чуть длиннее, руки потеплели. Запиши то, что находишь. Хватит короткой фразы вроде «Руки теплеют».\n\nЕсли нигде не стало легче, напиши: «Ступни на полу». Это тоже правда, и это тоже начало.\n\nВторое: комната. Напиши название одного предмета, который видишь рядом.\n\nОглянись и выбери первый предмет, на который падает взгляд. Стакан, штора, книга. Напиши его название, а рядом цвет. «Синий стакан». Эта маленькая фраза снова связывает тебя с комнатой, где ты находишься.\n\nТретье: спасибо. Одна маленькая настоящая вещь, которая сегодня была тебе в радость.\n\nИскать что-то большое не нужно. Глоток воды, сообщение, свет из окна, спокойный вдох минуту назад. Пусть это будет маленьким и настоящим.\n\nПеречитай написанное ещё раз. Пока это писалось, смягчилось ли что-то в лице или в груди? Если не заметно, это тоже нормально.\n\nКомментировать и анализировать не нужно. Когда закончишь, закрой тетрадь. Это не отчёт, а просто короткая передышка.\n\nКогда тетрадь закрыта, подержи ладонь на обложке ещё немного. Вдох… и выдох. Волна прошла. Сейчас ты здесь: в комнате, на твёрдом полу, со своим дыханием.\n\nЭту страницу можно открыть снова в любой момент. После следующей трудной минуты тебя будут ждать те же три заголовка.",
  },
  "attic.body": {
    tr: "Eski bir evin çatı katındasın. Tavan alçak, havada hafif bir ahşap kokusu var.\n\nÇatı katına dar, ahşap bir merdivenle çıktın. Her basamak tanıdık bir sesle gıcırdadı. Yukarıda eski eşyalar, katlanmış perdeler ve bir köşede yer minderleri var.\n\nYukarıda, çatının üstünde yağmur yağıyor. Damlalar düzenli bir ritimle vuruyor; ne hızlı ne yavaş.\n\nBir süre sadece yağmuru dinliyorsun. Bazen bir damla çatı oluğundan aşağı düşüyor ve ayrı bir ses çıkarıyor. Sonra yine o düzenli, yumuşak ritim.\n\nNefesin yağmurla birlikte yavaşlıyor. Damlaların arasına nefesini yerleştiriyorsun. Alıyorsun… ve uzun uzun veriyorsun.\n\nDar pencere buğulanmış. Dışarısı karanlık, içerisi sıcak.\n\nPencerenin buğusuna parmağınla küçük bir çizgi çiziyorsun. Çizginin içinden dışarıdaki ıslak dalları ve uzaktaki bir sokak lambasını görüyorsun. Sonra buğu yavaşça yeniden kapanıyor.\n\nKöşede eski bir sandık, üstünde kalın bir battaniye var. Sarı bir lamba odayı yumuşak bir ışıkla dolduruyor.\n\nMinderlerden birine oturuyorsun. Lambanın ışığı ahşap kirişlerin üstünde yumuşak gölgeler bırakıyor. Odada eski kitapların, kuru lavantanın ve tahtanın kokusu var.\n\nAşağıdaki evden çok hafif sesler geliyor; bir kapının kapanması, bir saatin uzak tik takı. Sonra yine yalnızca yağmur. Evin geri kalanı da uykuya hazırlanıyor.\n\nBattaniyeyi omuzlarına alıyorsun. Sandığı açmana gerek yok. Burada çözülecek ya da düzeltilecek hiçbir şey yok.\n\nBattaniyenin yünü yanağına değiyor. Bacaklarını kendine çekiyorsun, sonra yeniden uzatıyorsun. Bedenin minderin üstünde rahat bir yer buluyor. Omuzların, sırtın, ellerin yavaşça ağırlaşıyor.\n\nYağmur biraz hafifliyor, sonra yeniden artıyor. Ne olursa olsun çatı sağlam. Kirişler yüz yıldır bu evi taşıyor, bu gece de seni taşıyor.\n\nYağmur sadece yağıyor. Çatı seni koruyor. Bu küçük, sıcak odada güvendesin. Damlaların sesi seni yavaşça uykuya çağırıyor.\n\nLambayı biraz kısıyorsun. Oda daha da yumuşak, daha da sıcak. Damlalar düşmeye devam ediyor ve sen yavaş yavaş onların sesine bırakıyorsun kendini.",
    en: "You are in the attic of an old house. The ceiling is low, and the air smells faintly of wood.\n\nYou climbed up to the attic by a narrow wooden ladder. Each step creaked with a familiar sound. Up here there are old things, folded curtains, and a few floor cushions in a corner.\n\nAbove you, rain is falling on the roof. The drops land in a steady rhythm, neither fast nor slow.\n\nFor a while you simply listen to the rain. Now and then a drop falls from the gutter and makes a sound of its own. Then the same steady, soft rhythm returns.\n\nYour breath slows down with the rain. You place your breath between the drops. You breathe in… and breathe out long and slow.\n\nThe narrow window is misted over. Outside it is dark; inside it is warm.\n\nWith your finger you draw a small line in the mist on the window. Through the line you can see wet branches outside and a street lamp far away. Then the mist slowly closes over it again.\n\nIn the corner there is an old chest with a thick blanket on top. A yellow lamp fills the room with soft light.\n\nYou sit down on one of the cushions. The lamplight leaves soft shadows on the wooden beams. The room smells of old books, dried lavender and wood.\n\nVery faint sounds come from the house below; a door closing, the distant tick of a clock. Then only the rain again. The rest of the house is getting ready for sleep too.\n\nYou pull the blanket around your shoulders. You do not need to open the chest. There is nothing here to solve or to fix.\n\nThe wool of the blanket brushes your cheek. You draw your legs up, then stretch them out again. Your body finds a comfortable place on the cushion. Your shoulders, your back, your hands slowly grow heavy.\n\nThe rain eases a little, then grows stronger again. Whatever happens, the roof is strong. These beams have held this house for a hundred years, and tonight they are holding you.\n\nThe rain simply falls. The roof keeps you sheltered. In this small, warm room you are safe, and the sound of the drops gently invites you toward sleep.\n\nYou turn the lamp down a little. The room becomes even softer, even warmer. The drops keep falling, and little by little you let yourself go to their sound.",
    az: "Köhnə bir evin çardağındasan. Tavan alçaqdır, havada yüngül taxta qoxusu var.\n\nÇardağa dar, taxta bir pilləkənlə qalxdın. Hər pillə tanış bir səslə cırıldadı. Yuxarıda köhnə əşyalar, qatlanmış pərdələr və bir küncdə döşəkçələr var.\n\nYuxarıda, damın üstündə yağış yağır. Damcılar ahəngdar vurur; nə tez, nə də yavaş.\n\nBir müddət sadəcə yağışı dinləyirsən. Bəzən novdan bir damcı düşür və ayrı bir səs çıxarır. Sonra yenə o ahəngdar, yumşaq ritm.\n\nNəfəsin yağışla birlikdə yavaşlayır. Nəfəsini damcıların arasına yerləşdirirsən. Alırsan… və uzun-uzun verirsən.\n\nDar pəncərə buğulanıb. Çöl qaranlıqdır, içəri istidir.\n\nPəncərənin buğusunda barmağınla kiçik bir xətt çəkirsən. Xəttin içindən bayırdakı yaş budaqları və uzaqdakı küçə fənərini görürsən. Sonra buğu yavaş-yavaş yenidən bağlanır.\n\nKüncdə köhnə bir sandıq, üstündə qalın bir yorğan var. Sarı bir lampa otağı yumşaq işıqla doldurur.\n\nDöşəkçələrdən birinin üstündə oturursan. Lampanın işığı taxta tirlərin üstündə yumşaq kölgələr salır. Otaqda köhnə kitabların, quru lavandanın və taxtanın qoxusu var.\n\nAşağıdakı evdən çox zəif səslər gəlir; bir qapının bağlanması, saatın uzaqdan gələn tıqqıltısı. Sonra yenə yalnız yağış. Evin qalanı da yuxuya hazırlaşır.\n\nYorğanı çiyinlərinə salırsan. Sandığı açmağa ehtiyac yoxdur. Burada həll etməli və ya düzəltməli heç nə yoxdur.\n\nYorğanın yunu yanağına toxunur. Ayaqlarını özünə çəkirsən, sonra yenə uzadırsan. Bədənin döşəkçənin üstündə rahat bir yer tapır. Çiyinlərin, kürəyin, əllərin yavaş-yavaş ağırlaşır.\n\nYağış bir az zəifləyir, sonra yenə güclənir. Nə olursa olsun, dam möhkəmdir. Bu tirlər yüz ildir bu evi saxlayır, bu gecə də səni saxlayır.\n\nYağış sadəcə yağır. Dam səni qoruyur. Bu kiçik, isti otaqda təhlükəsizsən. Damcıların səsi səni yavaş-yavaş yuxuya çağırır.\n\nLampanı bir az azaldırsan. Otaq daha da yumşaq, daha da isti olur. Damcılar düşməyə davam edir və sən yavaş-yavaş özünü onların səsinə buraxırsan.",
    ru: "Ты на чердаке старого дома. Потолок низкий, в воздухе лёгкий запах дерева.\n\nНа чердак ведёт узкая деревянная лестница. Каждая ступенька поскрипывает знакомым звуком. Наверху старые вещи, сложенные шторы и несколько подушек для сидения в углу.\n\nНад тобой по крыше идёт дождь. Капли стучат ровно — не быстро и не медленно.\n\nКакое-то время ты просто слушаешь дождь. Иногда с водостока срывается капля и звучит отдельно. Потом снова тот же ровный, мягкий ритм.\n\nДыхание замедляется вместе с дождём. Ты укладываешь дыхание между каплями. Вдох… и долгий, медленный выдох.\n\nУзкое окно запотело. Снаружи темно, внутри тепло.\n\nПальцем ты проводишь маленькую линию на запотевшем стекле. Сквозь неё видны мокрые ветки снаружи и далёкий уличный фонарь. Потом стекло медленно затуманивается снова.\n\nВ углу стоит старый сундук, на нём толстое одеяло. Жёлтая лампа наполняет комнату мягким светом.\n\nТы садишься на одну из подушек. Свет лампы оставляет мягкие тени на деревянных балках. В комнате пахнет старыми книгами, сухой лавандой и деревом.\n\nИз дома снизу доносятся совсем тихие звуки: закрывается дверь, где-то далеко тикают часы. Потом снова только дождь. Весь дом тоже готовится ко сну.\n\nТы накидываешь одеяло на плечи. Открывать сундук не нужно. Здесь нечего решать и нечего чинить.\n\nШерсть одеяла касается щеки. Ты подтягиваешь ноги к себе, потом снова вытягиваешь. Тело находит удобное место на подушке. Плечи, спина, руки медленно тяжелеют.\n\nДождь немного стихает, потом снова усиливается. Что бы ни было, крыша крепкая. Эти балки сто лет держат дом, и этой ночью они держат тебя.\n\nДождь просто идёт. Крыша укрывает тебя. В этой маленькой тёплой комнате ты в безопасности, и звук капель тихо зовёт тебя ко сну.\n\nТы чуть приглушаешь лампу. Комната становится ещё мягче и теплее. Капли продолжают падать, и ты понемногу отдаёшься их звуку.",
  },
  "bath.body": {
    tr: "Küçük, eski bir hamamdasın. Kubbeden loş bir ışık süzülüyor. Hava ılık ve nemli.\n\nKapıdan girerken ayakkabılarını çıkarıyorsun. Ayaklarının altındaki taşlar ılık. Kubbedeki küçük cam gözlerden yıldız gibi ışıklar süzülüyor ve buharın içinde yumuşakça dağılıyor.\n\nSıcak bir mermer taşın üzerine oturuyorsun. Sırtını taşa yaslıyorsun; sıcaklık yavaşça kaslarına yayılıyor.\n\nGözlerini kubbeye kaldırıyorsun. Işık hüzmeleri buharın içinde ağır ağır hareket ediyor. Buhar yükseliyor, dağılıyor, yeniden toplanıyor. Hiçbir şeyin acelesi yok.\n\nSıcaklık önce sırtına, sonra omuzlarına yayılıyor. Kasların bir bir gevşiyor. Gün boyu taşıdığın yük, sanki taşın içine sızıyor.\n\nYanındaki kurnadan ince bir su akıyor. Sesi yumuşak ve kesintisiz.\n\nAvucunu kurnanın altına tutuyorsun. Su ılık ve yumuşak. Bir tas suyu omuzlarından aşağı döküyorsun; sıcaklık sırtından aşağı süzülüyor. Bir kez daha. Su, gün boyu biriken her şeyi yavaşça alıp götürüyor.\n\nTabanların ılık taşın üzerinde. Burada ayna yok, bakılacak bir şey yok. Kimse senden bir şey beklemiyor.\n\nNefesini fark ediyorsun. Nemli, ılık hava burnundan içeri giriyor, göğsünü dolduruyor. Veriyorsun ve omuzların biraz daha iniyor. Bir kez daha… al… ve bırak.\n\nUzaktan, hamamın başka bir odasından, hafif bir su sesi ve alçak bir mırıltı geliyor. Sonra yine yalnızca senin kurnanın sesi kalıyor.\n\nBir süre hiçbir şey olmuyor. Ve bu çok iyi. Sadece sıcaklık, suyun sesi ve senin nefesin var.\n\nBir süre sonra kalkıp serin odaya geçiyorsun. Kalın, yumuşak bir peştemale sarınıyorsun. Bir sedirin üstüne uzanıyorsun; biri yanına küçük bir bardak sıcak çay bırakmış.\n\nBedenin ağır ve sıcak. Teninde hâlâ suyun ılıklığı var. Çayı yudumluyorsun ve bardağı yavaşça yerine bırakıyorsun.\n\nHer nefes verişinde biraz daha yumuşuyorsun. Omuzların, sırtın, ellerin… hepsi taşın sıcaklığına teslim oluyor.\n\nGözlerin kapanmak isterse izin ver. Hamamın sessizliği, ılık taş ve suyun sesi seninle kalacak. Bu gece dinlenmek için her şey hazır.",
    en: "You are in a small, old bathhouse. Dim light filters down from the dome. The air is warm and moist.\n\nYou take off your shoes at the door. The stones beneath your feet are warm. Small glass openings in the dome let in points of light like stars, and they spread softly through the steam.\n\nYou sit on a warm slab of marble and lean your back against the stone. The warmth slowly spreads into your muscles.\n\nYou lift your eyes to the dome. The beams of light move slowly through the steam. The steam rises, drifts apart, gathers again. Nothing is in a hurry.\n\nThe warmth spreads first into your back, then into your shoulders. One by one, your muscles let go. The weight you have carried all day seems to sink into the stone.\n\nBeside you, a thin stream of water runs into a stone basin. Its sound is soft and unbroken.\n\nYou hold your palm under the basin tap. The water is warm and soft. You pour a bowl of water over your shoulders, and the warmth runs down your back. Once more. The water slowly carries away everything that has built up during the day.\n\nThe soles of your feet rest on the warm stone. There is no mirror here, nothing to look at. No one expects anything from you.\n\nNotice your breath. The warm, moist air comes in through your nose and fills your chest. You breathe out, and your shoulders drop a little more. Once more… in… and let go.\n\nFrom another room of the bath comes the faint sound of water and a low murmur. Then there is only the sound of your own basin again.\n\nFor a while, nothing happens. And that is good. There is only warmth, the sound of water, and your breath.\n\nAfter a while you get up and move into the cool room. You wrap yourself in a thick, soft towel. You lie down on a low bench; someone has left a small glass of hot tea beside you.\n\nYour body is heavy and warm. The warmth of the water is still on your skin. You sip the tea and slowly put the glass back.\n\nWith every out-breath you soften a little more. Your shoulders, your back, your hands… all of them give way to the warmth of the stone.\n\nIf your eyes want to close, let them. The quiet of the bath, the warm stone and the sound of the water will stay with you. Everything is ready for rest tonight.",
    az: "Kiçik, köhnə bir hamamdasan. Günbəzdən zəif bir işıq süzülür. Hava ilıq və nəmlidir.\n\nQapıdan girəndə ayaqqabılarını çıxarırsan. Ayaqlarının altındakı daşlar ilıqdır. Günbəzdəki kiçik şüşə pəncərələrdən ulduz kimi işıqlar süzülür və buxarın içində yumşaqca dağılır.\n\nİsti mərmər daşın üstündə oturursan. Kürəyini daşa söykəyirsən; istilik yavaş-yavaş əzələlərinə yayılır.\n\nGözlərini günbəzə qaldırırsan. İşıq zolaqları buxarın içində ağır-ağır hərəkət edir. Buxar qalxır, dağılır, yenidən toplanır. Heç nə tələsmir.\n\nİstilik əvvəl kürəyinə, sonra çiyinlərinə yayılır. Əzələlərin bir-bir boşalır. Bütün günü daşıdığın yük sanki daşın içinə hopur.\n\nYanındakı daş hovuzcuğa incə bir su axır. Səsi yumşaq və fasiləsizdir.\n\nOvucunu axan suyun altına tutursan. Su ilıq və yumşaqdır. Bir tas suyu çiyinlərindən aşağı tökürsən; istilik kürəyindən aşağı süzülür. Bir dəfə də. Su gün ərzində yığılan hər şeyi yavaş-yavaş aparır.\n\nAyaqaltıların ilıq daşın üstündədir. Burada güzgü yoxdur, baxmalı heç nə yoxdur. Heç kim səndən heç nə gözləmir.\n\nNəfəsinin fərqinə var. Nəmli, ilıq hava burnundan içəri girir, sinəni doldurur. Nəfəs verirsən və çiyinlərin bir az da enir. Bir dəfə də… al… və burax.\n\nHamamın başqa bir otağından yüngül su səsi və alçaq bir mızıltı gəlir. Sonra yenə yalnız sənin yanındakı suyun səsi qalır.\n\nBir müddət heç nə baş vermir. Və bu çox yaxşıdır. Sadəcə istilik, suyun səsi və sənin nəfəsin var.\n\nBir müddətdən sonra qalxıb sərin otağa keçirsən. Qalın, yumşaq bir dəsmala bürünürsən. Taxtın üstünə uzanırsan; kimsə yanına kiçik bir stəkan isti çay qoyub.\n\nBədənin ağır və istidir. Dərinin üstündə hələ də suyun ilıqlığı qalıb. Çaydan bir qurtum içib stəkanı yavaşca yerinə qoyursan.\n\nHər nəfəs verəndə bir az da yumşalırsan. Çiyinlərin, kürəyin, əllərin… hamısı daşın istiliyinə təslim olur.\n\nGözlərin yumulmaq istəsə, icazə ver. Hamamın sükutu, ilıq daş və suyun səsi səninlə qalacaq. Bu gecə dincəlmək üçün hər şey hazırdır.",
    ru: "Ты в маленькой старинной бане. Из-под купола падает мягкий приглушённый свет. Воздух тёплый и влажный.\n\nУ входа ты снимаешь обувь. Камни под ногами тёплые. Маленькие стеклянные окошки в куполе пропускают свет, похожий на звёзды, и он мягко рассеивается в пару.\n\nТы садишься на тёплую мраморную плиту и прислоняешься спиной к камню. Тепло медленно расходится по мышцам.\n\nТы поднимаешь взгляд к куполу. Лучи света медленно движутся в пару. Пар поднимается, расходится, снова собирается. Ничто не торопится.\n\nТепло сначала разливается по спине, потом по плечам. Мышцы одна за другой отпускают напряжение. Груз этого дня словно уходит в камень.\n\nРядом в каменную чашу льётся тонкая струйка воды. Звук мягкий и непрерывный.\n\nТы подставляешь ладонь под струю. Вода тёплая и мягкая. Ты льёшь из чаши воду на плечи, и тепло стекает по спине. Ещё раз. Вода медленно уносит всё, что накопилось за день.\n\nСтупни лежат на тёплом камне. Здесь нет зеркала, не на что смотреть. Никто ничего от тебя не ждёт.\n\nЗаметь дыхание. Тёплый влажный воздух входит через нос и наполняет грудь. Выдох — и плечи опускаются ещё немного. Ещё раз… вдох… и отпусти.\n\nИз другого зала доносится слабый плеск воды и негромкий разговор. Потом снова слышна только твоя струйка.\n\nКакое-то время ничего не происходит. И это очень хорошо. Есть только тепло, звук воды и твоё дыхание.\n\nЧерез какое-то время ты встаёшь и переходишь в прохладный зал. Ты заворачиваешься в толстое мягкое полотенце и ложишься на низкую скамью; кто-то оставил рядом маленький стакан горячего чая.\n\nТело тяжёлое и тёплое. На коже всё ещё тепло воды. Ты делаешь глоток чая и медленно ставишь стакан на место.\n\nС каждым выдохом ты становишься чуть мягче. Плечи, спина, руки… всё отдаётся теплу камня.\n\nЕсли глаза хотят закрыться, позволь им. Тишина бани, тёплый камень и звук воды останутся с тобой. Этой ночью всё готово для отдыха.",
  },
  "c1.body": {
    tr: "Bugünün küçük adımı çeneyle ilgili. Çene, gün boyu farkında olmadan en çok sıktığımız yerlerden biri. Stresliyken, odaklanırken, hatta uyurken bile.\n\nRahat bir yerde otur. Sırtın dik ama rahat olsun. Bir nefes al ve yavaşça ver.\n\nAzı dişlerini birbirinden ayır. Dilinin ucunu damağına hafifçe yasla. Otuz saniye böyle kal ve çenenin yumuşamasını izle.\n\nŞimdi çeneni fark et. Dişlerin birbirine değiyor mu? Yanaklarının içinde, kulaklarının hemen önünde bir gerginlik var mı? Değiştirmeye çalışmadan önce sadece bak.\n\nArdından dişlerini yavaşça birbirinden ayır. Dudakların kapalı kalabilir, ama dişlerin arasında küçük bir boşluk olsun. Dilinin ucu üst ön dişlerinin hemen arkasında, damağa hafifçe değsin.\n\nParmak uçlarınla çene ekleminin üstüne, kulaklarının önüne dokun. Küçük daireler çizerek nazikçe ovala. Bir yöne birkaç kez, sonra diğer yöne.\n\nAğzını yavaşça biraz aç, sonra yavaşça kapat ama dişlerin yine birbirine değmesin. Bir kez daha. Hareket ne kadar küçük olursa o kadar iyi.\n\nŞimdi nefesine dön. Burnundan nefes al… ve ağzından, dudakların hafif aralık, yavaşça ver. Verirken çenenin biraz daha aşağı düştüğünü hayal et.\n\nYanakların, şakakların, alnın… hepsi çeneyle birlikte biraz yumuşuyor. Yüzündeki küçük kaslar bir bir bırakıyor.\n\nGün içinde çeneni sıktığını fark ettiğinde bu adımı hatırla. Dişler ayrı, dil damakta, bir uzun nefes. Birkaç saniye yeter.\n\nŞimdi bir tur daha yapalım. Dişler ayrı. Dil damakta. Nefes al… ve ver. Bu kez verirken dudaklarının da yumuşadığını fark et. Ağzının köşeleri gevşiyor.\n\nBir süre bu yumuşaklıkta kal. Çenen ağır ve rahat. Yüzün dinleniyor. Hazır olduğunda gözlerini aç ve gününe bu yumuşak yüzle dön.",
    en: "Today's small step is about the jaw. The jaw is one of the places we clench most without noticing, all day long. When we are stressed, when we concentrate, even when we sleep.\n\nSit somewhere comfortable. Keep your back upright but relaxed. Take a breath and let it out slowly.\n\nLet your back teeth part. Rest the tip of your tongue lightly on the roof of your mouth. Stay like this for thirty seconds and notice your jaw softening.\n\nNow notice your jaw. Are your teeth touching? Is there tension inside your cheeks, just in front of your ears? Before trying to change anything, simply look.\n\nThen gently let your teeth part. Your lips can stay closed, but leave a small gap between your teeth. Let the tip of your tongue rest just behind your upper front teeth, lightly touching the roof of your mouth.\n\nWith your fingertips, touch the joint of your jaw, just in front of your ears. Massage it gently in small circles. A few times in one direction, then the other.\n\nOpen your mouth slowly a little, then close it slowly, without letting your teeth touch again. Once more. The smaller the movement, the better.\n\nNow come back to your breath. Breathe in through your nose… and breathe out slowly through your mouth, lips slightly apart. As you breathe out, imagine your jaw dropping a little further.\n\nYour cheeks, your temples, your forehead… all of them soften a little with the jaw. The small muscles of your face let go one by one.\n\nWhenever you notice yourself clenching during the day, remember this step. Teeth apart, tongue on the roof of the mouth, one long breath. A few seconds is enough.\n\nLet us do one more round. Teeth apart. Tongue resting. Breathe in… and out. This time, as you breathe out, notice your lips softening too. The corners of your mouth relax.\n\nStay in this softness for a while. Your jaw is heavy and at ease. Your face is resting. When you are ready, open your eyes and return to your day with this soft face.",
    az: "Bugünün kiçik addımı çənə ilə bağlıdır. Çənə gün boyu fərqinə varmadan ən çox sıxdığımız yerlərdən biridir. Stresdə olanda, fikrimizi cəmləyəndə, hətta yatanda belə.\n\nRahat bir yerdə otur. Kürəyin düz, amma rahat olsun. Bir nəfəs al və yavaşca ver.\n\nAzı dişlərini bir-birindən arala. Dilinin ucunu yüngülcə damağına söykə. Otuz saniyə belə qal və çənənin yumşaldığını izlə.\n\nİndi çənənin fərqinə var. Dişlərin bir-birinə toxunurmu? Yanaqlarının içində, qulaqlarının qabağında bir gərginlik varmı? Nəyisə dəyişməyə çalışmadan əvvəl sadəcə bax.\n\nSonra dişlərini yavaşca bir-birindən arala. Dodaqların bağlı qala bilər, amma dişlərinin arasında kiçik bir boşluq olsun. Dilinin ucu üst ön dişlərinin arxasında, damağa yüngülcə toxunsun.\n\nBarmaqlarının ucu ilə çənə oynağına, qulaqlarının qabağına toxun. Kiçik dairələr çəkərək yumşaqca ovuştur. Bir neçə dəfə bir tərəfə, sonra o biri tərəfə.\n\nAğzını yavaşca bir az aç, sonra yavaşca bağla, amma dişlərin yenə bir-birinə toxunmasın. Bir dəfə də. Hərəkət nə qədər kiçik olsa, o qədər yaxşıdır.\n\nİndi nəfəsinə qayıt. Burnundan nəfəs al… və ağzından, dodaqların yüngülcə aralı, yavaşca ver. Verəndə çənənin bir az da aşağı düşdüyünü təsəvvür et.\n\nYanaqların, gicgahların, alnın… hamısı çənə ilə birlikdə bir az yumşalır. Üzündəki kiçik əzələlər bir-bir boşalır.\n\nGün ərzində çənəni sıxdığını hiss edəndə bu addımı xatırla. Dişlər aralı, dil damaqda, bir uzun nəfəs. Bir neçə saniyə kifayətdir.\n\nİndi bir dəfə də edək. Dişlər aralı. Dil damaqda. Nəfəs al… və ver. Bu dəfə verəndə dodaqlarının da yumşaldığını hiss et. Ağzının kənarları boşalır.\n\nBir müddət bu yumşaqlıqda qal. Çənən ağır və rahatdır. Üzün dincəlir. Hazır olanda gözlərini aç və gününə bu yumşaq üzlə qayıt.",
    ru: "Сегодняшний маленький шаг — про челюсть. Челюсть — одно из мест, которые мы сильнее всего сжимаем в течение дня, даже не замечая этого. В стрессе, когда сосредотачиваемся, даже во сне.\n\nСядь удобно. Спина прямая, но расслабленная. Сделай вдох и медленный выдох.\n\nРазомкни коренные зубы. Слегка прислони кончик языка к нёбу. Побудь так тридцать секунд и замечай, как челюсть становится мягче.\n\nТеперь заметь челюсть. Касаются ли зубы друг друга? Есть ли напряжение внутри щёк, прямо перед ушами? Прежде чем что-то менять, просто посмотри.\n\nПотом мягко разомкни зубы. Губы могут оставаться сомкнутыми, но между зубами пусть будет небольшой зазор. Кончик языка лежит сразу за верхними передними зубами, слегка касаясь нёба.\n\nКончиками пальцев коснись челюстного сустава, прямо перед ушами. Мягко помассируй маленькими кругами. Несколько раз в одну сторону, потом в другую.\n\nМедленно чуть приоткрой рот, потом медленно закрой, не давая зубам снова сомкнуться. Ещё раз. Чем меньше движение, тем лучше.\n\nТеперь вернись к дыханию. Вдох через нос… и медленный выдох через рот, губы слегка приоткрыты. На выдохе представь, что челюсть опускается ещё немного.\n\nЩёки, виски, лоб… всё становится чуть мягче вместе с челюстью. Маленькие мышцы лица отпускают одна за другой.\n\nКогда в течение дня заметишь, что сжимаешь челюсть, вспомни этот шаг. Зубы разомкнуты, язык у нёба, один долгий выдох. Нескольких секунд достаточно.\n\nДавай ещё один круг. Зубы разомкнуты. Язык у нёба. Вдох… и выдох. На этот раз на выдохе заметь, как смягчаются и губы. Уголки рта расслабляются.\n\nПобудь немного в этой мягкости. Челюсть тяжёлая и спокойная. Лицо отдыхает. Когда захочется, открой глаза и возвращайся к своему дню с этим мягким лицом.",
  },
  "c10.body": {
    tr: "Bugünün küçük adımı kapı. Gözlerle bir şeyin kenarlarını yavaşça takip etmek dikkati toplar ve zihni sakinleştirir.\n\nBulunduğun odada rahatça otur. Bir nefes al ve gözlerini odanın kapısına çevir.\n\nOdanın kapısına bak. Gözlerinle kapının dört kenarını yavaşça takip et: üst, yan, alt ve diğer yan.\n\nÖnce üst kenardan başla. Sol köşeden sağ köşeye kadar gözlerinle yavaşça ilerle. Acele etme. Sanki bir kalemle çizgiyi yeniden çiziyormuşsun gibi.\n\nSağ köşeye geldiğinde aşağı dön. Kapının sağ kenarı boyunca yavaşça in. Menteşeleri ya da kolu fark edebilirsin.\n\nAlt kenara geldiğinde sola dön. Kapının eşiği, zeminle buluştuğu çizgi. Belki alttan hafif bir ışık sızıyor.\n\nSonra sol kenar boyunca yukarı çık ve başladığın köşeye dön. Dört kenar, bir dikdörtgen. Bitti.\n\nBir nefes al ve ver. Şimdi bir tur daha yap, bu kez nefesinle birlikte. Üst kenarda nefes al, sağ kenarda ver. Alt kenarda al, sol kenarda ver.\n\nKapı yerinde, sağlam, hareket etmiyor. Oda yerinde. Sen de buradasın, bu odanın içinde.\n\nGün içinde zihnin dağıldığında, herhangi bir kapı, pencere ya da çerçeveyle bu adımı yapabilirsin. Dört kenar, dört nefes.\n\nBir tur daha, bu kez daha da yavaş. Üst kenar… sağ kenar… alt kenar… sol kenar. Her köşede bir an dur.\n\nGözlerini kapıdan alıp odanın geri kalanına bak. Duvarlar, pencere, tavan. Her şey yerinde. Bir nefes al ve ver.",
    en: "Today's small step is the door. Slowly tracing the edges of something with your eyes gathers your attention and calms the mind.\n\nSit comfortably in the room you are in. Take a breath and turn your eyes towards the door.\n\nLook at the door of the room. With your eyes, slowly trace its four edges: the top, one side, the bottom, the other side.\n\nStart at the top edge. Move your eyes slowly from the left corner to the right corner. Do not hurry. As if you were drawing the line again with a pencil.\n\nWhen you reach the right corner, turn downwards. Move slowly down the right side of the door. You might notice the hinges or the handle.\n\nWhen you reach the bottom edge, turn left. The threshold, the line where the door meets the floor. Perhaps a little light seeps in underneath.\n\nThen go up the left side and back to the corner where you started. Four edges, one rectangle. Done.\n\nTake a breath and let it out. Now do one more round, this time with your breath. Breathe in along the top edge, out along the right side. In along the bottom, out along the left.\n\nThe door is in its place, solid, not moving. The room is in its place. And you are here, inside this room.\n\nWhenever your mind feels scattered during the day, you can do this step with any door, window or frame. Four edges, four breaths.\n\nOne more round, even more slowly. Top edge… right side… bottom edge… left side. Pause for a moment at each corner.\n\nTake your eyes from the door and look at the rest of the room. The walls, the window, the ceiling. Everything is in its place. Take a breath and let it out.",
    az: "Bugünün kiçik addımı qapıdır. Gözlərlə bir şeyin kənarlarını yavaşca izləmək diqqəti toplayır və ağlı sakitləşdirir.\n\nOlduğun otaqda rahat otur. Bir nəfəs al və gözlərini otağın qapısına çevir.\n\nOtağın qapısına bax. Gözlərinlə qapının dörd kənarını yavaşca izlə: üst, yan, alt və o biri yan.\n\nƏvvəlcə üst kənardan başla. Sol küncdən sağ küncə qədər gözlərinlə yavaşca irəlilə. Tələsmə. Sanki xətti yenidən qələmlə çəkirsən.\n\nSağ küncə çatanda aşağı dön. Qapının sağ kənarı boyu yavaşca en. Rəzələri və ya dəstəyi görə bilərsən.\n\nAlt kənara çatanda sola dön. Qapının astanası, döşəmə ilə birləşdiyi xətt. Bəlkə altından yüngül bir işıq süzülür.\n\nSonra sol kənar boyu yuxarı qalx və başladığın küncə qayıt. Dörd kənar, bir düzbucaqlı. Bitdi.\n\nBir nəfəs al və ver. İndi bir dövrə də et, bu dəfə nəfəsinlə birlikdə. Üst kənarda nəfəs al, sağ kənarda ver. Alt kənarda al, sol kənarda ver.\n\nQapı yerindədir, möhkəmdir, tərpənmir. Otaq yerindədir. Sən də buradasan, bu otağın içində.\n\nGün ərzində ağlın dağılanda istənilən qapı, pəncərə və ya çərçivə ilə bu addımı edə bilərsən. Dörd kənar, dörd nəfəs.\n\nBir dövrə də, bu dəfə daha da yavaş. Üst kənar… sağ kənar… alt kənar… sol kənar. Hər küncdə bir an dayan.\n\nGözlərini qapıdan çək və otağın qalan hissəsinə bax. Divarlar, pəncərə, tavan. Hər şey yerindədir. Bir nəfəs al və ver.",
    ru: "Сегодняшний маленький шаг — дверь. Если медленно обводить взглядом края чего-то, внимание собирается, а ум успокаивается.\n\nСядь удобно в комнате, где ты находишься. Сделай вдох и переведи взгляд на дверь.\n\nПосмотри на дверь комнаты. Глазами медленно обведи её четыре края: верх, одна сторона, низ, другая сторона.\n\nНачни с верхнего края. Медленно веди взгляд от левого угла к правому. Не спеши. Как будто заново проводишь линию карандашом.\n\nДойдя до правого угла, поверни вниз. Медленно спускайся вдоль правой стороны двери. Можно заметить петли или ручку.\n\nДойдя до нижнего края, поверни влево. Порог, линия, где дверь встречается с полом. Может быть, снизу пробивается немного света.\n\nПотом поднимись по левой стороне и вернись в угол, откуда начинал взгляд. Четыре края, один прямоугольник. Готово.\n\nСделай вдох и выдох. Теперь ещё один круг, на этот раз вместе с дыханием. Вдох вдоль верхнего края, выдох вдоль правого. Вдох вдоль нижнего, выдох вдоль левого.\n\nДверь на своём месте, прочная, неподвижная. Комната на своём месте. И ты здесь, внутри этой комнаты.\n\nКогда в течение дня мысли разбегаются, этот шаг можно сделать с любой дверью, окном или рамой. Четыре края, четыре дыхания.\n\nЕщё один круг, ещё медленнее. Верхний край… правая сторона… нижний край… левая сторона. В каждом углу останавливайся на мгновение.\n\nОтведи взгляд от двери и посмотри на остальную комнату. Стены, окно, потолок. Всё на своих местах. Вдох и выдох.",
  },
  "c11.body": {
    tr: "Bugünün küçük adımı sırt. Çoğu zaman oturduğumuzda bile sırtımızı tam yaslamayız; sanki her an kalkmaya hazırmışız gibi. Bugün sırtına destek vereceğiz.\n\nArkası olan bir sandalye bul ya da bir duvarın önüne otur. Bir nefes al ve yavaşça ver.\n\nSırtını sandalyeye ya da duvara yasla. Bütün ağırlığını bırak ve sandalyenin seni taşımasına izin ver.\n\nÖnce belini yasla. Sonra sırtının ortasını. Sonra kürek kemiklerini. Omurganın her bölümünün sandalyeye ya da duvara değdiğini hisset.\n\nBaşını da yaslayabiliyorsan yasla. Yaslayamıyorsan, başını omurganın üstünde dengede tut ve boynunu gevşet.\n\nŞimdi ağırlığını bırak. Sanki sırtın biraz daha ağırlaşıyor ve sandalye onu kolayca taşıyor. Sandalye bunun için var.\n\nNefes alırken sırtının destekle buluştuğu yerin biraz genişlediğini fark et. Nefes verirken bütün sırtın biraz daha yerleşiyor.\n\nOmuzların yaslandığın yüzeye doğru iniyor. Kolların ağırlaşıyor. Ellerin kucağında ya da dizlerinde dinleniyor.\n\nBirkaç nefes böyle kal. Kalkmana, bir yere yetişmene gerek yok. Şu an sadece desteklenmeyi deneyimliyorsun.\n\nGün içinde ne zaman otursan, sırtını tam yaslamayı hatırla. Bir nefes boyunca desteğin seni taşımasına izin ver.\n\nBir kez daha bütün sırtını tara. Bel, sırtın ortası, kürek kemikleri, ense. Hâlâ yaslanıyor musun, yoksa farkında olmadan öne mi eğildin? Varsa, yeniden yaslan.\n\nBirkaç nefes daha. Al… ve verirken sandalyeye biraz daha teslim ol. Destek orada, sen de buradasın.",
    en: "Today's small step is your back. Often, even when we sit, we do not fully lean back; as if ready to get up at any moment. Today we will give your back some support.\n\nFind a chair with a back, or sit in front of a wall. Take a breath and let it out slowly.\n\nLean your back against the chair or a wall. Let go of all your weight and let the chair carry you.\n\nFirst, lean your lower back against it. Then the middle of your back. Then your shoulder blades. Feel each part of your spine touching the chair or the wall.\n\nIf you can rest your head too, do. If not, balance your head on top of your spine and let your neck relax.\n\nNow let go of your weight. As if your back were getting a little heavier, and the chair were carrying it easily. That is what the chair is for.\n\nAs you breathe in, notice the place where your back meets the support widening a little. As you breathe out, your whole back settles a little more.\n\nYour shoulders sink towards the surface behind you. Your arms grow heavy. Your hands rest in your lap or on your knees.\n\nStay like this for a few breaths. You do not need to get up or get anywhere. Right now you are simply experiencing being supported.\n\nWhenever you sit down during the day, remember to lean back fully. For one breath, let the support carry you.\n\nScan your whole back once more. Lower back, middle back, shoulder blades, the back of your neck. Are you still leaning back, or have you drifted forward without noticing? If so, lean back again.\n\nA few more breaths. In… and as you breathe out, give yourself a little more to the chair. The support is there, and you are here.",
    az: "Bugünün kiçik addımı kürəkdir. Çox vaxt oturanda belə kürəyimizi tam söykəmirik; sanki hər an qalxmağa hazırıq. Bu gün kürəyinə dəstək verəcəyik.\n\nSöykənəcəyi olan bir stul tap və ya divarın qabağında otur. Bir nəfəs al və yavaşca ver.\n\nKürəyini stula və ya divara söykə. Bütün ağırlığını burax və qoy stul səni saxlasın.\n\nƏvvəlcə belini söykə. Sonra kürəyinin ortasını. Sonra kürək sümüklərini. Onurğanın hər hissəsinin stula və ya divara toxunduğunu hiss et.\n\nBaşını da söykəyə bilirsənsə, söykə. Bacarmırsansa, başını onurğanın üstündə tarazlıqda saxla və boynunu boşalt.\n\nİndi ağırlığını burax. Sanki kürəyin bir az da ağırlaşır və stul onu asanlıqla saxlayır. Stul elə bunun üçündür.\n\nNəfəs alanda kürəyinin dəstəklə qovuşduğu yerin bir az genişləndiyini hiss et. Nəfəs verəndə bütün kürəyin bir az da yerləşir.\n\nÇiyinlərin söykəndiyin səthə doğru enir. Qolların ağırlaşır. Əllərin qucağında və ya dizlərində dincəlir.\n\nBir neçə nəfəs belə qal. Qalxmağa, haraya isə çatmağa ehtiyac yoxdur. İndi sadəcə dəstəklənməyi yaşayırsan.\n\nGün ərzində nə vaxt otursan, kürəyini tam söykəməyi xatırla. Bir nəfəs boyu qoy dəstək səni saxlasın.\n\nBütün kürəyini bir dəfə də nəzərdən keçir. Bel, kürəyin ortası, kürək sümükləri, boynun arxası. Hələ söykənirsən, yoxsa fərqinə varmadan irəli əyilmisən? Əgər belədirsə, yenidən söykən.\n\nBir neçə nəfəs də. Al… və verəndə özünü stula bir az da tapşır. Dəstək oradadır, sən də buradasan.",
    ru: "Сегодняшний маленький шаг — спина. Часто, даже сидя, мы не опираемся спиной полностью, как будто готовы в любую секунду встать. Сегодня мы дадим спине опору.\n\nНайди стул со спинкой или сядь у стены. Сделай вдох и медленный выдох.\n\nОбопрись спиной о стул или стену. Отпусти весь свой вес и позволь стулу держать тебя.\n\nСначала обопрись поясницей. Потом серединой спины. Потом лопатками. Почувствуй, как каждая часть позвоночника касается спинки стула или стены.\n\nЕсли можно опереть и голову, обопри. Если нет, держи голову в равновесии над позвоночником и расслабь шею.\n\nТеперь отпусти вес. Как будто спина становится чуть тяжелее, а стул легко её держит. Для этого стул и нужен.\n\nНа вдохе заметь, как место, где спина встречается с опорой, немного расширяется. На выдохе вся спина устраивается чуть глубже.\n\nПлечи опускаются к поверхности за спиной. Руки тяжелеют. Ладони отдыхают на коленях.\n\nПобудь так несколько вдохов. Не нужно вставать или куда-то успевать. Сейчас ты просто проживаешь, каково это — получать опору.\n\nКаждый раз, когда садишься в течение дня, вспоминай, что можно полностью опереться спиной. Хотя бы на один вдох позволь опоре держать тебя.\n\nЕщё раз пройдись вниманием по всей спине. Поясница, середина спины, лопатки, затылок. Ты всё ещё опираешься или незаметно наклоняешься вперёд? Если да, снова обопрись.\n\nЕщё несколько вдохов. Вдох… и на выдохе отдайся стулу чуть больше. Опора есть, и ты здесь.",
  },
  "c12.body": {
    tr: "Bugünün küçük adımı üç teşekkür. Zihin doğası gereği sorunlara daha çok dikkat eder. Küçük iyi şeyleri bilerek aramak, bu dengeyi biraz düzeltir.\n\nRahatça otur. Gözlerini kapatabilirsin. Bir nefes al ve yavaşça ver.\n\nBugün sana iyi gelen üç küçük ve somut şeyi düşün. Büyük olmalarına gerek yok. Sonra derin bir nefes al.\n\nBirincisiyle başla. Belki sabah içtiğin sıcak bir içecek. Belki pencereden gelen ışık. Onu zihninde canlandır. Neredeydin? Ne hissettin?\n\nŞimdi ikincisi. Belki biri sana gülümsedi, belki bir mesaj geldi, belki sevdiğin bir şarkı çaldı. Küçük ve somut olsun.\n\nVe üçüncüsü. Belki şu an, şu nefes. Sırtını taşıyan sandalye. Bu birkaç dakikayı kendine ayırman.\n\nÜç şeyi bir arada düşün. Sanki üç küçük taşı avucunda tutuyormuşsun gibi. Ağır değiller, ama oradalar.\n\nŞimdi derin bir nefes al. Göğsünü hafifçe genişlet. Ve yavaşça ver. Bu üç şeyi göğsünde taşıdığını hayal et.\n\nZor bir gün geçiriyor olabilirsin. Bu teşekkürler zorluğu silmez. Ama yanına küçük bir ışık koyar.\n\nAkşam yatmadan önce bu üç şeyi bir kez daha hatırlayabilirsin. Ya da yarın yeni üç şey bulabilirsin.\n\nŞimdi üç şeyden birini seç, en sıcak geleni. Onu bir kez daha zihninde canlandır. Ayrıntılarını gör. Rengini, sesini, sıcaklığını.\n\nBu anı bir nefes boyunca tut. Al… ve ver. Hazır olduğunda gözlerini aç ve gününe bu küçük sıcaklıkla dön.",
    en: "Today's small step is three thanks. By nature, the mind pays more attention to problems. Deliberately looking for small good things corrects that balance a little.\n\nSit comfortably. You can close your eyes. Take a breath and let it out slowly.\n\nThink of three small, concrete things that did you good today. They do not need to be big. Then take a deep breath.\n\nStart with the first one. Perhaps a warm drink you had this morning. Perhaps the light from the window. Picture it in your mind. Where were you? What did you feel?\n\nNow the second one. Perhaps someone smiled at you, perhaps a message arrived, perhaps a song you love came on. Let it be small and concrete.\n\nAnd the third. Perhaps this moment, this breath. The chair holding your back. Giving yourself these few minutes.\n\nThink of the three things together. As if you were holding three small stones in your palm. They are not heavy, but they are there.\n\nNow take a deep breath. Let your chest widen a little. And breathe out slowly. Imagine carrying these three things in your chest.\n\nYou may be having a hard day. These thanks do not erase the difficulty. But they place a small light beside it.\n\nIn the evening, before bed, you can remember these three things once more. Or tomorrow you can find three new ones.\n\nNow choose one of the three, the one that feels warmest. Picture it once more. See its details. Its colour, its sound, its warmth.\n\nHold this moment for one breath. In… and out. When you are ready, open your eyes and return to your day with this small warmth.",
    az: "Bugünün kiçik addımı üç təşəkkürdür. Ağıl təbiətcə problemlərə daha çox diqqət edir. Kiçik yaxşı şeyləri bilərəkdən axtarmaq bu tarazlığı bir az düzəldir.\n\nRahat otur. Gözlərini yuma bilərsən. Bir nəfəs al və yavaşca ver.\n\nBu gün sənə xoş gələn üç kiçik və konkret şeyi düşün. Böyük olmalarına ehtiyac yoxdur. Sonra dərin nəfəs al.\n\nBirincisi ilə başla. Bəlkə səhər içdiyin isti bir içki. Bəlkə pəncərədən gələn işıq. Onu ağlında canlandır. Harada idin? Nə hiss etdin?\n\nİndi ikincisi. Bəlkə kimsə sənə gülümsədi, bəlkə bir mesaj gəldi, bəlkə sevdiyin bir mahnı səsləndi. Kiçik və konkret olsun.\n\nVə üçüncüsü. Bəlkə elə bu an, bu nəfəs. Kürəyini saxlayan stul. Bu bir neçə dəqiqəni özünə ayırman.\n\nÜç şeyi birlikdə düşün. Sanki ovucunda üç kiçik daş tutursan. Ağır deyillər, amma oradadırlar.\n\nİndi dərin bir nəfəs al. Sinəni yüngülcə genişləndir. Və yavaşca ver. Bu üç şeyi sinəndə daşıdığını təsəvvür et.\n\nÇətin bir gün keçirə bilərsən. Bu təşəkkürlər çətinliyi silmir. Amma onun yanına kiçik bir işıq qoyur.\n\nAxşam yatmazdan əvvəl bu üç şeyi bir dəfə də xatırlaya bilərsən. Ya da sabah yeni üç şey tapa bilərsən.\n\nİndi üç şeydən birini seç, ən isti gələni. Onu bir dəfə də ağlında canlandır. Təfərrüatlarını gör. Rəngini, səsini, istiliyini.\n\nBu anı bir nəfəs boyu saxla. Al… və ver. Hazır olanda gözlərini aç və gününə bu kiçik istiliklə qayıt.",
    ru: "Сегодняшний маленький шаг — три благодарности. По своей природе ум больше замечает проблемы. Если намеренно искать маленькие хорошие вещи, баланс немного выравнивается.\n\nСядь удобно. Можно закрыть глаза. Сделай вдох и медленный выдох.\n\nВспомни три маленькие конкретные вещи, которые сегодня были тебе в радость. Им не нужно быть большими. Потом глубоко вдохни.\n\nНачни с первой. Может быть, тёплый напиток утром. Может быть, свет из окна. Представь это. Где это было? Что при этом чувствовалось?\n\nТеперь вторая. Может быть, кто-то тебе улыбнулся, пришло сообщение, зазвучала любимая песня. Пусть это будет маленьким и конкретным.\n\nИ третья. Может быть, этот самый момент, этот вдох. Стул, который держит спину. То, что ты даришь себе эти несколько минут.\n\nПодумай обо всех трёх вместе. Как будто держишь на ладони три маленьких камешка. Они не тяжёлые, но они есть.\n\nТеперь сделай глубокий вдох. Пусть грудь немного расширится. И медленно выдохни. Представь, что эти три вещи хранятся у тебя в груди.\n\nВозможно, день трудный. Эти благодарности не стирают трудностей. Но они ставят рядом маленький огонёк.\n\nВечером перед сном можно вспомнить эти три вещи ещё раз. А завтра найти три новые.\n\nТеперь выбери одну из трёх, самую тёплую. Представь её ещё раз. Увидь детали. Её цвет, звук, тепло.\n\nУдержи этот момент на один вдох. Вдох… и выдох. Когда захочется, открой глаза и возвращайся к своему дню с этим маленьким теплом.",
  },
  "c13.body": {
    tr: "Bugünün küçük adımı endişeyi rafa koymak. Bazı endişeler hemen çözülemez. Ama onları sürekli zihninde taşımak zorunda değilsin.\n\nRahatça otur. Bir nefes al ve yavaşça ver. Şu an seni en çok meşgul eden endişeyi düşün.\n\nSeni meşgul eden endişeyi tek bir cümleye sığdır. Sonra onu zihninde bir rafa koyduğunu hayal et. Yarın oradan alabilirsin.\n\nCümleyi kurarken kısa tut. “Yarınki toplantıdan endişeliyim.” “Para konusunda kaygılıyım.” Ayrıntılara girme. Tek bir cümle.\n\nŞimdi zihninde bir raf hayal et. Ahşap, sağlam, göz hizanda. Belki bir kütüphanede, belki evinde. Rafın rengini, dokusunu gör.\n\nEndişe cümleni küçük bir kâğıda yazdığını hayal et. Kâğıdı katla. Sonra yavaşça rafa koy. Raf onu taşıyor.\n\nBir adım geri çekil. Raf orada, kâğıt orada. Endişe kaybolmadı, ama artık elinde değil. İhtiyacın olduğunda onu oradan alabilirsin.\n\nBir nefes al ve ver. Ellerini aç ve boş olduklarını hisset. Omuzlarını bırak.\n\nEndişe yeniden aklına gelirse, nazikçe kendine söyle: “Rafta. Yarın alacağım.” Ve dikkatini şu ana geri getir.\n\nBu adımı birden fazla endişe için de yapabilirsin. Her birine ayrı bir kâğıt, aynı sağlam raf.\n\nRaftaki kâğıda bir kez daha bak. Katlanmış, sessiz. Sonra rafa sırtını dön ve odanın içine bak. Burada başka şeyler de var.\n\nBir nefes al ve ver. Ellerin boş, omuzların hafif. Endişe rafta, sen buradasın.",
    en: "Today's small step is putting a worry on the shelf. Some worries cannot be solved right away. But you do not have to carry them in your mind all the time.\n\nSit comfortably. Take a breath and let it out slowly. Think of the worry that is occupying you most right now.\n\nFit the worry on your mind into a single sentence. Then imagine placing it on a shelf in your mind. You can pick it up from there tomorrow.\n\nKeep the sentence short. “I am worried about tomorrow's meeting.” “I am anxious about money.” Do not go into details. Just one sentence.\n\nNow imagine a shelf in your mind. Wooden, sturdy, at eye level. Perhaps in a library, perhaps in your home. See the colour and texture of the shelf.\n\nImagine writing your worry sentence on a small piece of paper. Fold the paper. Then slowly place it on the shelf. The shelf holds it.\n\nTake a step back. The shelf is there, the paper is there. The worry has not disappeared, but it is no longer in your hands. When you need it, you can take it down from there.\n\nTake a breath and let it out. Open your hands and feel that they are empty. Let your shoulders go.\n\nIf the worry comes back to mind, gently tell yourself: “It is on the shelf. I will take it down tomorrow.” And bring your attention back to this moment.\n\nYou can do this for more than one worry. A separate piece of paper for each, the same sturdy shelf.\n\nLook at the paper on the shelf once more. Folded, quiet. Then turn your back to the shelf and look into the room. There are other things here too.\n\nTake a breath and let it out. Your hands are empty, your shoulders are light. The worry is on the shelf, and you are here.",
    az: "Bugünün kiçik addımı narahatlığı rəfə qoymaqdır. Bəzi narahatlıqları dərhal həll etmək olmur. Amma onları daim ağlında daşımaq məcburiyyətində deyilsən.\n\nRahat otur. Bir nəfəs al və yavaşca ver. İndi səni ən çox məşğul edən narahatlığı düşün.\n\nSəni məşğul edən narahatlığı tək bir cümləyə sığdır. Sonra onu ağlında bir rəfə qoyduğunu təsəvvür et. Sabah oradan götürə bilərsən.\n\nCümləni qısa saxla. “Sabahkı görüşdən narahatam.” “Pul məsələsi məni narahat edir.” Təfərrüata varma. Tək bir cümlə.\n\nİndi ağlında bir rəf təsəvvür et. Taxta, möhkəm, göz səviyyəsində. Bəlkə bir kitabxanada, bəlkə evində. Rəfin rəngini, toxumasını gör.\n\nNarahatlıq cümləni kiçik bir kağıza yazdığını təsəvvür et. Kağızı qatla. Sonra yavaşca rəfə qoy. Rəf onu saxlayır.\n\nBir addım geri çəkil. Rəf orada, kağız orada. Narahatlıq yox olmadı, amma artıq sənin əlində deyil. Lazım olanda onu oradan götürə bilərsən.\n\nBir nəfəs al və ver. Əllərini aç və boş olduqlarını hiss et. Çiyinlərini burax.\n\nNarahatlıq yenidən ağlına gəlsə, özünə yumşaqca de: “Rəfdədir. Sabah götürəcəyəm.” Və diqqətini bu ana qaytar.\n\nBu addımı bir neçə narahatlıq üçün də edə bilərsən. Hər birinə ayrı kağız, eyni möhkəm rəf.\n\nRəfdəki kağıza bir dəfə də bax. Qatlanıb, səssizdir. Sonra rəfə arxa çevir və otağın içinə bax. Burada başqa şeylər də var.\n\nBir nəfəs al və ver. Əllərin boş, çiyinlərin yüngüldür. Narahatlıq rəfdədir, sən isə buradasan.",
    ru: "Сегодняшний маленький шаг — положить тревогу на полку. Некоторые тревоги нельзя решить сразу. Но и носить их в голове всё время не обязательно.\n\nСядь удобно. Сделай вдох и медленный выдох. Подумай о тревоге, которая сейчас занимает тебя больше всего.\n\nУложи тревогу, которая тебя занимает, в одно предложение. Потом представь, что кладёшь его на полку в уме. Завтра его можно будет оттуда взять.\n\nФраза должна быть короткой. «Меня тревожит завтрашняя встреча». «Я беспокоюсь о деньгах». Не уходи в подробности. Одно предложение.\n\nТеперь представь в уме полку. Деревянную, прочную, на уровне глаз. Может быть, в библиотеке, может быть, у тебя дома. Увидь её цвет и фактуру.\n\nПредставь, что записываешь свою фразу на маленьком листке. Сложи листок. Потом медленно положи его на полку. Полка его держит.\n\nОтступи на шаг. Полка там, листок там. Тревога не исчезла, но она больше не у тебя в руках. Когда понадобится, её можно оттуда взять.\n\nСделай вдох и выдох. Раскрой ладони и почувствуй, что они пусты. Отпусти плечи.\n\nЕсли тревога снова придёт в голову, мягко скажи себе: «Она на полке. Возьму завтра». И верни внимание в этот момент.\n\nТак можно сделать и с несколькими тревогами. Для каждой свой листок, полка та же, прочная.\n\nЕщё раз посмотри на листок на полке. Сложенный, тихий. Потом повернись к полке спиной и посмотри в комнату. Здесь есть и другое.\n\nВдох и выдох. Руки пусты, плечи лёгкие. Тревога на полке, а ты здесь.",
  },
  "c14.body": {
    tr: "Bugünün küçük adımı örtü. Bedenimiz sarılmayı, sıcak bir ağırlığı güvenle eşleştirir. Bir battaniye bile bu hissi verebilir.\n\nYakındaki bir battaniye, şal ya da kalın bir örtü al. Rahat bir yere otur ya da uzan.\n\nBir battaniye ya da örtü al ve üzerine ser. Ağırlığını ve bedenine değişini hisset. Bir süre öylece kal.\n\nÖrtüyü omuzlarına al ve önde birleştir. Ya da üzerine ser ve kenarlarını bedeninin altına sıkıştır. Sıkı olsun, ama rahat.\n\nAğırlığını hisset. Omuzlarında, sırtında, kollarında. Örtü bedenini her yönden hafifçe sarıyor.\n\nKumaşın dokusunu fark et. Yumuşak mı, pürüzlü mü? Parmaklarınla kenarına dokun. Yünün ya da pamuğun sıcaklığı yavaş yavaş artıyor.\n\nBir nefes al ve ver. Nefes alırken göğsünün örtünün altında yükseldiğini, verirken alçaldığını hisset.\n\nBir süre böyle kal. Hiçbir şey yapmana gerek yok. Sadece sarılmış, sıcak ve güvende.\n\nİstersen örtünün içinde kendine sarıl. Kollarını göğsünde çaprazla ve ellerini omuzlarına koy. Hafifçe bastır.\n\nGün içinde ya da yatmadan önce bunalmış hissettiğinde bu adımı hatırla. Bir örtü, bir nefes, birkaç dakika.\n\nÖrtünün içinde biraz daha kal. Kendine sarıldığın kollarını gevşet ve ellerini kucağına bırak. Örtü hâlâ seni sarıyor.\n\nBir nefes al ve ver. Sıcaklık, ağırlık, sessizlik. Hazır olduğunda örtüyü yavaşça aç ama bu sıcaklığı yanında götür.",
    en: "Today's small step is a blanket. Our bodies link being held, a warm weight, with safety. Even a blanket can give that feeling.\n\nTake a blanket, a shawl or a thick throw that is nearby. Sit or lie down somewhere comfortable.\n\nTake a blanket or a throw and spread it over yourself. Feel its weight and the way it touches your body. Stay like this for a while.\n\nWrap the blanket around your shoulders and bring it together at the front. Or spread it over you and tuck the edges under your body. Snug, but comfortable.\n\nFeel its weight. On your shoulders, your back, your arms. The blanket is gently wrapping your body from every side.\n\nNotice the texture of the fabric. Soft or rough? Touch its edge with your fingers. The warmth of the wool or cotton is slowly growing.\n\nTake a breath and let it out. As you breathe in, feel your chest rising under the blanket; as you breathe out, feel it falling.\n\nStay like this for a while. There is nothing you need to do. Just wrapped, warm and safe.\n\nIf you like, give yourself a hug inside the blanket. Cross your arms over your chest and rest your hands on your shoulders. Press gently.\n\nWhenever you feel overwhelmed during the day or before bed, remember this step. A blanket, a breath, a few minutes.\n\nStay inside the blanket a little longer. Loosen the arms you wrapped around yourself and let your hands rest in your lap. The blanket is still holding you.\n\nTake a breath and let it out. Warmth, weight, quiet. When you are ready, slowly open the blanket, but take this warmth with you.",
    az: "Bugünün kiçik addımı örtükdür. Bədənimiz qucaqlanmağı, isti bir ağırlığı təhlükəsizliklə bağlayır. Bir yorğan belə bu hissi verə bilər.\n\nYaxındakı bir yorğan, şal və ya qalın örtük götür. Rahat bir yerdə otur və ya uzan.\n\nBir yorğan və ya örtük götür və üstünə sal. Onun ağırlığını və bədəninə toxunuşunu hiss et. Bir müddət belə qal.\n\nÖrtüyü çiyinlərinə sal və qabaqda birləşdir. Ya da üstünə sər və kənarlarını bədəninin altına sıxışdır. Sıx olsun, amma rahat.\n\nAğırlığını hiss et. Çiyinlərində, kürəyində, qollarında. Örtük bədənini hər tərəfdən yüngülcə bürüyür.\n\nParçanın toxumasına diqqət et. Yumşaqdır, yoxsa kələ-kötür? Barmaqlarınla kənarına toxun. Yunun və ya pambığın istiliyi yavaş-yavaş artır.\n\nBir nəfəs al və ver. Nəfəs alanda sinənin örtüyün altında qalxdığını, verəndə endiyini hiss et.\n\nBir müddət belə qal. Heç nə etməyə ehtiyac yoxdur. Sadəcə bürünmüş, isti və təhlükəsiz.\n\nİstəsən, örtüyün içində özünü qucaqla. Qollarını sinənin üstündə çarpazla və əllərini çiyinlərinə qoy. Yüngülcə sıx.\n\nGün ərzində və ya yatmazdan əvvəl bunaldığını hiss edəndə bu addımı xatırla. Bir örtük, bir nəfəs, bir neçə dəqiqə.\n\nÖrtüyün içində bir az da qal. Özünü qucaqladığın qollarını boşalt və əllərini qucağına burax. Örtük hələ də səni bürüyür.\n\nBir nəfəs al və ver. İstilik, ağırlıq, sükut. Hazır olanda örtüyü yavaşca aç, amma bu istiliyi özünlə apar.",
    ru: "Сегодняшний маленький шаг — плед. Тело связывает объятия, тёплую тяжесть, с безопасностью. Даже плед может дать это ощущение.\n\nВозьми плед, шаль или плотное покрывало, которое рядом. Сядь или ляг удобно.\n\nВозьми плед или одеяло и укройся. Почувствуй его вес и то, как он касается тела. Побудь так немного.\n\nНакинь плед на плечи и соедини края спереди. Или укройся и подоткни края под себя. Плотно, но удобно.\n\nПочувствуй его вес. На плечах, на спине, на руках. Плед мягко обнимает тело со всех сторон.\n\nЗаметь фактуру ткани. Мягкая или шершавая? Коснись края пальцами. Тепло шерсти или хлопка понемногу нарастает.\n\nВдох и выдох. На вдохе почувствуй, как грудь поднимается под пледом, на выдохе — как опускается.\n\nПобудь так немного. Ничего делать не нужно. Просто укутанность, тепло и безопасность.\n\nЕсли хочется, обними себя внутри пледа. Скрести руки на груди и положи ладони на плечи. Слегка прижми.\n\nКогда в течение дня или перед сном всё наваливается, вспомни этот шаг. Плед, вдох, несколько минут.\n\nПобудь в пледе ещё немного. Ослабь руки, которыми обнимаешь себя, и положи ладони на колени. Плед всё ещё укрывает тебя.\n\nВдох и выдох. Тепло, тяжесть, тишина. Когда захочется, медленно раскройся, но возьми это тепло с собой.",
  },
  "c15.body": {
    tr: "Bugünün küçük adımı üç renk. Sesli söylemek hem gözlerini hem sesini çalıştırır. Zihin bu ikisini aynı anda yaparken endişeye daha az yer kalır.\n\nRahatça otur ve bir nefes al. Etrafına yavaşça bak.\n\nEtrafında üç eşya seç ve her birinin rengini yüksek sesle söyle. Mavi fincan, yeşil bitki, beyaz duvar…\n\nBirinci eşyayı seçtiğinde ona bak ve rengini söyle. Sesinin odada nasıl duyulduğunu fark et. Sonra eşyanın adını ekle.\n\nŞimdi ikinci eşya. Farklı bir renk seç. Gözlerin odada biraz gezinsin. Bulduğunda dur ve söyle.\n\nVe üçüncüsü. Belki tavana, belki yere, belki pencereden dışarı bak. Bir renk daha. Söyle.\n\nBir nefes al ve ver. Şimdi üç rengi sırayla bir kez daha söyle, her birinde gözlerini o eşyaya çevir.\n\nİstersen bir tur daha yap, bu kez daha yavaş. Her rengin tonuna dikkat et. Mavi, ama hangi mavi? Açık mı, koyu mu, griye çalan mı?\n\nGözlerini bir an kapat ve üç rengi hatırla. Sonra aç ve yeniden bul. Hepsi yerinde.\n\nGün içinde bunaldığında etrafındaki üç rengi sesli ya da içinden söyle. Üç renk, bir nefes.\n\nŞimdi bir dördüncü renk bul. Belki kendi giysinde, belki elinde. Söyle. Sonra beşincisi, gözünün en son takıldığı yer.\n\nBir nefes al ve ver. Odada birçok renk var ve sen hepsinin ortasındasın. Burada, şimdi.",
    en: "Today's small step is three colours. Saying them out loud uses both your eyes and your voice. When the mind is doing both at once, there is less room for worry.\n\nSit comfortably and take a breath. Look slowly around you.\n\nChoose three objects around you and say each color out loud. Blue cup, green plant, white wall…\n\nWhen you choose the first object, look at it and say its colour. Notice how your voice sounds in the room. Then add the name of the object.\n\nNow the second object. Choose a different colour. Let your eyes wander around the room a little. When you find it, stop and say it.\n\nAnd the third. Perhaps look at the ceiling, perhaps the floor, perhaps out of the window. One more colour. Say it.\n\nTake a breath and let it out. Now say the three colours in order once more, turning your eyes to each object as you do.\n\nIf you like, do one more round, more slowly this time. Pay attention to the shade of each colour. Blue, but which blue? Light, dark, greyish?\n\nClose your eyes for a moment and remember the three colours. Then open them and find them again. They are all in their places.\n\nWhenever you feel overwhelmed during the day, name three colours around you, out loud or silently. Three colours, one breath.\n\nNow find a fourth colour. Perhaps on your own clothes, perhaps in your hand. Say it. Then a fifth, wherever your eyes land last.\n\nTake a breath and let it out. There are many colours in the room, and you are in the middle of them all. Here, now.",
    az: "Bugünün kiçik addımı üç rəngdir. Ucadan demək həm gözlərini, həm səsini işlədir. Ağıl ikisini eyni anda edəndə narahatlığa daha az yer qalır.\n\nRahat otur və bir nəfəs al. Ətrafına yavaşca bax.\n\nƏtrafında üç əşya seç və hər birinin rəngini ucadan de. Mavi fincan, yaşıl gül, ağ divar…\n\nBirinci əşyanı seçəndə ona bax və rəngini de. Səsinin otaqda necə eşidildiyinə fikir ver. Sonra əşyanın adını əlavə et.\n\nİndi ikinci əşya. Fərqli bir rəng seç. Qoy gözlərin otaqda bir az gəzsin. Tapanda dayan və de.\n\nVə üçüncüsü. Bəlkə tavana, bəlkə döşəməyə, bəlkə pəncərədən bayıra bax. Bir rəng də. De.\n\nBir nəfəs al və ver. İndi üç rəngi ardıcıllıqla bir dəfə də de, hər birində gözlərini həmin əşyaya çevir.\n\nİstəsən, bir dəfə də et, bu dəfə daha yavaş. Hər rəngin çalarına diqqət et. Mavi, amma hansı mavi? Açıq, tünd, boza çalan?\n\nGözlərini bir anlıq yum və üç rəngi xatırla. Sonra aç və onları yenidən tap. Hamısı yerindədir.\n\nGün ərzində bunalanda ətrafındakı üç rəngi ucadan və ya içində de. Üç rəng, bir nəfəs.\n\nİndi dördüncü bir rəng tap. Bəlkə öz paltarında, bəlkə əlində. De. Sonra beşincisini, gözünün ən son düşdüyü yerdə.\n\nBir nəfəs al və ver. Otaqda çoxlu rəng var və sən hamısının ortasındasan. Burada, indi.",
    ru: "Сегодняшний маленький шаг — три цвета. Если называть их вслух, работают и глаза, и голос. Когда ум делает и то и другое сразу, для тревоги остаётся меньше места.\n\nСядь удобно и сделай вдох. Медленно оглядись.\n\nВыбери три предмета вокруг и вслух назови цвет каждого. Синяя чашка, зелёное растение, белая стена…\n\nВыбрав первый предмет, посмотри на него и назови его цвет. Заметь, как звучит голос в комнате. Потом добавь название предмета.\n\nТеперь второй предмет. Выбери другой цвет. Пусть взгляд немного поблуждает по комнате. Когда найдёшь, остановись и назови.\n\nИ третий. Может быть, посмотри на потолок, на пол или в окно. Ещё один цвет. Назови его.\n\nВдох и выдох. Теперь ещё раз назови три цвета по порядку, каждый раз переводя взгляд на предмет.\n\nЕсли хочется, сделай ещё один круг, на этот раз медленнее. Обрати внимание на оттенок каждого цвета. Синий, но какой синий? Светлый, тёмный, сероватый?\n\nНа мгновение закрой глаза и вспомни три цвета. Потом открой и найди их снова. Все на своих местах.\n\nКогда в течение дня всё наваливается, назови три цвета вокруг, вслух или про себя. Три цвета, один вдох.\n\nТеперь найди четвёртый цвет. Может быть, на своей одежде, может быть, в руке. Назови его. Потом пятый, там, куда в последний раз упал взгляд.\n\nВдох и выдох. В комнате много цветов, и ты посреди них всех. Здесь и сейчас.",
  },
  "c16.body": {
    tr: "Bugünün küçük adımı telefonun ağırlığı. Telefonlar genellikle zihnimizi başka yerlere götürür. Bugün onu tam tersine, seni şu ana getirmek için kullanacağız.\n\nRahatça otur. Telefonunu ekranı aşağı bakacak şekilde iki elinin arasına al. Bir nefes al ve yavaşça ver.\n\nTelefonunu iki elinle tut. On saniye boyunca sadece ağırlığını ve sıcaklığını hisset; ekrana bakma. Sonra bırak.\n\nAğırlığını hisset. Avuçlarına ne kadar bastırıyor? Bir elinden diğerine yavaşça aktar. Sonra yeniden iki elinle tut.\n\nSıcaklığına dikkat et. Arka yüzü serin mi, ılık mı? Ellerinin sıcaklığı ona geçiyor mu?\n\nKenarlarını parmaklarınla takip et. Köşeleri yuvarlak mı? Yüzeyi pürüzsüz mü, dokulu mu? Düğmeleri hisset ama basma.\n\nBir titreşim ya da bir ses gelirse, bakmadan fark et ve bırak. Bu birkaç saniye senin.\n\nBir nefes al ve ver. Ellerin telefonu tutuyor, ama dikkatin ekranda değil, ellerinde.\n\nŞimdi telefonu yavaşça masaya, ekranı aşağı bakacak şekilde bırak. Ellerin boşaldığında ne hissediyorsun? Hafiflik mi?\n\nGün içinde telefona uzandığını fark ettiğinde, bazen ekranı açmadan önce onu sadece birkaç saniye tut. Ağırlık, sıcaklık, bir nefes.\n\nTelefon masada dururken ellerini birbirine bastır. Az önce taşıdığın ağırlığın yerini şimdi kendi ellerinin sıcaklığı alıyor.\n\nBir nefes al ve ver. Telefon orada, bekleyebilir. Sen buradasın, bu nefeste.",
    en: "Today's small step is the weight of your phone. Phones usually take our minds somewhere else. Today we will use it the other way round, to bring you into this moment.\n\nSit comfortably. Hold your phone between both hands with the screen facing down. Take a breath and let it out slowly.\n\nHold your phone in both hands. For ten seconds, feel only its weight and warmth; do not look at the screen. Then put it down.\n\nFeel its weight. How much does it press into your palms? Pass it slowly from one hand to the other. Then hold it in both hands again.\n\nNotice its temperature. Is the back cool or warm? Is the warmth of your hands passing into it?\n\nTrace its edges with your fingers. Are the corners rounded? Is the surface smooth or textured? Feel the buttons, but do not press them.\n\nIf a vibration or a sound comes, notice it without looking, and let it go. These few seconds are yours.\n\nTake a breath and let it out. Your hands are holding the phone, but your attention is in your hands, not on the screen.\n\nNow slowly put the phone down on the table, screen facing down. What do you feel when your hands are empty? Lightness?\n\nDuring the day, when you notice yourself reaching for your phone, sometimes just hold it for a few seconds before opening the screen. Weight, warmth, one breath.\n\nWhile the phone rests on the table, press your hands together. The warmth of your own hands now takes the place of the weight you were holding.\n\nTake a breath and let it out. The phone is there; it can wait. You are here, in this breath.",
    az: "Bugünün kiçik addımı telefonun ağırlığıdır. Telefonlar adətən ağlımızı başqa yerlərə aparır. Bu gün onu əksinə, səni bu ana gətirmək üçün istifadə edəcəyik.\n\nRahat otur. Telefonunu ekranı aşağı baxmaqla iki əlinin arasına al. Bir nəfəs al və yavaşca ver.\n\nTelefonunu iki əlinlə tut. On saniyə ərzində sadəcə onun ağırlığını və istiliyini hiss et; ekrana baxma. Sonra yerə qoy.\n\nAğırlığını hiss et. Ovuclarına nə qədər basır? Onu yavaşca bir əlindən o birinə keçir. Sonra yenə iki əllə tut.\n\nTemperaturuna diqqət et. Arxa tərəfi sərindir, yoxsa ilıq? Əllərinin istiliyi ona keçirmi?\n\nKənarlarını barmaqlarınla izlə. Küncləri yumrudurmu? Səthi hamardır, yoxsa naxışlı? Düymələri hiss et, amma basma.\n\nBir titrəyiş və ya səs gəlsə, baxmadan fərqinə var və burax. Bu bir neçə saniyə sənindir.\n\nBir nəfəs al və ver. Əllərin telefonu tutur, amma diqqətin ekranda yox, əllərindədir.\n\nİndi telefonu yavaşca masaya, ekranı aşağı qoy. Əllərin boşalanda nə hiss edirsən? Yüngüllük?\n\nGün ərzində telefona əl uzatdığını görəndə, bəzən ekranı açmazdan əvvəl onu sadəcə bir neçə saniyə tut. Ağırlıq, istilik, bir nəfəs.\n\nTelefon masada durarkən əllərini bir-birinə sıx. Bir az əvvəl tutduğun ağırlığın yerini indi öz əllərinin istiliyi alır.\n\nBir nəfəs al və ver. Telefon oradadır, gözləyə bilər. Sən buradasan, bu nəfəsdə.",
    ru: "Сегодняшний маленький шаг — вес телефона. Обычно телефон уводит наш ум куда-то ещё. Сегодня используем его наоборот: чтобы вернуть тебя в этот момент.\n\nСядь удобно. Возьми телефон обеими руками экраном вниз. Сделай вдох и медленный выдох.\n\nВозьми телефон обеими руками. Десять секунд чувствуй только его вес и тепло; на экран не смотри. Потом положи его.\n\nПочувствуй его вес. Насколько он давит на ладони? Медленно переложи его из одной руки в другую. Потом снова держи обеими.\n\nЗаметь его температуру. Задняя сторона прохладная или тёплая? Переходит ли к нему тепло рук?\n\nПроведи пальцами по краям. Углы закруглённые? Поверхность гладкая или рельефная? Нащупай кнопки, но не нажимай.\n\nЕсли придёт вибрация или звук, заметь это, не глядя, и отпусти. Эти несколько секунд принадлежат тебе.\n\nВдох и выдох. Руки держат телефон, но внимание не на экране, а в руках.\n\nТеперь медленно положи телефон на стол экраном вниз. Что ощущается, когда руки свободны? Лёгкость?\n\nКогда в течение дня рука тянется к телефону, иногда просто подержи его несколько секунд, прежде чем включить экран. Вес, тепло, один вдох.\n\nПока телефон лежит на столе, прижми ладони друг к другу. Место веса, который был в руках минуту назад, теперь занимает тепло собственных рук.\n\nВдох и выдох. Телефон там, он может подождать. А ты здесь, в этом вдохе.",
  },
  "c2.body": {
    tr: "Bugünün küçük adımı ayak tabanlarıyla ilgili. Zihin hızlandığında dikkat çoğu zaman başta toplanır. Onu yavaşça aşağı, ayaklara indirmek bedeni sakinleştirir.\n\nİstersen ayakkabılarını çıkar. Bir sandalyeye otur ya da ayakta dur. Bir nefes al ve yavaşça ver.\n\nİki ayak tabanını da yerde hisset. Zemin serin mi, ılık mı? Ağırlığını yavaşça yere bırak.\n\nÖnce topuklarını hisset. Ağırlığının ne kadarı topuklarında? Sonra ayaklarının dış kenarlarını. Sonra parmaklarının altındaki yumuşak bölgeyi. En son da parmaklarını.\n\nAyak parmaklarını yavaşça açıp kapat. Birkaç kez. Sonra onları yere bırak ve tabanlarının bütün yüzeyiyle yere değdiğini hisset.\n\nAğırlığını çok hafifçe öne doğru kaydır, sonra geriye. Sonra sağa, sonra sola. Sonra ortada, en rahat noktada dur. Bu hareketler küçük olsun; neredeyse görünmez.\n\nŞimdi nefes alırken ayaklarının yere biraz daha yerleştiğini hayal et. Nefes verirken ağırlığın yere doğru akıyor. Sanki ayaklarından yere kökler uzanıyor.\n\nZemin seni taşıyor. Bina, toprak, dünya… hepsi altında, sağlam. Senin bir şey tutmana gerek yok.\n\nBir kez daha nefes al ve ver. Dikkatin hâlâ ayaklarında mı? Başa döndüyse, nazikçe yeniden aşağı indir.\n\nGün içinde kaygı yükseldiğinde, oturduğun ya da durduğun her yerde bu adımı yapabilirsin. Kimse fark etmez. Sadece sen ve ayaklarının altındaki yer.\n\nBir tur daha yapalım. Topuklar… dış kenarlar… parmakların altı… parmaklar. Ayaklarının bütününü aynı anda hisset. Nefes al… ve ver.\n\nAyakların sıcak mı, serin mi? Ne olursa olsun, yerdeler. Sen de buradasın. Hazır olduğunda bir adım at ve her adımda tabanlarının yere değişini hatırla.",
    en: "Today's small step is about the soles of your feet. When the mind speeds up, attention often gathers in the head. Bringing it slowly down to the feet calms the body.\n\nIf you like, take off your shoes. Sit on a chair or stand. Take a breath and let it out slowly.\n\nFeel both soles of your feet on the floor. Is the ground cool or warm? Slowly let your weight sink into it.\n\nFirst, feel your heels. How much of your weight is in your heels? Then the outer edges of your feet. Then the soft area under your toes. And finally your toes.\n\nSlowly spread your toes and curl them. A few times. Then let them rest on the floor, and feel the whole surface of your soles touching the ground.\n\nShift your weight very slightly forward, then back. Then to the right, then to the left. Then stop in the middle, at the most comfortable point. Keep these movements small; almost invisible.\n\nNow, as you breathe in, imagine your feet settling a little more into the ground. As you breathe out, your weight flows down. As if roots were reaching from your feet into the earth.\n\nThe ground is holding you. The building, the earth, the whole world… all of it beneath you, solid. You do not need to hold anything up.\n\nBreathe in and out once more. Is your attention still in your feet? If it has gone back to your head, gently bring it down again.\n\nWhenever anxiety rises during the day, you can do this step wherever you are sitting or standing. No one will notice. Just you and the ground beneath your feet.\n\nLet us do one more round. Heels… outer edges… under the toes… toes. Feel the whole of both feet at once. Breathe in… and out.\n\nAre your feet warm or cool? Either way, they are on the ground. And you are here. When you are ready, take a step, and with every step remember your soles touching the floor.",
    az: "Bugünün kiçik addımı ayaqaltıları ilə bağlıdır. Ağıl sürətlənəndə diqqət çox vaxt başda toplanır. Onu yavaşca aşağıya, ayaqlara endirmək bədəni sakitləşdirir.\n\nİstəsən, ayaqqabılarını çıxar. Stulda otur və ya ayaq üstə dur. Bir nəfəs al və yavaşca ver.\n\nHər iki ayağının altını yerdə hiss et. Döşəmə sərindir, yoxsa ilıq? Ağırlığını yavaşca yerə burax.\n\nƏvvəlcə dabanlarını hiss et. Ağırlığının nə qədəri dabanlarındadır? Sonra ayaqlarının çöl kənarlarını. Sonra barmaqlarının altındakı yumşaq hissəni. Ən sonda barmaqlarını.\n\nAyaq barmaqlarını yavaşca aç və yığ. Bir neçə dəfə. Sonra onları yerə burax və ayaqaltılarının bütün səthi ilə yerə toxunduğunu hiss et.\n\nAğırlığını çox yüngülcə irəli sürüşdür, sonra geri. Sonra sağa, sonra sola. Sonra ortada, ən rahat nöqtədə dayan. Bu hərəkətlər kiçik olsun; demək olar ki, görünməz.\n\nİndi nəfəs alanda ayaqlarının yerə bir az da yerləşdiyini təsəvvür et. Nəfəs verəndə ağırlığın yerə doğru axır. Sanki ayaqlarından torpağa köklər uzanır.\n\nDöşəmə səni saxlayır. Bina, torpaq, dünya… hamısı altındadır, möhkəmdir. Nəyisə tutmağa ehtiyac yoxdur.\n\nBir dəfə də nəfəs al və ver. Diqqətin hələ ayaqlarındadırmı? Başa qayıdıbsa, yumşaqca yenidən aşağı endir.\n\nGün ərzində narahatlıq artanda oturduğun və ya dayandığın hər yerdə bu addımı edə bilərsən. Heç kim hiss etməz. Yalnız sən və ayaqlarının altındakı yer.\n\nBir dəfə də edək. Dabanlar… çöl kənarlar… barmaqların altı… barmaqlar. Hər iki ayağını eyni anda bütövlükdə hiss et. Nəfəs al… və ver.\n\nAyaqların istidir, yoxsa sərin? Nə olursa olsun, yerdədirlər. Sən də buradasan. Hazır olanda bir addım at və hər addımda ayaqaltılarının yerə toxunduğunu xatırla.",
    ru: "Сегодняшний маленький шаг — про стопы. Когда ум разгоняется, внимание обычно собирается в голове. Если медленно опустить его вниз, к стопам, тело успокаивается.\n\nЕсли хочется, сними обувь. Сядь на стул или встань. Сделай вдох и медленный выдох.\n\nПочувствуй обе стопы на полу. Пол прохладный или тёплый? Медленно отдай ему свой вес.\n\nСначала почувствуй пятки. Какая часть веса приходится на пятки? Потом внешние края стоп. Потом мягкую часть под пальцами. И в конце сами пальцы.\n\nМедленно раздвинь пальцы ног и сожми их. Несколько раз. Потом отпусти их на пол и почувствуй, как вся поверхность стоп касается пола.\n\nОчень слегка перенеси вес вперёд, потом назад. Потом вправо, потом влево. Потом остановись посередине, в самой удобной точке. Пусть эти движения будут маленькими, почти незаметными.\n\nТеперь на вдохе представь, что стопы чуть глубже устраиваются на полу. На выдохе вес стекает вниз. Как будто от стоп в землю тянутся корни.\n\nПол держит тебя. Здание, земля, весь мир… всё это внизу, надёжное. Тебе не нужно ничего удерживать.\n\nЕщё раз вдох и выдох. Внимание всё ещё в стопах? Если оно вернулось в голову, мягко опусти его снова.\n\nКогда в течение дня поднимается тревога, этот шаг можно сделать где угодно, сидя или стоя. Никто не заметит. Только ты и пол под ногами.\n\nДавай ещё один круг. Пятки… внешние края… под пальцами… пальцы. Почувствуй обе стопы целиком сразу. Вдох… и выдох.\n\nСтопы тёплые или прохладные? Как бы ни было, они на полу. И ты здесь. Когда захочется, сделай шаг и с каждым шагом вспоминай, как подошвы касаются пола.",
  },
  "c3.body": {
    tr: "Bugünün küçük adımı tek bir eşya. Düşünceler hızla dönerken, gözlerini tek bir somut şeye vermek zihne bir çapa olur.\n\nBulunduğun yerde rahatça otur. Bir nefes al ve etrafına yavaşça bak.\n\nYakınındaki bir eşyayı seç: bir bardak, bir düğme. Adını içinden söyle. Dokusunu hisset. Hikâye kurmana gerek yok.\n\nSeçtiğin eşyayı eline al ya da ona dikkatle bak. Önce şeklini fark et. Yuvarlak mı, köşeli mi? Büyük mü, küçük mü?\n\nSonra rengine bak. Tek bir renk mi, birkaç renk mi? Işık ona nereden düşüyor? Bir tarafı daha parlak, bir tarafı daha gölgeli mi?\n\nEline aldıysan ağırlığını hisset. Hafif mi, ağır mı? Yüzeyi pürüzsüz mü, pürüzlü mü? Serin mi, ılık mı? Parmaklarını yavaşça üzerinde gezdir.\n\nZihin bu eşyayla ilgili bir hikâye anlatmaya başlayabilir: nereden alındığı, kimin verdiği, ne kadar tuttuğu. Bu hikâyeleri fark et ve yeniden eşyanın kendisine dön. Şekil, renk, doku.\n\nŞimdi bir nefes al ve eşyaya bakmaya devam ederek yavaşça ver. Bir kez daha. Eşya hareket etmiyor. Sabırla, olduğu gibi duruyor.\n\nBu küçük anda dikkatin tek bir yerde toplandı. Zihin biraz daha yavaş, biraz daha sakin.\n\nEşyayı yerine bırak. Gün içinde dağıldığını hissettiğinde, etrafında herhangi bir eşyayla bu adımı tekrarlayabilirsin.\n\nBir kez daha eşyaya bak, bu kez sanki onu ilk kez görüyormuşsun gibi. Daha önce fark etmediğin küçük bir ayrıntı bul. Bir çizik, bir parıltı, bir kıvrım.\n\nBu ayrıntıya birkaç nefes boyunca bak. Al… ve ver. Zihin şimdi daha az kalabalık. Sadece bir eşya ve sen.",
    en: "Today's small step is a single object. When thoughts are spinning fast, giving your eyes one concrete thing becomes an anchor for the mind.\n\nSit comfortably where you are. Take a breath and look around you slowly.\n\nChoose an object near you: a glass, a button. Say its name to yourself. Feel its texture. No need to make up a story.\n\nPick up the object you chose, or look at it carefully. First notice its shape. Round or angular? Large or small?\n\nThen look at its colour. One colour, or several? Where is the light falling on it? Is one side brighter and the other more shaded?\n\nIf you are holding it, feel its weight. Light or heavy? Is the surface smooth or rough? Cool or warm? Let your fingers move slowly over it.\n\nThe mind may start telling a story about this object: where it came from, who gave it to you, how much it cost. Notice these stories, and come back to the object itself. Shape, colour, texture.\n\nNow take a breath, and keep looking at the object as you slowly breathe out. Once more. The object is not moving. It stays patiently, just as it is.\n\nIn this small moment, your attention has gathered in one place. The mind is a little slower, a little calmer.\n\nPut the object back. Whenever you feel scattered during the day, you can repeat this step with any object around you.\n\nLook at the object once more, as if you were seeing it for the first time. Find a small detail you had not noticed before. A scratch, a glint, a curve.\n\nLook at that detail for a few breaths. In… and out. The mind is less crowded now. Just one object, and you.",
    az: "Bugünün kiçik addımı tək bir əşyadır. Fikirlər sürətlə fırlananda gözlərini tək bir konkret şeyə vermək ağıl üçün lövbər olur.\n\nOlduğun yerdə rahat otur. Bir nəfəs al və ətrafına yavaşca bax.\n\nYaxınlığındakı bir əşyanı seç: bir stəkan, bir düymə. Adını içində de. Toxumasını hiss et. Hekayə qurmağa ehtiyac yoxdur.\n\nSeçdiyin əşyanı əlinə götür və ya ona diqqətlə bax. Əvvəlcə formasına fikir ver. Yumrudur, yoxsa künclü? Böyükdür, yoxsa kiçik?\n\nSonra rənginə bax. Tək bir rəngdir, yoxsa bir neçə? İşıq ona haradan düşür? Bir tərəfi daha parlaq, o biri tərəfi daha kölgəlidirmi?\n\nƏlinə götürmüsənsə, ağırlığını hiss et. Yüngüldür, yoxsa ağır? Səthi hamardır, yoxsa kələ-kötür? Sərindir, yoxsa ilıq? Barmaqlarını yavaşca onun üstündə gəzdir.\n\nAğıl bu əşya haqqında hekayə danışmağa başlaya bilər: haradan alınıb, kim verib, neçəyə olub. Bu hekayələrin fərqinə var və yenidən əşyanın özünə qayıt. Forma, rəng, toxuma.\n\nİndi bir nəfəs al və əşyaya baxmağa davam edərək yavaşca ver. Bir dəfə də. Əşya tərpənmir. Səbirlə, olduğu kimi durur.\n\nBu kiçik anda diqqətin bir yerdə toplandı. Ağıl bir az daha yavaş, bir az daha sakitdir.\n\nƏşyanı yerinə qoy. Gün ərzində dağınıq olduğunu hiss edəndə ətrafındakı istənilən əşya ilə bu addımı təkrarlaya bilərsən.\n\nƏşyaya bir dəfə də bax, bu dəfə sanki onu ilk dəfə görürsən. Əvvəl fərqinə varmadığın kiçik bir detal tap. Bir cızıq, bir parıltı, bir əyri xətt.\n\nBu detala bir neçə nəfəs boyu bax. Al… və ver. Ağıl indi daha az izdihamlıdır. Sadəcə bir əşya və sən.",
    ru: "Сегодняшний маленький шаг — один предмет. Когда мысли быстро кружатся, один конкретный предмет для глаз становится якорем для ума.\n\nСядь удобно там, где ты сейчас. Сделай вдох и медленно оглядись.\n\nВыбери предмет рядом: стакан, пуговицу. Мысленно назови его. Почувствуй его текстуру. Придумывать историю не нужно.\n\nВозьми выбранный предмет в руки или внимательно посмотри на него. Сначала заметь его форму. Круглая или угловатая? Большой он или маленький?\n\nПотом посмотри на цвет. Один цвет или несколько? Откуда на него падает свет? Одна сторона ярче, а другая в тени?\n\nЕсли он в руках, почувствуй его вес. Лёгкий или тяжёлый? Поверхность гладкая или шершавая? Прохладная или тёплая? Медленно проведи по нему пальцами.\n\nУм может начать рассказывать историю про этот предмет: откуда он, кто его подарил, сколько стоил. Замечай эти истории и возвращайся к самому предмету. Форма, цвет, фактура.\n\nТеперь сделай вдох и, продолжая смотреть на предмет, медленно выдохни. Ещё раз. Предмет не движется. Он терпеливо остаётся таким, какой есть.\n\nВ этот маленький момент внимание собралось в одном месте. Ум стал чуть медленнее и спокойнее.\n\nПоложи предмет на место. Когда в течение дня будет ощущение, что внимание рассыпается, этот шаг можно повторить с любым предметом рядом.\n\nПосмотри на предмет ещё раз, как будто видишь его впервые. Найди маленькую деталь, которую раньше не замечал взгляд. Царапину, блик, изгиб.\n\nПосмотри на эту деталь несколько вдохов. Вдох… и выдох. В уме теперь меньше толпы. Только один предмет и ты.",
  },
  "c4.body": {
    tr: "Bugünün küçük adımı omuzlar. Omuzlar gün boyu, fark etmeden kulaklara doğru yükselir. Ekrana bakarken, acele ederken, endişelenirken.\n\nRahat bir yerde otur ya da ayakta dur. Kollarını iki yanına bırak. Bir nefes al ve yavaşça ver.\n\nOmuzlarını kulaklarına doğru kaldır, iki saniye tut, sonra bırak. Bir kez daha. Bırakırken nefesini ver.\n\nBu kez nefesi hareketle birleştirelim. Nefes alırken omuzlarını yavaşça kulaklarına doğru kaldır… tut… bir, iki… ve nefesini verirken bırak. Omuzların düşsün.\n\nBir kez daha. Al ve kaldır… tut… ver ve bırak. Bırakırken bir ses çıkarmak istersen, hafif bir “ahh” da olur.\n\nŞimdi omuzlarını yavaşça geriye doğru çevir. Büyük, yavaş daireler. Üç kez geriye. Sonra üç kez öne. Hareket ederken boynunun nasıl hissettiğini fark et.\n\nArdından başını yavaşça sağ omzuna doğru eğ. Sol omzunu aşağı bırak. Birkaç nefes orada kal. Sonra başını ortaya getir ve diğer tarafa eğ.\n\nBaşını ortaya getir. Ellerini dizlerine ya da kucağına bırak. Omuzlarının şimdiki yerini fark et. Az önceye göre biraz daha aşağıda mı?\n\nNefes al… ve verirken omuzların bir milim daha insin. Bir kez daha. Ne kadar indikleri önemli değil; bırakmayı hatırlaman yeterli.\n\nGün içinde omuzlarının yükseldiğini fark ettiğinde bu adımı hatırla. Bir kaldır, bir bırak. Birkaç saniye yeter.\n\nSon bir tur. Nefes al ve omuzlarını kaldır. Tut. Ve bırak. Bu kez bıraktıktan sonra kollarının ağırlığını hisset. Kollar omuzları aşağı çekiyor.\n\nEllerin dizlerinde ya da kucağında, ağır ve sıcak. Birkaç nefes böyle kal. Omuzların yerinde, nefesin rahat.",
    en: "Today's small step is your shoulders. During the day, without our noticing, the shoulders creep up towards the ears. While we look at screens, while we hurry, while we worry.\n\nSit somewhere comfortable or stand. Let your arms hang by your sides. Take a breath and let it out slowly.\n\nLift your shoulders toward your ears, hold for two seconds, then let them drop. Once more. Breathe out as you let go.\n\nThis time let us join the breath with the movement. As you breathe in, slowly lift your shoulders towards your ears… hold… one, two… and as you breathe out, let go. Let your shoulders drop.\n\nOnce more. Breathe in and lift… hold… breathe out and let go. If you want to make a sound as you let go, a soft “ahh” is fine.\n\nNow slowly roll your shoulders backwards. Big, slow circles. Three times backwards. Then three times forwards. As you move, notice how your neck feels.\n\nThen slowly tilt your head towards your right shoulder. Let your left shoulder drop. Stay there for a few breaths. Then bring your head back to the middle and tilt to the other side.\n\nBring your head back to the middle. Let your hands rest on your knees or in your lap. Notice where your shoulders are now. A little lower than before?\n\nBreathe in… and as you breathe out, let your shoulders sink one millimetre more. Once more. It does not matter how far they drop; remembering to let go is enough.\n\nWhenever you notice your shoulders rising during the day, remember this step. Lift once, let go once. A few seconds is enough.\n\nOne last round. Breathe in and lift your shoulders. Hold. And let go. This time, after letting go, feel the weight of your arms. Your arms are drawing your shoulders down.\n\nYour hands are on your knees or in your lap, heavy and warm. Stay like this for a few breaths. Your shoulders are in place, your breath is easy.",
    az: "Bugünün kiçik addımı çiyinlərdir. Çiyinlər gün boyu, fərqinə varmadan qulaqlara doğru qalxır. Ekrana baxanda, tələsəndə, narahat olanda.\n\nRahat bir yerdə otur və ya ayaq üstə dur. Qollarını yanlarına burax. Bir nəfəs al və yavaşca ver.\n\nÇiyinlərini qulaqlarına doğru qaldır, iki saniyə saxla, sonra burax. Bir dəfə də. Buraxanda nəfəsini ver.\n\nBu dəfə nəfəsi hərəkətlə birləşdirək. Nəfəs alanda çiyinlərini yavaşca qulaqlarına doğru qaldır… saxla… bir, iki… və nəfəs verəndə burax. Qoy çiyinlərin düşsün.\n\nBir dəfə də. Al və qaldır… saxla… ver və burax. Buraxanda səs çıxarmaq istəsən, yüngül bir “ahh” da olar.\n\nİndi çiyinlərini yavaşca geriyə fırlat. Böyük, yavaş dairələr. Üç dəfə geriyə. Sonra üç dəfə irəliyə. Hərəkət edəndə boynunun necə hiss etdiyinə diqqət et.\n\nSonra başını yavaşca sağ çiyninə doğru əy. Sol çiynini aşağı burax. Bir neçə nəfəs orada qal. Sonra başını ortaya gətir və o biri tərəfə əy.\n\nBaşını ortaya gətir. Əllərini dizlərinə və ya qucağına burax. Çiyinlərinin indiki yerinə fikir ver. Əvvəlkindən bir az aşağıdadırmı?\n\nNəfəs al… və verəndə qoy çiyinlərin bir millimetr də ensin. Bir dəfə də. Nə qədər endikləri vacib deyil; buraxmağı xatırlamaq kifayətdir.\n\nGün ərzində çiyinlərinin qalxdığını hiss edəndə bu addımı xatırla. Bir dəfə qaldır, bir dəfə burax. Bir neçə saniyə kifayətdir.\n\nSon bir dəfə. Nəfəs al və çiyinlərini qaldır. Saxla. Və burax. Bu dəfə buraxandan sonra qollarının ağırlığını hiss et. Qollar çiyinləri aşağı çəkir.\n\nƏllərin dizlərində və ya qucağında, ağır və isti. Bir neçə nəfəs belə qal. Çiyinlərin yerindədir, nəfəsin rahatdır.",
    ru: "Сегодняшний маленький шаг — плечи. В течение дня плечи незаметно поднимаются к ушам. Когда смотрим в экран, когда спешим, когда тревожимся.\n\nСядь удобно или встань. Опусти руки вдоль тела. Сделай вдох и медленный выдох.\n\nПодними плечи к ушам, задержи на две секунды и опусти. Ещё раз. Опуская плечи, выдыхай.\n\nНа этот раз соединим дыхание с движением. На вдохе медленно подними плечи к ушам… задержи… раз, два… и на выдохе отпусти. Пусть плечи упадут.\n\nЕщё раз. Вдох, поднимаем… задержка… выдох, отпускаем. Если хочется издать звук, отпуская, мягкое «ах» тоже подходит.\n\nТеперь медленно покрути плечами назад. Большие, медленные круги. Три раза назад. Потом три раза вперёд. Во время движения замечай, как ощущается шея.\n\nПотом медленно наклони голову к правому плечу. Левое плечо опусти вниз. Побудь так несколько вдохов. Потом верни голову в центр и наклони в другую сторону.\n\nВерни голову в центр. Положи руки на колени или на бёдра. Заметь, где сейчас плечи. Чуть ниже, чем раньше?\n\nВдох… и на выдохе пусть плечи опустятся ещё на миллиметр. Ещё раз. Неважно, насколько они опускаются; достаточно помнить, что их можно отпустить.\n\nКогда в течение дня заметишь, что плечи поднялись, вспомни этот шаг. Один раз поднять, один раз отпустить. Нескольких секунд достаточно.\n\nПоследний круг. Вдох, и плечи поднимаются. Задержка. И отпускаем. На этот раз после этого почувствуй вес рук. Руки тянут плечи вниз.\n\nЛадони на коленях, тяжёлые и тёплые. Побудь так несколько вдохов. Плечи на своём месте, дыхание свободное.",
  },
  "c5.body": {
    tr: "Bugünün küçük adımı ışık. Işığa dikkat etmek, zihni düşüncelerden alıp bulunduğun ana getirir. Hem de çok sessizce.\n\nBulunduğun yerde rahatça otur. Bir nefes al ve gözlerini yavaşça etrafında gezdir.\n\nIşığın hangi yönden geldiğine bak. Pencereden mi, lambadan mı? Sonra bir gölge bul ve nereye düştüğünü fark et.\n\nIşığın kaynağını bulduğunda bir süre ona bak. Doğal ışık mı, yapay ışık mı? Sıcak, sarımsı bir ışık mı, yoksa beyaz ve serin mi?\n\nŞimdi ışığın düştüğü yerleri takip et. Masanın kenarı, duvarın bir köşesi, yerdeki bir leke. Işık bazı yerlerde parlak, bazı yerlerde yumuşak.\n\nBir gölge bulduğunda onun şekline bak. Keskin mi, bulanık mı? Gölgenin kenarı ışığa nasıl karışıyor? Gölgeler de ışık kadar sakin.\n\nElini ışığa doğru kaldır. Elinin gölgesini bir yüzeyde gör. Parmaklarını yavaşça aç ve kapat. Gölge de seninle birlikte hareket ediyor.\n\nElini indir. Bir nefes al ve yavaşça ver. Işık sen düşünürken de, sen fark etmezken de oradaydı. Şimdi sadece onu görüyorsun.\n\nGözlerini bir an kapat. Göz kapaklarının arkasında bile hafif bir aydınlık var mı? Sonra yavaşça aç ve odanın ışığını yeniden karşıla.\n\nGün içinde bunalmış hissettiğinde, sadece ışığın nereden geldiğine bak. Bu küçük soru seni bulunduğun yere geri getirir.\n\nBir kez daha ışığın kaynağına bak. Sonra yavaşça ışığın en uzağa ulaştığı yeri bul. Odanın en loş köşesi. Orada bile biraz ışık var.\n\nIşıktan gölgeye, gölgeden ışığa gözlerini yavaşça gezdir. Her geçişte bir nefes al ve ver. Oda sakin, ışık yerinde, sen buradasın.",
    en: "Today's small step is light. Paying attention to light takes the mind away from thoughts and brings it into the moment you are in. Very quietly.\n\nSit comfortably where you are. Take a breath and let your eyes move slowly around you.\n\nNotice which way the light is coming from. The window, or a lamp? Then find a shadow and see where it falls.\n\nWhen you find the source of the light, look at it for a while. Is it natural light, or artificial? A warm, yellowish light, or white and cool?\n\nNow follow the places where the light falls. The edge of the table, a corner of the wall, a patch on the floor. In some places the light is bright, in others soft.\n\nWhen you find a shadow, look at its shape. Sharp or blurred? How does the edge of the shadow blend into the light? Shadows are just as calm as light.\n\nRaise your hand towards the light. See the shadow of your hand on a surface. Slowly open and close your fingers. The shadow moves with you.\n\nLower your hand. Take a breath and let it out slowly. The light was here while you were thinking, and while you were not noticing. Now you are simply seeing it.\n\nClose your eyes for a moment. Is there a faint brightness even behind your eyelids? Then slowly open them and meet the light of the room again.\n\nWhenever you feel overwhelmed during the day, just look at where the light is coming from. This small question brings you back to where you are.\n\nLook at the source of the light once more. Then slowly find the place where the light reaches furthest. The dimmest corner of the room. Even there, there is a little light.\n\nLet your eyes move slowly from light to shadow, from shadow to light. Take a breath with each crossing. The room is calm, the light is in its place, you are here.",
    az: "Bugünün kiçik addımı işıqdır. İşığa diqqət etmək ağlı fikirlərdən alıb olduğun ana gətirir. Özü də çox səssizcə.\n\nOlduğun yerdə rahat otur. Bir nəfəs al və gözlərini yavaşca ətrafında gəzdir.\n\nİşığın hansı tərəfdən gəldiyinə bax. Pəncərədən, yoxsa lampadan? Sonra bir kölgə tap və hara düşdüyünə diqqət et.\n\nİşığın mənbəyini tapanda bir müddət ona bax. Təbii işıqdır, yoxsa süni? İsti, sarımtıl işıqdır, yoxsa ağ və sərin?\n\nİndi işığın düşdüyü yerləri izlə. Masanın kənarı, divarın bir küncü, döşəmədə bir ləkə. İşıq bəzi yerlərdə parlaq, bəzi yerlərdə yumşaqdır.\n\nBir kölgə tapanda onun formasına bax. Kəskindir, yoxsa bulanıq? Kölgənin kənarı işığa necə qarışır? Kölgələr də işıq qədər sakitdir.\n\nƏlini işığa doğru qaldır. Əlinin kölgəsini bir səthdə gör. Barmaqlarını yavaşca aç və bağla. Kölgə də səninlə birlikdə hərəkət edir.\n\nƏlini endir. Bir nəfəs al və yavaşca ver. Sən düşünəndə də, fərqinə varmayanda da işıq burada idi. İndi sadəcə onu görürsən.\n\nGözlərini bir anlıq yum. Göz qapaqlarının arxasında belə yüngül bir aydınlıq varmı? Sonra yavaşca aç və otağın işığını yenidən qarşıla.\n\nGün ərzində bunaldığını hiss edəndə sadəcə işığın haradan gəldiyinə bax. Bu kiçik sual səni olduğun yerə qaytarır.\n\nİşığın mənbəyinə bir dəfə də bax. Sonra yavaşca işığın ən uzağa çatdığı yeri tap. Otağın ən qaranlıq küncü. Orada belə bir az işıq var.\n\nGözlərini yavaşca işıqdan kölgəyə, kölgədən işığa gəzdir. Hər keçiddə bir nəfəs al və ver. Otaq sakit, işıq yerində, sən buradasan.",
    ru: "Сегодняшний маленький шаг — свет. Внимание к свету уводит ум от мыслей и возвращает в тот момент, где ты находишься. И делает это очень тихо.\n\nСядь удобно там, где ты сейчас. Сделай вдох и медленно веди взгляд вокруг.\n\nПосмотри, с какой стороны идёт свет. Из окна или от лампы? Потом найди тень и заметь, куда она падает.\n\nКогда найдёшь источник света, посмотри на него какое-то время. Это дневной свет или искусственный? Тёплый, желтоватый или белый и прохладный?\n\nТеперь проследи, куда падает свет. Край стола, угол стены, пятно на полу. Где-то свет яркий, где-то мягкий.\n\nКогда найдёшь тень, посмотри на её форму. Чёткая или размытая? Как край тени переходит в свет? Тени так же спокойны, как свет.\n\nПодними руку к свету. Увидь тень руки на какой-нибудь поверхности. Медленно раскрой и сожми пальцы. Тень движется вместе с тобой.\n\nОпусти руку. Сделай вдох и медленный выдох. Свет был здесь и пока ты думаешь, и пока не замечаешь его. Сейчас ты просто его видишь.\n\nНа мгновение закрой глаза. Есть ли лёгкий свет даже за веками? Потом медленно открой глаза и снова встреть свет комнаты.\n\nКогда в течение дня всё наваливается, просто посмотри, откуда идёт свет. Этот маленький вопрос возвращает тебя туда, где ты есть.\n\nЕщё раз посмотри на источник света. Потом медленно найди место, куда свет доходит дальше всего. Самый тёмный угол комнаты. Даже там есть немного света.\n\nМедленно веди взгляд от света к тени и от тени к свету. С каждым переходом вдох и выдох. Комната спокойна, свет на месте, ты здесь.",
  },
  "c6.body": {
    tr: "Bugünün küçük adımı su. Bir yudum su içmek, en basit sakinleşme yollarından biri. Hem bedene iyi gelir, hem de dikkat için sade bir odak noktası verir.\n\nBir bardak su al. Rahatça otur. Bardağı iki elinle tut ve bir nefes al.\n\nBir yudum su al. Suyun sıcaklığını hisset. Boğazından aşağı inişini izle. Sonra bardağı bırak.\n\nYudumu almadan önce bardağa bak. Suyun yüzeyi kıpırdıyor mu? Işık suyun içinden nasıl geçiyor? Bardağın ağırlığını ellerinde hisset. Serin mi, ılık mı?\n\nŞimdi küçük bir yudum al. Hemen yutma. Suyu bir an ağzında tut. Dilinde, yanaklarının içinde serinliği ya da ılıklığı hisset.\n\nSonra yavaşça yut. Suyun boğazından aşağı indiğini, göğsünün ortasından geçtiğini takip et. Belki midende hafif bir serinlik hissediyorsun.\n\nBir nefes al ve ver. Sonra bir yudum daha. Bu kez daha da yavaş. Suyun sesini bile duyabilirsin.\n\nZihin başka yere giderse sorun değil. Bardağın ağırlığına, suyun serinliğine geri dön. Su seni bekliyor.\n\nBardağı masaya bıraktığında ellerinin boşaldığını hisset. Bedeninin biraz daha ferah olduğunu fark edebilirsin.\n\nGün içinde gerildiğinde, yanında bir bardak su olsun. Bir yudum, yavaşça. Bu kadar küçük bir şey bile bir mola olabilir.\n\nSon bir yudum için bardağı yeniden eline al. Bu kez yudumu alırken gözlerini kapat. Sadece serinlik, sadece akış, sadece yutkunma.\n\nGözlerini aç ve bardağı bırak. Bir nefes al ve ver. Bedenin biraz daha sulanmış, zihnin biraz daha sakin.",
    en: "Today's small step is water. Taking a sip of water is one of the simplest ways to calm down. It is good for the body, and it gives your attention a plain point of focus.\n\nTake a glass of water. Sit comfortably. Hold the glass in both hands and take a breath.\n\nTake a sip of water. Feel its temperature. Notice it going down your throat. Then put the glass down.\n\nBefore you take the sip, look at the glass. Is the surface of the water moving? How does the light pass through the water? Feel the weight of the glass in your hands. Is it cool or warm?\n\nNow take a small sip. Do not swallow straight away. Hold the water in your mouth for a moment. Feel its coolness or warmth on your tongue, inside your cheeks.\n\nThen swallow slowly. Follow the water as it goes down your throat, through the middle of your chest. Perhaps you feel a slight coolness in your stomach.\n\nTake a breath and let it out. Then one more sip. Even slower this time. You might even hear the sound of the water.\n\nIf your mind wanders, that is fine. Come back to the weight of the glass, the coolness of the water. The water is waiting for you.\n\nWhen you put the glass down, feel your hands becoming empty. You might notice your body feels a little more spacious.\n\nWhen you feel tense during the day, keep a glass of water nearby. One sip, slowly. Even something this small can be a pause.\n\nPick up the glass again for one last sip. This time, close your eyes as you drink. Only the coolness, only the flow, only the swallow.\n\nOpen your eyes and put the glass down. Take a breath and let it out. Your body is a little more refreshed, your mind a little calmer.",
    az: "Bugünün kiçik addımı sudur. Bir qurtum su içmək sakitləşməyin ən sadə yollarından biridir. Həm bədənə xeyirdir, həm də diqqətə sadə bir fokus nöqtəsi verir.\n\nBir stəkan su götür. Rahat otur. Stəkanı iki əllə tut və bir nəfəs al.\n\nBir qurtum su iç. Suyun temperaturunu hiss et. Boğazından aşağı enməsini izlə. Sonra stəkanı yerə qoy.\n\nQurtumu almazdan əvvəl stəkana bax. Suyun səthi tərpənirmi? İşıq suyun içindən necə keçir? Stəkanın ağırlığını əllərində hiss et. Sərindir, yoxsa ilıq?\n\nİndi kiçik bir qurtum al. Dərhal udma. Suyu bir an ağzında saxla. Dilində, yanaqlarının içində sərinliyi və ya ilıqlığı hiss et.\n\nSonra yavaşca ud. Suyun boğazından aşağı endiyini, sinənin ortasından keçdiyini izlə. Bəlkə mədəndə yüngül bir sərinlik hiss edirsən.\n\nBir nəfəs al və ver. Sonra bir qurtum da. Bu dəfə daha da yavaş. Suyun səsini belə eşidə bilərsən.\n\nAğıl başqa yerə getsə, problem deyil. Stəkanın ağırlığına, suyun sərinliyinə qayıt. Su səni gözləyir.\n\nStəkanı masaya qoyanda əllərinin boşaldığını hiss et. Bədəninin bir az daha rahatladığını görə bilərsən.\n\nGün ərzində gərgin olanda yanında bir stəkan su olsun. Bir qurtum, yavaşca. Belə kiçik bir şey də fasilə ola bilər.\n\nSon bir qurtum üçün stəkanı yenidən əlinə al. Bu dəfə içəndə gözlərini yum. Sadəcə sərinlik, sadəcə axın, sadəcə udqunma.\n\nGözlərini aç və stəkanı qoy. Bir nəfəs al və ver. Bədənin bir az da təravətlənib, ağlın bir az da sakitdir.",
    ru: "Сегодняшний маленький шаг — вода. Глоток воды — один из самых простых способов успокоиться. Это полезно для тела и даёт вниманию простую точку опоры.\n\nВозьми стакан воды. Сядь удобно. Держи стакан обеими руками и сделай вдох.\n\nСделай глоток воды. Почувствуй её температуру. Замечай, как она проходит по горлу. Потом поставь стакан.\n\nПрежде чем сделать глоток, посмотри на стакан. Двигается ли поверхность воды? Как свет проходит сквозь неё? Почувствуй вес стакана в руках. Он прохладный или тёплый?\n\nТеперь сделай маленький глоток. Не глотай сразу. Подержи воду во рту мгновение. Почувствуй прохладу или тепло на языке, на внутренней стороне щёк.\n\nПотом медленно проглоти. Проследи, как вода проходит по горлу, через середину груди. Может быть, в животе ощущается лёгкая прохлада.\n\nСделай вдох и выдох. Потом ещё один глоток. На этот раз ещё медленнее. Можно даже услышать звук воды.\n\nЕсли ум уходит в сторону, это нормально. Возвращайся к весу стакана, к прохладе воды. Вода ждёт тебя.\n\nКогда ставишь стакан, почувствуй, как руки освобождаются. Может быть заметно, что в теле стало чуть просторнее.\n\nКогда в течение дня накатывает напряжение, держи рядом стакан воды. Один глоток, медленно. Даже такая мелочь может стать передышкой.\n\nДля последнего глотка снова возьми стакан. На этот раз закрой глаза, когда пьёшь. Только прохлада, только течение, только глоток.\n\nОткрой глаза и поставь стакан. Вдох и выдох. Тело чуть свежее, ум чуть спокойнее.",
  },
  "c7.body": {
    tr: "Bugünün küçük adımı kendi adın. Bazen stres ya da kaygı insanı kendinden uzaklaşmış gibi hissettirir. Kendi sesini ve adını duymak, seni yeniden kendine bağlar.\n\nSessiz bir yere geç. Rahatça otur. Bir nefes al ve yavaşça ver.\n\nAdını fısıltıyla söyle. Sonra bugünün tarihini fısılda. Kendi sesini duy; aynaya bakmana gerek yok.\n\nAdını söylerken sesine dikkat et. Alçak mı, yumuşak mı? Fısıltının dudaklarında, dilinde nasıl hissettirdiğini fark et.\n\nŞimdi bir kez daha söyle, bu kez biraz daha yavaş. Her heceyi hisset. Bu ad yıllardır seninle. Seni çağıran, seni tanıyan bir ad.\n\nArdından bugünün tarihini fısılda. Gün, ay, yıl. Sonra bulunduğun yeri söyle: “Evdeyim.” “Odamdayım.” “Masamdayım.”\n\nBu üç cümle seni zamana ve yere bağlar. Ben buyum. Bugün bugün. Burası burası.\n\nBir elini göğsüne koy. Adını bir kez daha fısılda. Göğsünde sesin hafif titreşimini hissedebilirsin.\n\nBir nefes al… ve ver. Sen buradasın. Bu bedende, bu odada, bu günde.\n\nGün içinde kendinden uzaklaştığını hissettiğinde, adını içinden ya da fısıltıyla söyle. Bu küçük adım seni geri getirir.\n\nBir kez daha, bu kez sadece içinden söyle. Adın, bugünün tarihi, bulunduğun yer. Sesin içinde de yankılanıyor.\n\nElini göğsünde tutmaya devam et. Birkaç nefes. Sen buradasın ve bu yeterli.",
    en: "Today's small step is your own name. Sometimes stress or anxiety can make you feel distant from yourself. Hearing your own voice and your own name connects you back to yourself.\n\nGo somewhere quiet. Sit comfortably. Take a breath and let it out slowly.\n\nWhisper your name. Then whisper today’s date. Hear your own voice; there is no need to look in a mirror.\n\nAs you say your name, pay attention to your voice. Is it low? Soft? Notice how the whisper feels on your lips and tongue.\n\nNow say it once more, a little more slowly this time. Feel each syllable. This name has been with you for years. A name that calls you, that knows you.\n\nThen whisper today's date. The day, the month, the year. Then say where you are: “I am at home.” “I am in my room.” “I am at my desk.”\n\nThese three sentences connect you to time and place. This is me. Today is today. Here is here.\n\nPut one hand on your chest. Whisper your name once more. You may feel a faint vibration of your voice in your chest.\n\nBreathe in… and out. You are here. In this body, in this room, on this day.\n\nWhenever you feel distant from yourself during the day, say your name silently or in a whisper. This small step brings you back.\n\nOnce more, this time only inside your head. Your name, today's date, where you are. Your voice echoes inside too.\n\nKeep your hand on your chest. A few breaths. You are here, and that is enough.",
    az: "Bugünün kiçik addımı öz adındır. Bəzən stress və ya narahatlıq insanı özündən uzaqlaşmış kimi hiss etdirir. Öz səsini və adını eşitmək səni yenidən özünə bağlayır.\n\nSakit bir yerə keç. Rahat otur. Bir nəfəs al və yavaşca ver.\n\nAdını pıçıltı ilə de. Sonra bugünkü tarixi pıçılda. Öz səsini eşit; güzgüyə baxmağa ehtiyac yoxdur.\n\nAdını deyəndə səsinə diqqət et. Alçaqdır? Yumşaqdır? Pıçıltının dodaqlarında, dilində necə hiss olunduğuna fikir ver.\n\nİndi bir dəfə də de, bu dəfə bir az da yavaş. Hər hecanı hiss et. Bu ad illərdir səninlədir. Səni çağıran, səni tanıyan bir ad.\n\nSonra bugünkü tarixi pıçılda. Gün, ay, il. Sonra olduğun yeri de: “Evdəyəm.” “Otağımdayam.” “Masamın arxasındayam.”\n\nBu üç cümlə səni zamana və məkana bağlayır. Bu mənəm. Bu gün bu gündür. Bura buradır.\n\nBir əlini sinənə qoy. Adını bir dəfə də pıçılda. Sinəndə səsin yüngül titrəyişini hiss edə bilərsən.\n\nNəfəs al… və ver. Sən buradasan. Bu bədəndə, bu otaqda, bu gündə.\n\nGün ərzində özündən uzaqlaşdığını hiss edəndə adını içində və ya pıçıltı ilə de. Bu kiçik addım səni geri qaytarır.\n\nBir dəfə də, bu dəfə yalnız içində de. Adın, bugünkü tarix, olduğun yer. Səsin içində də əks-səda verir.\n\nƏlini sinəndə saxlamağa davam et. Bir neçə nəfəs. Sən buradasan və bu kifayətdir.",
    ru: "Сегодняшний маленький шаг — твоё имя. Иногда стресс или тревога дают ощущение, будто ты отдаляешься от себя. Услышать свой голос и своё имя — значит снова соединиться с собой.\n\nНайди тихое место. Сядь удобно. Сделай вдох и медленный выдох.\n\nПрошепчи своё имя. Потом прошепчи сегодняшнюю дату. Услышь свой голос; смотреть в зеркало не нужно.\n\nКогда произносишь имя, обрати внимание на голос. Он низкий? Мягкий? Заметь, как шёпот ощущается на губах и языке.\n\nТеперь скажи его ещё раз, чуть медленнее. Почувствуй каждый слог. Это имя с тобой много лет. Имя, которым тебя зовут и по которому тебя знают.\n\nПотом прошепчи сегодняшнюю дату. День, месяц, год. Потом скажи, где ты: «Я дома». «Я в своей комнате». «Я за своим столом».\n\nЭти три фразы связывают тебя со временем и местом. Это я. Сегодня — это сегодня. Здесь — это здесь.\n\nПоложи одну руку на грудь. Прошепчи имя ещё раз. В груди можно почувствовать лёгкую вибрацию голоса.\n\nВдох… и выдох. Ты здесь. В этом теле, в этой комнате, в этом дне.\n\nКогда в течение дня появится ощущение отстранённости от себя, произнеси своё имя про себя или шёпотом. Этот маленький шаг возвращает тебя.\n\nЕщё раз, на этот раз только про себя. Имя, сегодняшняя дата, где ты. Голос звучит и внутри.\n\nДержи руку на груди. Несколько вдохов. Ты здесь, и этого достаточно.",
  },
  "c8.body": {
    tr: "Bugünün küçük adımı avuçlarının sıcaklığı. Eller çok şey hisseder ve sıcaklık bedene güven sinyali verir.\n\nRahatça otur. Ellerini kucağına bırak. Bir nefes al ve yavaşça ver.\n\nAvuçlarını birbirine bastır, birkaç saniye sonra ayır. Aradaki sıcaklığı hisset.\n\nÖnce avuçlarını birbirine iyice bastır. Parmak uçlarından bileklerine kadar. Birkaç saniye tut. Avuçlarının arasında sıcaklığın arttığını hisset.\n\nŞimdi avuçlarını hızlıca birbirine sürt. Beş, altı, yedi saniye. Sürtünme sıcaklık yaratıyor. Sonra dur ve ellerini birkaç santim ayır.\n\nAvuçlarının arasındaki boşluğu fark et. Sıcaklık hâlâ orada mı? Hafif bir karıncalanma var mı? Ellerini biraz yaklaştır, biraz uzaklaştır.\n\nŞimdi sıcak avuçlarını yüzüne koy. Gözlerinin üstüne, yumuşakça. Sıcaklığın göz kapaklarına geçmesine izin ver. Gözlerinin arkasındaki kaslar gevşesin.\n\nBir nefes al ve ver. Sonra ellerini yavaşça yanaklarına, sonra boynuna indir. Her yerde sıcaklık kısa bir süre kalıyor.\n\nEllerini yeniden kucağına bırak. Avuçların yukarı baksın. Sıcaklığın yavaşça yayıldığını hisset.\n\nGün içinde ellerin soğuk ya da gergin olduğunda bu adımı hatırla. Bastır, sürt, yüzüne koy. Birkaç saniyelik sıcaklık.\n\nBir tur daha yapalım. Avuçları bastır… sürt… ayır. Bu kez sıcak ellerini ensene koy. Boynunun arkası sıcaklığı alıyor, omuzların biraz iniyor.\n\nEllerini yeniden kucağına bırak. Bir nefes al ve ver. Sıcaklık ellerinden bütün bedenine yavaşça yayılıyor.",
    en: "Today's small step is the warmth of your palms. Hands feel a great deal, and warmth gives the body a signal of safety.\n\nSit comfortably. Rest your hands in your lap. Take a breath and let it out slowly.\n\nPress your palms together, and after a few seconds, pull them apart. Feel the warmth between them.\n\nFirst, press your palms firmly together. From your fingertips to your wrists. Hold for a few seconds. Feel the warmth growing between your palms.\n\nNow rub your palms together quickly. Five, six, seven seconds. The friction creates warmth. Then stop, and move your hands a few centimetres apart.\n\nNotice the space between your palms. Is the warmth still there? Is there a slight tingling? Bring your hands a little closer, then a little further apart.\n\nNow place your warm palms over your face. Gently over your eyes. Let the warmth pass into your eyelids. Let the muscles behind your eyes relax.\n\nTake a breath and let it out. Then slowly move your hands down to your cheeks, then to your neck. Everywhere they go, the warmth stays for a moment.\n\nRest your hands in your lap again, palms facing up. Feel the warmth slowly spreading.\n\nWhen your hands are cold or tense during the day, remember this step. Press, rub, place them on your face. A few seconds of warmth.\n\nLet us do one more round. Press your palms… rub… part. This time, place your warm hands on the back of your neck. Your neck takes in the warmth, and your shoulders drop a little.\n\nRest your hands in your lap again. Take a breath and let it out. The warmth spreads slowly from your hands through your whole body.",
    az: "Bugünün kiçik addımı ovuclarının istiliyidir. Əllər çox şey hiss edir və istilik bədənə təhlükəsizlik siqnalı verir.\n\nRahat otur. Əllərini qucağına burax. Bir nəfəs al və yavaşca ver.\n\nOvuclarını bir-birinə sıx, bir neçə saniyədən sonra arala. Aradakı istiliyi hiss et.\n\nƏvvəlcə ovuclarını bir-birinə möhkəm sıx. Barmaq uclarından biləklərə qədər. Bir neçə saniyə saxla. Ovuclarının arasında istiliyin artdığını hiss et.\n\nİndi ovuclarını cəld bir-birinə sürt. Beş, altı, yeddi saniyə. Sürtünmə istilik yaradır. Sonra dayan və əllərini bir neçə santimetr arala.\n\nOvuclarının arasındakı boşluğu hiss et. İstilik hələ oradadırmı? Yüngül bir göynəmə varmı? Əllərini bir az yaxınlaşdır, bir az uzaqlaşdır.\n\nİndi isti ovuclarını üzünə qoy. Gözlərinin üstünə, yumşaqca. Qoy istilik göz qapaqlarına keçsin. Gözlərinin arxasındakı əzələlər boşalsın.\n\nBir nəfəs al və ver. Sonra əllərini yavaşca yanaqlarına, sonra boynuna endir. Hər yerdə istilik qısa müddət qalır.\n\nƏllərini yenidən qucağına burax. Ovucların yuxarı baxsın. İstiliyin yavaş-yavaş yayıldığını hiss et.\n\nGün ərzində əllərin soyuq və ya gərgin olanda bu addımı xatırla. Sıx, sürt, üzünə qoy. Bir neçə saniyəlik istilik.\n\nBir dəfə də edək. Ovucları sıx… sürt… arala. Bu dəfə isti əllərini boynunun arxasına qoy. Boynun istiliyi alır, çiyinlərin bir az enir.\n\nƏllərini yenidən qucağına burax. Bir nəfəs al və ver. İstilik əllərindən bütün bədəninə yavaş-yavaş yayılır.",
    ru: "Сегодняшний маленький шаг — тепло ладоней. Руки чувствуют очень многое, а тепло подаёт телу сигнал безопасности.\n\nСядь удобно. Положи руки на колени. Сделай вдох и медленный выдох.\n\nПрижми ладони друг к другу, а через несколько секунд разведи их. Почувствуй тепло между ними.\n\nСначала крепко прижми ладони друг к другу. От кончиков пальцев до запястий. Подержи несколько секунд. Почувствуй, как между ладонями нарастает тепло.\n\nТеперь быстро потри ладони друг о друга. Пять, шесть, семь секунд. Трение создаёт тепло. Потом остановись и разведи руки на несколько сантиметров.\n\nЗаметь пространство между ладонями. Тепло всё ещё там? Есть ли лёгкое покалывание? Приблизь руки чуть ближе, потом чуть дальше.\n\nТеперь положи тёплые ладони на лицо. Мягко на глаза. Пусть тепло перейдёт к векам. Пусть мышцы за глазами расслабятся.\n\nСделай вдох и выдох. Потом медленно опусти руки на щёки, потом на шею. Везде тепло ненадолго задерживается.\n\nСнова положи руки на колени, ладонями вверх. Почувствуй, как тепло медленно расходится.\n\nКогда в течение дня руки холодные или напряжённые, вспомни этот шаг. Прижать, потереть, приложить к лицу. Несколько секунд тепла.\n\nДавай ещё раз. Прижать ладони… потереть… развести. На этот раз положи тёплые руки на затылок, на заднюю сторону шеи. Шея принимает тепло, плечи немного опускаются.\n\nСнова положи руки на колени. Вдох и выдох. Тепло медленно расходится от рук по всему телу.",
  },
  "c9.body": {
    tr: "Bugünün küçük adımı uzun bir nefes. Uzun ve yavaş bir nefes verişi bedene güvende olduğunu hatırlatır. Kalp ritmi bu ritmi takip eder.\n\nRahatça otur ya da uzan. Omuzlarını bırak. Bir elini karnına koyabilirsin.\n\nBurnundan nefes al, sonra ağzından altıya kadar sayarak yavaşça ver. Üç kez tekrarla. Zorlamadan, rahatça.\n\nBirlikte yapalım. Burnundan nefes al… bir, iki, üç, dört. Ve ağzından yavaşça ver… bir, iki, üç, dört, beş, altı.\n\nBir kez daha. Nefes al… bir, iki, üç, dört. Ver… bir, iki, üç, dört, beş, altı. Verirken dudaklarını hafifçe büzebilirsin, sanki bir pipetten üflüyormuş gibi.\n\nÜçüncü kez. Al… bir, iki, üç, dört. Ver… bir, iki, üç, dört, beş, altı. Karnının elinin altında yavaşça indiğini hisset.\n\nSaymak zor gelirse bırak. Sadece nefes verişini nefes alışından biraz daha uzun tut. Bu kadar.\n\nŞimdi nefesi kendi haline bırak. Birkaç nefes sadece izle. Daha mı yavaş? Daha mı derin? Belki omuzların biraz indi.\n\nKalbin hızlı atıyorsa bu da olabilir. Onu durdurmaya çalışma. Uzun nefes verişleri ona zaman içinde yavaşlamayı öğretir.\n\nGün içinde gerildiğinde bu adımı hatırla. Dört say, al. Altı say, ver. Üç kez. Bir dakika bile sürmez.\n\nSon bir kez birlikte. Al… bir, iki, üç, dört. Ver… bir, iki, üç, dört, beş, altı. Ve bir kez daha. Al… ve uzun uzun ver.\n\nŞimdi elini karnında bırak ve sadece dinlen. Nefesin kendi ritminde. Bedenin biraz daha yumuşak, biraz daha yavaş.",
    en: "Today's small step is one long breath. A long, slow out-breath reminds the body that it is safe. Your heart rhythm follows this rhythm.\n\nSit or lie down comfortably. Let your shoulders go. You can rest one hand on your belly.\n\nBreathe in through your nose, then breathe out slowly through your mouth, counting to six. Repeat three times, gently, without forcing.\n\nLet us do it together. Breathe in through your nose… one, two, three, four. And breathe out slowly through your mouth… one, two, three, four, five, six.\n\nOnce more. Breathe in… one, two, three, four. Out… one, two, three, four, five, six. As you breathe out, you can purse your lips slightly, as if blowing through a straw.\n\nA third time. In… one, two, three, four. Out… one, two, three, four, five, six. Feel your belly slowly sinking under your hand.\n\nIf counting feels hard, let it go. Just keep your out-breath a little longer than your in-breath. That is all.\n\nNow let the breath find its own way. Simply watch a few breaths. Slower? Deeper? Perhaps your shoulders have dropped a little.\n\nIf your heart is beating fast, that is all right too. Do not try to stop it. Long out-breaths teach it to slow down over time.\n\nWhenever you feel tense during the day, remember this step. Count four, breathe in. Count six, breathe out. Three times. It takes less than a minute.\n\nOne last time together. In… one, two, three, four. Out… one, two, three, four, five, six. And once more. In… and a long, slow out.\n\nNow leave your hand on your belly and simply rest. Your breath is in its own rhythm. Your body is a little softer, a little slower.",
    az: "Bugünün kiçik addımı bir uzun nəfəsdir. Uzun və yavaş nəfəs verişi bədənə təhlükəsiz olduğunu xatırladır. Ürəyin ritmi bu ritmi izləyir.\n\nRahat otur və ya uzan. Çiyinlərini burax. Bir əlini qarnına qoya bilərsən.\n\nBurnundan nəfəs al, sonra ağzından altıya qədər sayaraq yavaşca ver. Üç dəfə təkrarla. Zorlamadan, rahatca.\n\nBirlikdə edək. Burnundan nəfəs al… bir, iki, üç, dörd. Və ağzından yavaşca ver… bir, iki, üç, dörd, beş, altı.\n\nBir dəfə də. Nəfəs al… bir, iki, üç, dörd. Ver… bir, iki, üç, dörd, beş, altı. Verəndə dodaqlarını yüngülcə büzə bilərsən, sanki borucuqdan üfürürsən.\n\nÜçüncü dəfə. Al… bir, iki, üç, dörd. Ver… bir, iki, üç, dörd, beş, altı. Qarnının əlinin altında yavaşca endiyini hiss et.\n\nSaymaq çətin gəlsə, burax. Sadəcə nəfəs verişini nəfəs alışından bir az uzun saxla. Bu qədər.\n\nİndi nəfəsi öz halına burax. Bir neçə nəfəsi sadəcə izlə. Daha yavaşdır? Daha dərindir? Bəlkə çiyinlərin bir az enib.\n\nÜrəyin tez döyünürsə, bu da ola bilər. Onu dayandırmağa çalışma. Uzun nəfəs verişləri ona zamanla yavaşlamağı öyrədir.\n\nGün ərzində gərgin olanda bu addımı xatırla. Dördə qədər say, al. Altıya qədər say, ver. Üç dəfə. Bir dəqiqə də çəkmir.\n\nSon dəfə birlikdə. Al… bir, iki, üç, dörd. Ver… bir, iki, üç, dörd, beş, altı. Və bir dəfə də. Al… və uzun-uzun ver.\n\nİndi əlini qarnında saxla və sadəcə dincəl. Nəfəsin öz ritmindədir. Bədənin bir az daha yumşaq, bir az daha yavaşdır.",
    ru: "Сегодняшний маленький шаг — один длинный выдох. Длинный, медленный выдох напоминает телу, что оно в безопасности. Сердечный ритм следует за этим ритмом.\n\nСядь или ляг удобно. Отпусти плечи. Одну руку можно положить на живот.\n\nВдохни через нос, затем медленно выдохни через рот, считая до шести. Повтори три раза. Спокойно, без усилия.\n\nДавай вместе. Вдох через нос… раз, два, три, четыре. И медленный выдох через рот… раз, два, три, четыре, пять, шесть.\n\nЕщё раз. Вдох… раз, два, три, четыре. Выдох… раз, два, три, четыре, пять, шесть. На выдохе можно слегка сложить губы трубочкой, как будто дуешь через соломинку.\n\nВ третий раз. Вдох… раз, два, три, четыре. Выдох… раз, два, три, четыре, пять, шесть. Почувствуй, как живот медленно опускается под рукой.\n\nЕсли считать трудно, отпусти счёт. Просто делай выдох чуть длиннее вдоха. Вот и всё.\n\nТеперь позволь дыханию идти само. Просто понаблюдай несколько вдохов. Медленнее? Глубже? Может быть, плечи немного опустились.\n\nЕсли сердце бьётся быстро, это тоже нормально. Не пытайся его остановить. Длинные выдохи со временем учат его замедляться.\n\nКогда в течение дня накатывает напряжение, вспомни этот шаг. Счёт до четырёх — вдох. Счёт до шести — выдох. Три раза. Это занимает меньше минуты.\n\nПоследний раз вместе. Вдох… раз, два, три, четыре. Выдох… раз, два, три, четыре, пять, шесть. И ещё раз. Вдох… и долгий медленный выдох.\n\nТеперь оставь руку на животе и просто отдыхай. Дыхание в своём ритме. Тело чуть мягче и чуть медленнее.",
  },
  "coral.body": {
    tr: "Fırtınasız, sakin bir gece. Küçük, sığ bir koyun kıyısındasın. Su ılık ve berrak.\n\nAy suyun üstünde gümüş bir yol çiziyor. Kıyıda kimse yok; sadece sen, ılık kum ve hafif bir esinti. Havluyu bir kayanın üstüne bırakıyorsun ve çıplak ayaklarla suyun kenarına yürüyorsun.\n\nYavaşça suya giriyorsun. Su önce dizlerine, sonra beline kadar geliyor. Ayaklarının altındaki kum ince ve yumuşak.\n\nSuyun sıcaklığı bedenini sarıyor. Kollarını yavaşça açıyorsun; su ellerinin arasından yumuşakça kayıyor. Her adımında kum ayaklarının altında biraz çöküyor, sonra yeniden seni taşıyor.\n\nBiraz ileride, suyun içinde mercandan doğal bir kemer var; bir kapı gibi. Önünden yavaşça geçiyorsun.\n\nKemerin altından ay ışığı süzülüyor. Mercanların renkleri gece bile hafifçe seçiliyor: soluk pembe, kum rengi, açık turuncu. Hepsi yerinde, sabırla büyüyor.\n\nElini mercanların yakınında tutuyorsun ama dokunmuyorsun. Onlar da sen de bu suyun içinde güvendesiniz. Suyun hafif akıntısı parmaklarının arasından geçiyor.\n\nKüçük balıklar etrafında süzülüyor. Hiçbiri acele etmiyor. Sen de acele etmiyorsun.\n\nBir balık sürüsü aynı anda dönüyor; gümüş bir parıltı, sonra yeniden sakinlik. Bir yengeç kumun üstünde yavaşça yürüyor ve bir kayanın altında kayboluyor.\n\nNefesin suyun ritmine uyuyor. Su hafifçe yükselirken nefes alıyorsun, alçalırken veriyorsun. Göğsün, karnın, omuzların… hepsi suyun içinde biraz daha hafif.\n\nDüz bir kayaya oturuyorsun. Ellerin suyun içinde, dudaklarında hafif bir tuz tadı var. Dalga yok, sadece suyun hafif kıpırtısı.\n\nGökyüzüne bakıyorsun. Birkaç yıldız var, ay yumuşak bir ışıkla parlıyor. Kıyıdan çamların kokusu geliyor. Uzakta bir köyde bir pencere sönüyor.\n\nDerine inmen gerekmiyor. Burada, sığ ve güvenli suda kalabilirsin. Su seni yavaşça sallıyor, sen dinleniyorsun.\n\nBir süre sonra suyun içinden yavaşça çıkıyor ve kıyıya dönüyorsun. Havluyu omuzlarına alıyorsun. Kum hâlâ ılık. Oturuyor ve koyu son bir kez izliyorsun.\n\nSu sakin, mercanlar yerinde, gece uzun. Bedenin ağır ve rahat. Gözlerin kapanırken suyun hafif sesini duymaya devam ediyorsun.",
    en: "It is a calm night with no storm. You are on the shore of a small, shallow cove. The water is warm and clear.\n\nThe moon draws a silver path across the water. There is no one on the shore; only you, the warm sand and a light breeze. You leave your towel on a rock and walk barefoot to the water's edge.\n\nYou wade in slowly. The water rises to your knees, then to your waist. The sand under your feet is fine and soft.\n\nThe warmth of the water surrounds your body. You open your arms slowly, and the water slides softly between your hands. With every step the sand gives a little under your feet, then holds you again.\n\nA little further out, there is a natural arch of coral in the water, like a gate. You drift slowly past it.\n\nMoonlight filters through the arch. Even at night you can make out the colours of the coral: pale pink, sandy beige, soft orange. Everything is in its place, growing patiently.\n\nYou hold your hand near the coral without touching it. You and the coral are both safe in this water. A gentle current passes between your fingers.\n\nSmall fish glide around you. None of them is in a hurry, and neither are you.\n\nA shoal of fish turns all at once; a silver flicker, and then calm again. A crab walks slowly across the sand and disappears under a rock.\n\nYour breath follows the rhythm of the water. As the water rises a little, you breathe in; as it falls, you breathe out. Your chest, your belly, your shoulders… all a little lighter in the water.\n\nYou sit on a flat rock. Your hands rest in the water, and there is a faint taste of salt on your lips. There are no waves, only the gentle stirring of the water.\n\nYou look up at the sky. There are a few stars, and the moon shines with a soft light. The smell of pine drifts from the shore. In a distant village, a window goes dark.\n\nYou do not need to go deeper. You can stay here, in the shallow, safe water. It rocks you softly while you rest.\n\nAfter a while you slowly come out of the water and walk back to the shore. You wrap the towel around your shoulders. The sand is still warm. You sit down and watch the cove one last time.\n\nThe water is calm, the coral is in its place, the night is long. Your body is heavy and at ease. As your eyes close, you can still hear the soft sound of the water.",
    az: "Fırtınasız, sakit bir gecədir. Kiçik, dayaz bir körfəzin sahilindəsən. Su ilıq və dumdurudur.\n\nAy suyun üstündə gümüşü bir yol çəkir. Sahildə heç kim yoxdur; yalnız sən, ilıq qum və yüngül meh. Dəsmalı bir qayanın üstünə qoyub yalınayaq suyun kənarına gedirsən.\n\nYavaşca suya girirsən. Su əvvəl dizlərinə, sonra belinə qədər qalxır. Ayaqlarının altındakı qum incə və yumşaqdır.\n\nSuyun istiliyi bədənini bürüyür. Qollarını yavaşca açırsan; su əllərinin arasından yumşaqca sürüşür. Hər addımda qum ayaqlarının altında bir az çökür, sonra yenə səni saxlayır.\n\nBir az irəlidə, suyun içində mərcandan təbii bir tağ var, qapı kimi. Onun yanından yavaşca keçirsən.\n\nTağın altından ay işığı süzülür. Mərcanların rəngləri gecə də yüngülcə seçilir: solğun çəhrayı, qum rəngi, açıq narıncı. Hamısı yerindədir, səbirlə böyüyür.\n\nƏlini mərcanlara yaxın tutursan, amma toxunmursan. Onlar da, sən də bu suyun içində təhlükəsizsiniz. Suyun yüngül axını barmaqlarının arasından keçir.\n\nKiçik balıqlar ətrafında üzür. Heç biri tələsmir. Sən də tələsmirsən.\n\nBir balıq sürüsü eyni anda dönür; gümüşü bir parıltı, sonra yenə sakitlik. Bir xərçəng qumun üstündə yavaşca yeriyir və bir qayanın altında gözdən itir.\n\nNəfəsin suyun ahənginə uyğunlaşır. Su yüngülcə qalxanda nəfəs alırsan, enəndə verirsən. Sinən, qarnın, çiyinlərin… hamısı suyun içində bir az da yüngüldür.\n\nHamar bir qayanın üstündə oturursan. Əllərin suyun içindədir, dodaqlarında yüngül duz dadı var. Dalğa yoxdur, sadəcə suyun yüngül tərpənişi.\n\nSəmaya baxırsan. Bir neçə ulduz var, ay yumşaq işıqla parlayır. Sahildən şam ağaclarının qoxusu gəlir. Uzaq bir kənddə bir pəncərənin işığı sönür.\n\nDərinə getməyə ehtiyac yoxdur. Burada, dayaz və təhlükəsiz suda qala bilərsən. Su səni yavaşca yırğalayır, sən isə dincəlirsən.\n\nBir müddətdən sonra sudan yavaşca çıxıb sahilə qayıdırsan. Dəsmalı çiyinlərinə salırsan. Qum hələ də ilıqdır. Oturursan və körfəzə son dəfə baxırsan.\n\nSu sakitdir, mərcanlar yerindədir, gecə uzundur. Bədənin ağır və rahatdır. Gözlərin yumularkən suyun yüngül səsini eşitməyə davam edirsən.",
    ru: "Тихая ночь без шторма. Ты на берегу маленькой мелкой бухты. Вода тёплая и прозрачная.\n\nЛуна прокладывает по воде серебряную дорожку. На берегу никого нет — только ты, тёплый песок и лёгкий ветер. Полотенце остаётся на камне, а ты босиком идёшь к кромке воды.\n\nТы медленно входишь в воду. Сначала она доходит до колен, потом до пояса. Песок под ногами мелкий и мягкий.\n\nТёплая вода обнимает тело. Ты медленно разводишь руки, и вода мягко скользит между ладонями. С каждым шагом песок чуть проседает под ногами и снова держит тебя.\n\nЧуть дальше в воде стоит природная арка из кораллов, похожая на ворота. Ты медленно проплываешь мимо неё.\n\nСквозь арку пробивается лунный свет. Даже ночью можно различить цвета кораллов: бледно-розовый, песочный, мягкий оранжевый. Всё на своих местах и растёт терпеливо.\n\nТы держишь руку рядом с кораллами, но не касаешься их. И им, и тебе в этой воде безопасно. Лёгкое течение проходит между пальцами.\n\nВокруг скользят маленькие рыбы. Ни одна не торопится. И ты не торопишься.\n\nСтайка рыбок разом поворачивается — серебряная вспышка, и снова покой. Краб медленно идёт по песку и исчезает под камнем.\n\nДыхание подстраивается под ритм воды. Когда вода чуть поднимается, ты вдыхаешь, когда опускается — выдыхаешь. Грудь, живот, плечи… в воде всё становится немного легче.\n\nТы садишься на плоский камень. Руки в воде, на губах лёгкий вкус соли. Волн нет, только тихое движение воды.\n\nТы смотришь на небо. Несколько звёзд, мягкий свет луны. С берега доносится запах сосен. В далёкой деревне гаснет окно.\n\nНе нужно уходить на глубину. Можно остаться здесь, в мелкой и безопасной воде. Вода мягко покачивает тебя, пока ты отдыхаешь.\n\nЧерез какое-то время ты медленно выходишь из воды и возвращаешься на берег. Полотенце ложится на плечи. Песок всё ещё тёплый. Ты садишься и в последний раз смотришь на бухту.\n\nВода спокойна, кораллы на своих местах, ночь длинная. Тело тяжёлое и расслабленное. Глаза закрываются, а тихий звук воды всё ещё слышен.",
  },
  "edges.body": {
    tr: "Dünya bazen uzak, bulanık ya da gerçek dışıymış gibi gelebilir. Bu yazı, etrafındakilerle yeniden temas kurmana yardım eder.\n\nBöyle anlarda korkmak çok doğal. Ama bu his tehlikeli değil; zihnin yorulduğunda bazen bir sis perdesi çeker. Sis gelir ve sis geçer.\n\nRahat bir yere otur. Ayaklarını yere bas ve ağırlığını sandalyeye bırak. Bir nefes al… ve yavaşça ver. Şimdi adım adım kenarları bulacağız.\n\nÖnce yüksek sesle söyle, sonra yaz. Gördüğün beş eşya. Dokunabildiğin üç doku: pürüzlü, yumuşak, soğuk… Hissettiğin bir sıcaklık. Duyduğun bir ses.\n\nSesini duymak önemli. Kendi sesin seni bulunduğun yere bağlar. Fısıltı da olur. Gördüğün ilk eşyayla başla: “Kapı.” Sonra ikinciyle: “Lamba.” Acele etme.\n\nDokulara geçtiğinde elini gerçekten uzat. Masanın yüzeyine, kumaşa, duvara dokun. Parmak uçlarında ne hissediyorsun? Pürüzlü mü, düz mü, ılık mı, serin mi?\n\nSıcaklık için bir bardağa, bir battaniyeye ya da kendi avuçlarına dokunabilirsin. Ses için kulağını odaya aç: bir saat, bir araba, kendi nefesin.\n\n“Sanki” diye başlayan cümleler kurma. Sadece adlar ve duyular yeter: “Masa. Ahşap. Serin.”\n\nKısa kelimeler zihni yavaşlatır. Her kelimeyi yazarken bir an dur. Kalemin kâğıda değdiği yeri hisset. Kâğıdın beyazlığını, mürekkebin rengini fark et.\n\nListeyi bitirdiğinde onu yüksek sesle bir kez oku. Her kelimede gözlerini o eşyaya çevir. Masa… ahşap… serin.\n\nSisle tartışmana gerek yok. Kenarlar yerinde duruyor; sen sadece onları adlandırıyorsun.\n\nBir süre sonra sis hafifleyebilir ya da biraz daha kalabilir. İki durumda da sen buradasın; bu odada, bu sandalyede, bu nefeste.\n\nAyaklarını yere bir kez daha bastır. Ellerini birbirine sürt ve sıcaklığı hisset. Bir nefes al ve uzun uzun ver.\n\nBu sayfayı sakla. Sis yeniden geldiğinde aynı listeyi okuyabilirsin. Kenarlar her seferinde orada olacak.",
    en: "Sometimes the world can feel distant, blurry, or unreal. This exercise helps you reconnect with what is around you.\n\nFeeling frightened at moments like this is very natural. But this feeling is not dangerous; when the mind is tired, it sometimes draws a curtain of fog. The fog comes, and the fog passes.\n\nSit somewhere comfortable. Put your feet on the floor and let your weight rest on the chair. Take a breath… and let it out slowly. Now, step by step, we will find the edges.\n\nFirst say it out loud, then write it down. Five things you can see. Three textures you can touch: rough, soft, cool… One warmth you can feel. One sound you can hear.\n\nHearing your voice matters. Your own voice connects you to where you are. A whisper is fine. Start with the first object you see: “Door.” Then the second: “Lamp.” Take your time.\n\nWhen you move on to textures, really reach out your hand. Touch the surface of the table, a piece of fabric, the wall. What do you feel under your fingertips? Rough or smooth, warm or cool?\n\nFor warmth, you can touch a cup, a blanket, or your own palms. For sound, open your ears to the room: a clock, a car, your own breath.\n\nAvoid sentences that begin with “as if”. Just names and senses: “Table. Wood. Cool.”\n\nShort words slow the mind down. Pause for a moment as you write each one. Feel where the pen touches the paper. Notice the white of the page, the colour of the ink.\n\nWhen you finish the list, read it aloud once. With each word, turn your eyes to that object. Table… wood… cool.\n\nYou do not need to argue with the fog. The edges are still there; you are simply naming them.\n\nAfter a while the fog may lift, or it may stay a little longer. Either way, you are here; in this room, on this chair, in this breath.\n\nPress your feet into the floor once more. Rub your hands together and feel the warmth. Take a breath and let it out long and slow.\n\nKeep this page. When the fog comes back, you can read the same list. The edges will be there every time.",
    az: "Dünya bəzən uzaq, dumanlı və ya qeyri-real görünə bilər. Bu yazı ətrafındakılarla yenidən təmas qurmağa kömək edir.\n\nBelə anlarda qorxmaq çox təbiidir. Amma bu hiss təhlükəli deyil; ağıl yorulanda bəzən bir duman pərdəsi çəkir. Duman gəlir və duman keçir.\n\nRahat bir yerdə otur. Ayaqlarını yerə bas və ağırlığını stula burax. Bir nəfəs al… və yavaşca ver. İndi addım-addım kənarları tapacağıq.\n\nƏvvəlcə ucadan de, sonra yaz. Gördüyün beş əşya. Toxuna bildiyin üç toxuma: kələ-kötür, yumşaq, soyuq… Hiss etdiyin bir istilik. Eşitdiyin bir səs.\n\nSəsini eşitmək vacibdir. Öz səsin səni olduğun yerə bağlayır. Pıçıltı da olar. Gördüyün ilk əşya ilə başla: “Qapı.” Sonra ikincisi ilə: “Lampa.” Tələsmə.\n\nToxumalara keçəndə əlini həqiqətən uzat. Masanın səthinə, parçaya, divara toxun. Barmaqlarının ucunda nə hiss edirsən? Kələ-kötür, hamar, ilıq, sərin?\n\nİstilik üçün bir fincana, yorğana və ya öz ovuclarına toxuna bilərsən. Səs üçün qulağını otağa aç: saat, maşın, öz nəfəsin.\n\n“Elə bil” deyə başlayan cümlələr qurma. Sadəcə adlar və duyğular kifayətdir: “Masa. Taxta. Sərin.”\n\nQısa sözlər ağlı yavaşladır. Hər sözü yazanda bir an dayan. Qələmin kağıza toxunduğu yeri hiss et. Kağızın ağlığını, mürəkkəbin rəngini gör.\n\nSiyahını bitirəndə onu bir dəfə ucadan oxu. Hər sözdə gözlərini həmin əşyaya çevir. Masa… taxta… sərin.\n\nDumanla mübahisə etməyə ehtiyac yoxdur. Kənarlar yerindədir; sən sadəcə onları adlandırırsan.\n\nBir müddətdən sonra duman yüngülləşə də bilər, bir az da qala bilər. Hər iki halda sən buradasan; bu otaqda, bu stulda, bu nəfəsdə.\n\nAyaqlarını yerə bir dəfə də bas. Əllərini bir-birinə sürt və istiliyi hiss et. Bir nəfəs al və uzun-uzun ver.\n\nBu səhifəni saxla. Duman yenidən gələndə eyni siyahını oxuya bilərsən. Kənarlar hər dəfə orada olacaq.",
    ru: "Иногда мир может казаться далёким, размытым или ненастоящим. Это упражнение помогает снова почувствовать связь с тем, что вокруг.\n\nПугаться в такие моменты очень естественно. Но само это чувство не опасно; когда ум устаёт, он иногда опускает завесу тумана. Туман приходит, и туман уходит.\n\nСядь удобно. Поставь ступни на пол и отдай вес стулу. Вдох… и медленный выдох. Теперь шаг за шагом найдём границы.\n\nСначала скажи вслух, потом запиши. Пять вещей, которые видишь. Три текстуры, которых можешь коснуться: шершавое, мягкое, прохладное… Одно тепло, которое чувствуешь. Один звук, который слышишь.\n\nВажно слышать свой голос. Собственный голос связывает тебя с местом, где ты находишься. Можно и шёпотом. Начни с первого предмета, который видишь: «Дверь». Потом второй: «Лампа». Не спеши.\n\nКогда дойдёшь до текстур, правда протяни руку. Коснись поверхности стола, ткани, стены. Что чувствуют кончики пальцев? Шершаво или гладко, тепло или прохладно?\n\nДля тепла можно коснуться чашки, пледа или собственных ладоней. Для звука прислушайся к комнате: часы, машина, твоё дыхание.\n\nНе используй фразы, начинающиеся со слов «как будто». Только названия и ощущения: «Стол. Дерево. Прохладно».\n\nКороткие слова замедляют ум. На каждом слове остановись на мгновение. Почувствуй, где ручка касается бумаги. Заметь белизну листа, цвет чернил.\n\nКогда список готов, прочитай его вслух один раз. На каждом слове переводи взгляд на этот предмет. Стол… дерево… прохладно.\n\nСпорить с туманом не нужно. Границы на месте; ты просто называешь их.\n\nЧерез какое-то время туман может рассеяться, а может ещё немного побыть. В любом случае ты здесь: в этой комнате, на этом стуле, в этом вдохе.\n\nЕщё раз упрись ступнями в пол. Потри ладони друг о друга и почувствуй тепло. Сделай вдох и долгий медленный выдох.\n\nСохрани эту страницу. Когда туман вернётся, можно прочитать тот же список. Границы каждый раз будут на месте.",
  },
  "gratitude-small.body": {
    tr: "Bu alıştırma günün sonunda, yatmadan önce ya da zor bir günün ortasında yapılabilir. Yanına bir kalem ve küçük bir defter al. Rahat bir yere otur ve bir nefes al.\n\nGün nasıl geçmiş olursa olsun, içinde mutlaka küçük ve iyi bir an vardır. Bazen gürültünün altında kalır. Şimdi onları birlikte bulacağız.\n\nÜç satır yaz. Her satırda bugün sana iyi gelen küçük ve somut bir şey olsun.\n\nÖnce günün başına dön. Sabah uyandığında ne vardı? Bir fincan sıcak içecek, pencereden gelen ışık, yatağın sıcaklığı. Sonra öğleye geç. Sonra akşama. Yavaş yavaş, bir film gibi.\n\nBüyük şeyler aramana gerek yok. Bir bardak su, ayaklarının altındaki zemin, rahat bir nefes, bir insanın sesi, yumuşak bir kumaş… hepsi olur.\n\nBir şeyi bulduğunda bir an üzerinde dur. O anı yeniden hayal et. Suyun serinliğini, sesin tonunu, kumaşın dokusunu. Bedeninde küçük bir yumuşama hissedebilirsin.\n\nAbartmadan, süslemeden yaz.\n\n“Harika bir gündü” gibi büyük cümleler yerine küçük ve somut cümleler yaz. “Öğlen güneş yüzüme geldi.” “Kedim yanıma kıvrıldı.” “Bir arkadaş mesaj attı.”\n\nÜç satırı bulmak zor gelirse, şu an yanında olan şeylere bak. Sırtını taşıyan sandalye, ellerin, nefesin. Bunlar da sayılır.\n\nİstersen her satırın yanına küçük bir not ekle: Bu şey bana ne hissettirdi? “Rahatladım.” “Gülümsedim.” “Yalnız değilmişim gibi geldi.” Tek bir kelime bile yeter.\n\nBitince defteri kapat. Üç küçük şey, bir gün için yeterli.\n\nDefteri kapatmadan önce üç satırı bir kez yavaşça oku. Her satırda bir nefes al. Sonra elini göğsüne koy ve o küçük şeyleri orada taşıdığını hayal et.\n\nBunu her gün yaparsan zihnin iyi anları daha kolay fark etmeye başlar. Kötü şeyler kaybolmaz ama iyi şeyler de görünür olur.\n\nBu gece yatağa girdiğinde o üç şeyden birini hatırla. Sadece birini. Ve onunla birlikte dinlen.",
    en: "You can do this at the end of the day, before bed, or in the middle of a hard day. Take a pen and a small notebook. Sit somewhere comfortable and take a breath.\n\nHowever the day has gone, there is always a small good moment in it somewhere. Sometimes it gets buried under the noise. Now we will find a few together.\n\nWrite three lines. On each line, put one small, concrete thing that did you good today.\n\nFirst, go back to the start of the day. What was there when you woke up? A warm drink, light from the window, the warmth of the bed. Then move on to midday. Then the evening. Slowly, like a film.\n\nYou do not need to look for big things. A glass of water, the floor under your feet, an easy breath, someone’s voice, a soft piece of fabric… all of these count.\n\nWhen you find something, stay with it for a moment. Picture that moment again. The coolness of the water, the tone of the voice, the texture of the fabric. You might feel a small softening in your body.\n\nWrite them simply, without decoration.\n\nInstead of big sentences like “It was a great day”, write small, concrete ones. “The sun was on my face at noon.” “My cat curled up next to me.” “A friend sent a message.”\n\nIf three lines feel hard to find, look at what is with you right now. The chair holding your back, your hands, your breath. These count too.\n\nIf you like, add a small note next to each line: How did this make me feel? “Relieved.” “I smiled.” “I felt less alone.” Even a single word is enough.\n\nWhen you are done, close the notebook. Three small things are enough for one day.\n\nBefore you close the notebook, read the three lines slowly once. Take a breath with each line. Then put your hand on your chest and imagine you are carrying those small things there.\n\nIf you do this every day, your mind begins to notice good moments more easily. The hard things do not disappear, but the good things become visible too.\n\nTonight, when you get into bed, remember one of those three things. Just one. And rest with it.",
    az: "Bu məşqi günün sonunda, yatmazdan əvvəl və ya çətin bir günün ortasında etmək olar. Yanına qələm və kiçik bir dəftər götür. Rahat bir yerdə otur və bir nəfəs al.\n\nGün necə keçmiş olursa olsun, içində mütləq kiçik və yaxşı bir an olur. Bəzən səs-küyün altında qalır. İndi onları birlikdə tapacağıq.\n\nÜç sətir yaz. Hər sətirdə bu gün sənə xoş gələn kiçik və konkret bir şey olsun.\n\nƏvvəlcə günün əvvəlinə qayıt. Səhər oyananda nə var idi? Bir fincan isti içki, pəncərədən gələn işıq, yatağın istiliyi. Sonra günortaya keç. Sonra axşama. Yavaş-yavaş, film kimi.\n\nBöyük şeylər axtarmağa ehtiyac yoxdur. Bir stəkan su, ayaqlarının altındakı döşəmə, rahat bir nəfəs, bir insanın səsi, yumşaq bir parça… hamısı olar.\n\nBir şey tapanda bir an onun üstündə dayan. O anı yenidən təsəvvür et. Suyun sərinliyini, səsin tonunu, parçanın toxumasını. Bədənində kiçik bir yumşalma hiss edə bilərsən.\n\nŞişirtmədən, bəzəmədən yaz.\n\n“Əla gün idi” kimi böyük cümlələrin yerinə kiçik və konkret cümlələr yaz. “Günorta günəş üzümə düşdü.” “Pişiyim yanımda qıvrıldı.” “Bir dostum mesaj yazdı.”\n\nÜç sətir tapmaq çətin gəlsə, indi yanında olan şeylərə bax. Kürəyini saxlayan stul, əllərin, nəfəsin. Bunlar da sayılır.\n\nİstəsən, hər sətirin yanına kiçik bir qeyd əlavə et: Bu şey mənə nə hiss etdirdi? “Rahatladım.” “Gülümsədim.” “Tək olmadığımı hiss etdim.” Bircə söz də kifayətdir.\n\nBitirəndə dəftəri bağla. Üç kiçik şey bir gün üçün kifayətdir.\n\nDəftəri bağlamazdan əvvəl üç sətri bir dəfə yavaşca oxu. Hər sətirdə bir nəfəs al. Sonra əlini sinənə qoy və o kiçik şeyləri orada daşıdığını təsəvvür et.\n\nBunu hər gün etsən, ağlın yaxşı anları daha asan görməyə başlayır. Pis şeylər yox olmur, amma yaxşı şeylər də görünür olur.\n\nBu gecə yatağa girəndə o üç şeydən birini xatırla. Sadəcə birini. Və onunla birlikdə dincəl.",
    ru: "Это можно делать в конце дня, перед сном или посреди трудного дня. Возьми ручку и маленькую тетрадь. Сядь удобно и сделай вдох.\n\nКак бы ни прошёл день, в нём обязательно есть маленький хороший момент. Иногда он теряется под шумом. Сейчас мы найдём несколько вместе.\n\nНапиши три строки. В каждой — одна маленькая конкретная вещь, которая сегодня была тебе в радость.\n\nСначала вернись в начало дня. Что было утром, сразу после пробуждения? Тёплый напиток, свет из окна, тепло постели. Потом переходи к середине дня. Потом к вечеру. Медленно, как фильм.\n\nНе нужно искать что-то большое. Стакан воды, пол под ногами, спокойный вдох, чей-то голос, мягкая ткань… всё подходит.\n\nКогда что-то находится, задержись на нём. Представь этот момент снова. Прохладу воды, интонацию голоса, фактуру ткани. В теле может появиться небольшое смягчение.\n\nПиши просто, без украшений.\n\nВместо больших фраз вроде «Это был прекрасный день» пиши маленькие и конкретные. «В полдень солнце светило в лицо». «Кошка свернулась рядом». «Друг прислал сообщение».\n\nЕсли три строки найти трудно, посмотри на то, что рядом прямо сейчас. Стул, который держит спину, твои руки, дыхание. Это тоже считается.\n\nЕсли хочется, добавь к каждой строке короткую заметку: что это мне дало? «Стало легче». «Улыбка». «Чувство, что рядом кто-то есть». Даже одного слова хватит.\n\nКогда закончишь, закрой тетрадь. Трёх маленьких вещей на один день достаточно.\n\nПрежде чем закрыть тетрадь, медленно прочитай три строки. На каждой строке сделай вдох. Потом положи ладонь на грудь и представь, что эти маленькие вещи хранятся там.\n\nЕсли делать это каждый день, ум начинает легче замечать хорошие моменты. Тяжёлое не исчезает, но хорошее тоже становится видимым.\n\nСегодня, когда ложишься в постель, вспомни одну из этих трёх вещей. Только одну. И отдыхай вместе с ней.",
  },
  "harbor.body": {
    tr: "Gece, küçük bir limanda bağlı bir teknenin kapalı güvertesindesin. Dışarıda yağmur yağıyor ama fırtına yok.\n\nKamaranın içi küçük ama sıcak. Ahşap duvarlar, yuvarlak bir pencere, köşede bir yatak ve kalın bir yün battaniye. Küçük bir sobada ateş sessizce yanıyor.\n\nCamlar hafifçe buğulanmış. Yağmur damlaları cama değip yavaşça aşağı süzülüyor.\n\nBir damlayı gözünle takip ediyorsun. Önce yavaşça kayıyor, sonra başka bir damlayla birleşiyor ve birlikte aşağı iniyor. Sonra bir başkası. Acele etmeden, kendi yollarını buluyorlar.\n\nBir halat iskeledeki direğe usulca vuruyor. Yumuşak, düzenli bir ses.\n\nTekne suyun üstünde hafifçe sallanıyor. Öyle az ki ancak dikkat edince fark ediyorsun. İleri… geri… ileri… geri. Bir beşik gibi.\n\nNefesin bu sallantıya uyuyor. Tekne yükselirken nefes alıyorsun, alçalırken veriyorsun. Göğsün yumuşuyor, çenen gevşiyor.\n\nRıhtımda sarı bir fener yanıyor; ışığı yağmurda titreşiyor ama yerinden kıpırdamıyor. Diğer tekneler de bağlı, hepsi sakin.\n\nSobanın üstündeki çaydanlık hafifçe buhar çıkarıyor. Kendine bir bardak ıhlamur dolduruyorsun. Sıcaklık avuçlarına yayılıyor, kokusu kamarayı dolduruyor.\n\nUzakta deniz fenerinin ışığı dönüyor. Her dönüşte yağmurun içinden yumuşak bir parıltı geçiyor. Limanın girişi güvende, gemiler güvende, sen güvendesin.\n\nBu gece nöbet tutman gerekmiyor. Her şey bağlı, her şey yerinde. Sen sadece içeride, kuru ve sıcak bir köşede oturuyorsun.\n\nBattaniyeyi omuzlarına alıyorsun ve yatağa uzanıyorsun. Yastık serin, yün sıcak. Tavandaki ahşap kirişlere bakıyorsun. Yağmur tam üstünde, ama sana dokunamıyor.\n\nYağmurun sesini dinle. Damla, damla… halatın yumuşak vuruşu. Omuzların aşağı iniyor, nefesin yavaşlıyor.\n\nGözlerin ağırlaşıyor. Yağmur, halat, sallantı… hepsi tek bir yumuşak ses gibi. Sabah olunca yağmur dinecek, güneş ıslak iskeleyi parlatacak. Ama şimdi gece ve sen dinleniyorsun.",
    en: "It is night, and you are on the covered deck of a boat moored in a small harbor. Outside it is raining, but there is no storm.\n\nThe cabin is small but warm. Wooden walls, a round porthole, a bunk in the corner and a thick wool blanket. In a little stove, a fire burns quietly.\n\nThe windows are slightly misted. Raindrops land on the glass and slide slowly down.\n\nYou follow one drop with your eyes. First it slides slowly, then it joins another drop, and they run down together. Then another. Without any hurry, they find their own way.\n\nA rope taps gently against a post on the pier. A soft, regular sound.\n\nThe boat rocks gently on the water. So gently that you only notice it when you pay attention. Forward… back… forward… back. Like a cradle.\n\nYour breath falls into this rocking. As the boat rises, you breathe in; as it sinks, you breathe out. Your chest softens, your jaw loosens.\n\nOn the quay a yellow lamp is glowing. Its light shimmers in the rain, but it does not move. The other boats are tied up too, all of them still.\n\nThe kettle on the stove lets out a little steam. You pour yourself a cup of linden tea. The warmth spreads into your palms, and its scent fills the cabin.\n\nIn the distance the lighthouse beam turns. Each time it passes, a soft glow moves through the rain. The harbour entrance is safe, the boats are safe, and you are safe.\n\nYou do not have to keep watch tonight. Everything is tied, everything is in its place. You are simply sitting inside, in a dry, warm corner.\n\nYou pull the blanket around your shoulders and lie down on the bunk. The pillow is cool, the wool is warm. You look up at the wooden beams of the ceiling. The rain is right above you, but it cannot touch you.\n\nListen to the rain. Drop by drop… and the soft tap of the rope. Your shoulders lower, and your breathing slows.\n\nYour eyes grow heavy. The rain, the rope, the rocking… all of it like one soft sound. In the morning the rain will stop and the sun will make the wet pier shine. But now it is night, and you are resting.",
    az: "Gecədir, kiçik bir limanda bağlanmış qayığın örtülü göyərtəsindəsən. Çöldə yağış yağır, amma fırtına yoxdur.\n\nKayuta kiçikdir, amma istidir. Taxta divarlar, yumru bir pəncərə, küncdə çarpayı və qalın yun yorğan. Kiçik bir sobada od səssizcə yanır.\n\nŞüşələr yüngülcə buğulanıb. Yağış damcıları şüşəyə dəyib yavaş-yavaş aşağı süzülür.\n\nBir damcını gözünlə izləyirsən. Əvvəl yavaşca sürüşür, sonra başqa bir damcı ilə birləşir və birlikdə aşağı enirlər. Sonra başqası. Tələsmədən, öz yollarını tapırlar.\n\nBir kəndir körpüdəki dirəyə yavaşca dəyir. Yumşaq, ahəngdar bir səs.\n\nQayıq suyun üstündə yüngülcə yırğalanır. Elə az ki, yalnız diqqət edəndə hiss edirsən. İrəli… geri… irəli… geri. Beşik kimi.\n\nNəfəsin bu yırğalanmaya uyğunlaşır. Qayıq qalxanda nəfəs alırsan, enəndə verirsən. Sinən yumşalır, çənən boşalır.\n\nSahildə sarı bir fənər yanır; işığı yağışda titrəyir, amma yerindən tərpənmir. Digər qayıqlar da bağlıdır, hamısı sakitdir.\n\nSobanın üstündəki çaydan yüngülcə buxar çıxarır. Özünə bir stəkan cökə çayı süzürsən. İstilik ovuclarına yayılır, ətri kayutanı doldurur.\n\nUzaqda mayakın işığı fırlanır. Hər dövrədə yağışın içindən yumşaq bir parıltı keçir. Limanın girişi təhlükəsizdir, qayıqlar təhlükəsizdir, sən də təhlükəsizsən.\n\nBu gecə növbə çəkməyə ehtiyac yoxdur. Hər şey bağlıdır, hər şey yerindədir. Sən sadəcə içəridə, quru və isti bir küncdə oturursan.\n\nYorğanı çiyinlərinə salıb çarpayıya uzanırsan. Yastıq sərin, yun isə istidir. Tavandakı taxta tirlərə baxırsan. Yağış düz üstündədir, amma sənə toxuna bilmir.\n\nYağışın səsini dinlə. Damcı, damcı… kəndirin yumşaq səsi. Çiyinlərin aşağı enir, nəfəsin yavaşlayır.\n\nGözlərin ağırlaşır. Yağış, kəndir, yırğalanma… hamısı tək bir yumşaq səs kimidir. Səhər yağış kəsiləcək, günəş yaş körpünü parladacaq. Amma indi gecədir və sən dincəlirsən.",
    ru: "Ночь. Ты на крытой палубе лодки, пришвартованной в маленькой гавани. Снаружи идёт дождь, но шторма нет.\n\nКаюта маленькая, но тёплая. Деревянные стены, круглый иллюминатор, койка в углу и толстое шерстяное одеяло. В маленькой печке тихо горит огонь.\n\nСтёкла слегка запотели. Капли падают на стекло и медленно стекают вниз.\n\nТы следишь взглядом за одной каплей. Сначала она медленно скользит, потом сливается с другой, и они стекают вместе. Потом следующая. Без спешки они находят свой путь.\n\nКанат тихо постукивает о столб на причале. Мягкий, ровный звук.\n\nЛодка слегка покачивается на воде. Так слабо, что это заметно, только если прислушаться. Вперёд… назад… вперёд… назад. Как колыбель.\n\nДыхание попадает в это покачивание. Лодка поднимается — вдох, опускается — выдох. Грудь становится мягче, челюсть расслабляется.\n\nНа пристани горит жёлтый фонарь; его свет дрожит в дожде, но сам он не двигается. Другие лодки тоже привязаны, всё спокойно.\n\nЧайник на печке тихонько выпускает пар. Ты наливаешь себе чашку липового чая. Тепло расходится по ладоням, аромат наполняет каюту.\n\nВдали вращается луч маяка. С каждым оборотом сквозь дождь проходит мягкое сияние. Вход в гавань под присмотром, лодки в безопасности, и ты в безопасности.\n\nЭтой ночью не нужно нести вахту. Всё привязано, всё на своих местах. Ты просто сидишь внутри, в сухом и тёплом углу.\n\nТы укутываешь плечи одеялом и ложишься на койку. Подушка прохладная, шерсть тёплая. Над тобой деревянные балки потолка. Дождь прямо над головой, но коснуться тебя он не может.\n\nПослушай дождь. Капля за каплей… и мягкий стук каната. Плечи опускаются, дыхание замедляется.\n\nВеки тяжелеют. Дождь, канат, покачивание… всё сливается в один мягкий звук. Утром дождь закончится, и солнце заблестит на мокром причале. Но сейчас ночь, и ты отдыхаешь.",
  },
  "lab-1.body": {
    tr: "Bu gecenin tek bir kuralı var: Yatak uyku içindir.\n\nBu kural kulağa basit geliyor ama beden için çok anlamlı. Beden, bir yerde sık sık ne yaparsan o yeri o şeyle eşleştirir. Mutfakta acıkırsın, masada işe odaklanırsın. Yatakta da uyumayı öğrenebilirsin.\n\nYatakta plan yapmamaya, tartışmamaya, telefonda gezinmemeye çalış. Böylece beden zamanla yatağı uykuyla eşleştirir.\n\nYatakta saatlerce telefona bakmak, e-postaları okumak ya da yarının planını yapmak, yatağı yavaş yavaş bir çalışma masasına çevirir. Sonra yattığında zihin uyku yerine işe hazırlanır.\n\nBu gece telefonunu yatağın yanına değil, odanın başka bir köşesine koymayı dene. Alarm için gerekiyorsa ekranı ters çevir. Böylece yatağa girdiğinde elin ona uzanmaz.\n\nUyku gelmezse yatakta dönüp durma. Kalk, loş bir köşeye geç ve sakin, sıradan bir şey yap. Belki birkaç sayfa sıkıcı bir kitap, belki sessizce oturmak.\n\nYaklaşık yirmi dakika uyuyamadığını hissedersen, saate bakmadan kalkabilirsin. Saate bakmak çoğu zaman huzursuzluğu artırır. Sadece “Bir süredir uyanığım” demen yeterli.\n\nKalktığında ışıkları parlak açma. Küçük bir lamba yeter. Ekranlara, işe, heyecan veren şeylere uzak dur. Sıkıcı olsun; sıkıcılık uykunun dostudur.\n\nUykun geldiğinde yatağa dön.\n\nBu gidip gelme ilk gecelerde yorucu olabilir. Bir gece birkaç kez kalkman gerekebilir. Bu normal. Beden yeni kuralı öğrenirken biraz zaman ister.\n\nYatağa döndüğünde bedenini yerleştir. Omuzlarını bırak, ellerini yanına koy. Bir nefes al… ve uzun uzun ver.\n\nBu gece mükemmel uyumak zorunda değilsin. Sadece yatağa yeni bir alışkanlık öğretiyorsun.\n\nŞimdi, eğer yataktaysan, bedenin yatağa değdiği yerleri fark et. Başın yastıkta, sırtın şiltede, bacakların yorganın altında. Yatak seni taşıyor. Burada yapacak başka bir iş yok.\n\nNefesini yavaşlat. Al… ve ver. Bu yatak bu gece sadece dinlenmen için var.",
    en: "Tonight has just one rule: the bed is for sleep.\n\nThis rule sounds simple, but it means a lot to the body. The body links a place with whatever you often do there. You get hungry in the kitchen; you focus at your desk. In bed, you can learn to sleep.\n\nTry not to plan, argue, or scroll in bed. Over time, your body learns to connect the bed with sleep.\n\nSpending hours on your phone in bed, reading emails or planning tomorrow slowly turns the bed into a desk. Then, when you lie down, your mind gets ready for work instead of sleep.\n\nTonight, try putting your phone not beside the bed but in another corner of the room. If you need it for the alarm, turn it face down. That way, when you get into bed, your hand will not reach for it.\n\nIf sleep does not come, do not toss and turn. Get up, go to a dim corner, and do something quiet and ordinary. Perhaps a few pages of a dull book, or simply sitting still.\n\nIf you feel you have been awake for about twenty minutes, you can get up without looking at the clock. Checking the time often makes restlessness worse. It is enough to say, “I have been awake for a while.”\n\nWhen you get up, do not switch on bright lights. A small lamp is enough. Stay away from screens, work and anything exciting. Let it be dull; dullness is a friend of sleep.\n\nWhen you feel sleepy, go back to bed.\n\nGoing back and forth like this can be tiring at first. Some nights you may need to get up more than once. That is normal. The body needs a little time to learn a new rule.\n\nWhen you return to bed, settle your body. Let your shoulders go, rest your hands by your sides. Take a breath… and let it out long and slow.\n\nYou do not have to sleep perfectly tonight. You are simply teaching your bed a new habit.\n\nNow, if you are in bed, notice where your body touches it. Your head on the pillow, your back on the mattress, your legs under the covers. The bed is holding you. There is no other job to do here.\n\nSlow your breathing. In… and out. Tonight, this bed is here only for you to rest.",
    az: "Bu gecənin yalnız bir qaydası var: Yataq yuxu üçündür.\n\nBu qayda sadə səslənir, amma bədən üçün çox mənalıdır. Bədən bir yerdə tez-tez nə edirsənsə, o yeri o işlə bağlayır. Mətbəxdə acırsan, masa arxasında işə fokuslanırsan. Yataqda da yatmağı öyrənə bilərsən.\n\nYataqda plan qurmamağa, mübahisə etməməyə, telefonda vərəqləməməyə çalış. Belə olanda bədən zamanla yatağı yuxu ilə bağlayır.\n\nYataqda saatlarla telefona baxmaq, e-poçt oxumaq və ya sabahın planını qurmaq yatağı yavaş-yavaş iş masasına çevirir. Sonra uzananda ağıl yuxuya yox, işə hazırlaşır.\n\nBu gecə telefonunu yatağın yanına yox, otağın başqa bir küncünə qoymağı sına. Zəngli saat üçün lazımdırsa, ekranını aşağı çevir. Belə olanda yatağa girəndə əlin ona uzanmayacaq.\n\nYuxu gəlməsə, yataqda o yan-bu yana çevrilmə. Qalx, yarıqaranlıq bir küncə keç və sakit, adi bir şey et. Bəlkə darıxdırıcı bir kitabdan bir neçə səhifə, bəlkə də sadəcə səssizcə oturmaq.\n\nTəxminən iyirmi dəqiqə yata bilmədiyini hiss etsən, saata baxmadan qalxa bilərsən. Saata baxmaq çox vaxt narahatlığı artırır. Sadəcə “Bir müddətdir oyağam” demək kifayətdir.\n\nQalxanda parlaq işıqları yandırma. Kiçik bir lampa kifayətdir. Ekranlardan, işdən, həyəcanlandıran şeylərdən uzaq dur. Qoy darıxdırıcı olsun; darıxdırıcılıq yuxunun dostudur.\n\nYuxun gələndə yatağa qayıt.\n\nBu gediş-gəliş ilk gecələrdə yorucu ola bilər. Bir gecədə bir neçə dəfə qalxmalı ola bilərsən. Bu normaldır. Bədən yeni qaydanı öyrənəndə bir az vaxt istəyir.\n\nYatağa qayıdanda bədənini yerləşdir. Çiyinlərini burax, əllərini yanına qoy. Bir nəfəs al… və uzun-uzun ver.\n\nBu gecə mükəmməl yatmağa borclu deyilsən. Sadəcə yatağa yeni bir vərdiş öyrədirsən.\n\nİndi, əgər yataqdasansa, bədəninin yatağa toxunduğu yerləri hiss et. Başın yastıqda, kürəyin döşəkdə, ayaqların yorğanın altında. Yataq səni saxlayır. Burada başqa iş yoxdur.\n\nNəfəsini yavaşlat. Al… və ver. Bu yataq bu gecə yalnız sənin dincəlməyin üçündür.",
    ru: "У этой ночи только одно правило: кровать — для сна.\n\nЭто правило звучит просто, но для тела оно очень важно. Тело связывает место с тем, что ты там часто делаешь. На кухне хочется есть, за столом легче сосредоточиться. В постели тоже можно научиться засыпать.\n\nПостарайся не строить планы, не спорить и не листать телефон в постели. Со временем тело начнёт связывать кровать со сном.\n\nЧасы с телефоном в постели, чтение почты или планы на завтра понемногу превращают кровать в рабочий стол. И потом, когда ложишься, ум готовится не ко сну, а к работе.\n\nЭтой ночью попробуй положить телефон не у кровати, а в другом углу комнаты. Если он нужен для будильника, переверни его экраном вниз. Тогда, ложась, рука не будет тянуться к нему.\n\nЕсли сон не приходит, не ворочайся. Встань, перейди в полутёмный уголок и займись чем-то спокойным и обычным. Например, пару страниц скучной книги или просто тихо посиди.\n\nЕсли кажется, что не спится уже минут двадцать, можно встать, не глядя на часы. Взгляд на часы чаще всего только усиливает беспокойство. Достаточно сказать себе: «Я не сплю уже какое-то время».\n\nКогда встаёшь, не включай яркий свет. Хватит маленькой лампы. Держись подальше от экранов, работы и всего, что будоражит. Пусть будет скучно; скука — подруга сна.\n\nКогда почувствуешь сонливость, возвращайся в кровать.\n\nПоначалу такие хождения туда-обратно могут утомлять. В какую-то ночь придётся вставать несколько раз. Это нормально. Телу нужно немного времени, чтобы выучить новое правило.\n\nВернувшись в постель, устрой тело удобно. Отпусти плечи, положи руки вдоль тела. Вдох… и долгий медленный выдох.\n\nСегодня не нужно спать идеально. Ты просто учишь свою кровать новой привычке.\n\nСейчас, если ты в постели, заметь, где тело её касается. Голова на подушке, спина на матрасе, ноги под одеялом. Кровать держит тебя. Других дел здесь нет.\n\nЗамедли дыхание. Вдох… и выдох. Этой ночью эта кровать здесь только для твоего отдыха.",
  },
  "lab-2.body": {
    tr: "Yatma saatin biraz değişebilir, ama kalkış saatini her gün aynı tutmaya çalış. Hafta sonları bile.\n\nBedenin içinde bir saat çalışır. Ne zaman acıkacağını, ne zaman uyanık olacağını, ne zaman uykunun geleceğini bu saat belirler. En çok da sabah ışığına ve uyanma saatine bakarak ayarlanır.\n\nHer gün farklı saatlerde kalkınca bu saat şaşırır. Sanki her gün başka bir ülkeye uçmuşsun gibi hafif bir yorgunluk olur. Sabit bir kalkış saati ise ona net bir işaret verir.\n\nBu bir ceza değil. Sabit bir kalkış saati, bedenin iç saati için güvenilir bir kıyı gibidir. Gece ona yaslanır.\n\nKendin için gerçekçi bir saat seç. Çok erken olmasın; her gün tutabileceğin bir saat olsun. Alarmı kur ve bu hafta boyunca aynı saatte kalkmayı dene.\n\nAlarm çaldığında erteleme tuşuna basmamaya çalış. Kısa ertelemeler çoğu zaman dinlendirmez, sadece uyanmayı zorlaştırır.\n\nKötü bir geceden sonra uzun uzun uyuyarak açığı kapatmaya çalışma. Bu, bir sonraki geceyi zorlaştırabilir.\n\nKötü bir geceden sonra gün içinde yorgun hissedebilirsin. Bu normal. Kısa bir öğle uykusu istersen yirmi dakikayı geçmesin ve öğleden sonra çok geç olmasın.\n\nYorgunluk aslında bir sonraki gece sana yardım eder. Akşam daha kolay uyku gelir. Beden kendi dengesini bulur.\n\nSabah kalkınca perdeyi aç ve gün ışığını gör. Beden böylece günün başladığını öğrenir.\n\nMümkünse sabah birkaç dakika dışarı çık ya da pencere önünde dur. Bulutlu bir gün bile içerideki lambadan çok daha fazla ışık verir. Bir fincan çayı ya da kahveyi pencere kenarında içebilirsin.\n\nAkşam ise ışıkları yavaş yavaş kıs. Parlak beyaz ışıklar yerine sarı, loş lambalar kullan. Beden böylece gecenin yaklaştığını anlar.\n\nBu gece yatağa uzandığında yarın sabah kalkacağın saati bir kez hatırla. Sonra onu bırak. Sabah orada olacak; sen şimdi dinlenebilirsin. Bir nefes al… ve yavaşça ver.",
    en: "Your bedtime can shift a little, but try to keep your wake-up time the same every day. Even at weekends.\n\nInside your body there is a clock. It decides when you feel hungry, when you feel alert, and when sleep comes. It sets itself mostly by morning light and by the time you wake up.\n\nWhen you get up at a different time every day, this clock gets confused. It is a bit like flying to a different country every day; a mild tiredness follows. A steady wake-up time gives it a clear signal.\n\nThis is not a punishment. A steady wake-up time is like a reliable shore for your body clock. The night can lean on it.\n\nChoose a realistic time for yourself. Not too early; a time you can keep every day. Set the alarm and try to get up at the same time all this week.\n\nWhen the alarm goes off, try not to press snooze. Short snoozes rarely rest you; they mostly make waking up harder.\n\nAfter a bad night, try not to make up for it by sleeping in for hours. That can make the next night harder.\n\nAfter a bad night you may feel tired during the day. That is normal. If you want a short nap, keep it under twenty minutes and not too late in the afternoon.\n\nTiredness actually helps you the next night. Sleep comes more easily in the evening. The body finds its own balance.\n\nWhen you get up, open the curtains and see the daylight. That is how your body learns the day has begun.\n\nIf you can, step outside for a few minutes in the morning, or stand by a window. Even a cloudy day gives far more light than an indoor lamp. You could drink your tea or coffee by the window.\n\nIn the evening, dim the lights little by little. Use warm, low lamps instead of bright white ones. That is how the body understands that night is coming.\n\nTonight, when you lie down, remember once the time you will get up tomorrow. Then let it go. The morning will be there; right now you can rest. Take a breath… and let it out slowly.",
    az: "Yatma vaxtın bir az dəyişə bilər, amma oyanma vaxtını hər gün eyni saxlamağa çalış. Hətta həftə sonları da.\n\nBədənin içində bir saat işləyir. Nə vaxt acacağını, nə vaxt oyaq olacağını, nə vaxt yuxunun gələcəyini bu saat müəyyən edir. Ən çox da səhər işığına və oyanma vaxtına baxaraq tənzimlənir.\n\nHər gün fərqli saatlarda qalxanda bu saat çaşır. Sanki hər gün başqa ölkəyə uçmusan, yüngül bir yorğunluq olur. Sabit oyanma vaxtı isə ona aydın bir işarə verir.\n\nBu cəza deyil. Sabit oyanma vaxtı bədənin daxili saatı üçün etibarlı bir sahil kimidir. Gecə ona söykənir.\n\nÖzün üçün real bir saat seç. Çox erkən olmasın; hər gün saxlaya biləcəyin bir saat olsun. Zəngli saatı qur və bu həftə boyu eyni saatda qalxmağa çalış.\n\nZəng çalanda təxirə salma düyməsini basmamağa çalış. Qısa təxirlər çox vaxt dincəltmir, sadəcə oyanmağı çətinləşdirir.\n\nPis bir gecədən sonra saatlarla yataraq əvəzini çıxmağa çalışma. Bu, növbəti gecəni çətinləşdirə bilər.\n\nPis bir gecədən sonra gün ərzində yorğun hiss edə bilərsən. Bu normaldır. Qısa günorta yuxusu istəsən, iyirmi dəqiqədən çox olmasın və günortadan sonra çox gec olmasın.\n\nYorğunluq əslində növbəti gecə sənə kömək edir. Axşam yuxu daha asan gəlir. Bədən öz tarazlığını tapır.\n\nSəhər qalxanda pərdəni aç və gün işığını gör. Bədən belə öyrənir ki, gün başlayıb.\n\nMümkünsə, səhər bir neçə dəqiqə bayıra çıx və ya pəncərənin qarşısında dayan. Buludlu bir gün belə otaqdakı lampadan qat-qat çox işıq verir. Çayını və ya qəhvəni pəncərə kənarında içə bilərsən.\n\nAxşam isə işıqları yavaş-yavaş azalt. Parlaq ağ işıqların yerinə sarı, zəif lampalardan istifadə et. Bədən belə anlayır ki, gecə yaxınlaşır.\n\nBu gecə yatağa uzananda sabah qalxacağın saatı bir dəfə xatırla. Sonra onu burax. Səhər orada olacaq; sən isə indi dincələ bilərsən. Bir nəfəs al… və yavaşca ver.",
    ru: "Время отхода ко сну может немного меняться, но время подъёма старайся держать одинаковым каждый день. Даже в выходные.\n\nВнутри тела работают часы. Они решают, когда хочется есть, когда ты бодрствуешь и когда приходит сон. Настраиваются они больше всего по утреннему свету и по времени подъёма.\n\nКогда встаёшь каждый день в разное время, эти часы сбиваются. Как будто каждый день перелетаешь в другую страну: появляется лёгкая усталость. А постоянное время подъёма даёт им ясный сигнал.\n\nЭто не наказание. Постоянное время подъёма — как надёжный берег для внутренних часов. Ночь может на него опереться.\n\nВыбери для себя реалистичное время. Не слишком раннее; такое, которое можно держать каждый день. Поставь будильник и попробуй всю эту неделю вставать в одно и то же время.\n\nКогда звонит будильник, постарайся не нажимать «отложить». Короткие отсрочки редко дают отдых, они скорее делают пробуждение труднее.\n\nПосле плохой ночи не пытайся отоспаться долгими часами. Это может сделать следующую ночь труднее.\n\nПосле плохой ночи днём может быть усталость. Это нормально. Если хочется подремать, пусть это будет не дольше двадцати минут и не слишком поздно днём.\n\nУсталость на самом деле помогает следующей ночью. Вечером сон приходит легче. Тело само находит равновесие.\n\nУтром, когда встанешь, открой шторы и посмотри на дневной свет. Так тело узнаёт, что день начался.\n\nЕсли получится, выйди утром на несколько минут на улицу или постой у окна. Даже пасмурный день даёт гораздо больше света, чем лампа в комнате. Чай или кофе можно выпить у окна.\n\nА вечером понемногу приглушай свет. Вместо ярких белых ламп используй тёплые и неяркие. Так тело понимает, что приближается ночь.\n\nЭтой ночью, когда ложишься, один раз вспомни, во сколько завтра вставать. А потом отпусти это. Утро никуда не денется; сейчас можно отдыхать. Вдох… и медленный выдох.",
  },
  "lab-3.body": {
    tr: "Gece yatınca zihin bazen bir mahkemeye dönüşür: “Uyuyamazsam yarın mahvolur.” “Şunu neden yaptım?”\n\nGece zihin farklı çalışır. Gündüz küçük görünen bir sorun gece büyür. Yorgun beyin tehlikeleri daha büyük, çözümleri daha uzak görür. Bu senin suçun değil; gecenin doğası böyle.\n\nBu yüzden gece verilen kararlara ve gece kurulan cümlelere çok güvenme. Sabah aynı düşünce çoğu zaman daha küçük ve daha yönetilebilir görünür.\n\nBu düşüncelerle tartışmana gerek yok. Onları fark et ve zihninde bir rafa kaldır: “Bunu yarın düşüneceğim.”\n\nRafa kaldırmak, düşünceyi bastırmak demek değil. Onu görüyorsun, adını koyuyorsun ve şimdilik bir kenara koyuyorsun. “Bu bir iş endişesi. Yarın öğlen bakarım.”\n\nBazen düşünce yeniden gelir. O zaman aynı cümleyi sakin bir sesle tekrar et. Tartışmadan, kızmadan. Rafa geri koy.\n\nGün içinde bir endişe penceresi açtıysan, gece defter kapalıdır. Endişelerin zaten bir yeri var.\n\nYorgun bir beden de ertesi gün iş görebilir. Bir gecelik kötü uyku her şeyi mahvetmez.\n\nUyuyamamaktan korkmak, uykuyu daha da uzaklaştırır. Uyumaya çalıştıkça uyku kaçar. O yüzden bu gece hedefin uyumak değil, dinlenmek olsun.\n\nGözlerin kapalı, bedenin rahat bir şekilde yatmak da bedene iyi gelir. Uyku gelirse gelsin; gelmezse de dinleniyorsun.\n\nBu gece hâkim koltuğundan kalk. Kimseyi, kendini de, yargılaman gerekmiyor.\n\nŞimdi bedenine dön. Alnını gevşet. Çeneni bırak. Omuzlarının yatağa doğru indiğini hisset. Ellerin açık ve yumuşak.\n\nNefes al… ve ver. Her verişte bir düşünceyi rafa koyduğunu hayal et. Raf sağlam, düşünceler orada bekleyebilir. Sen bu gece hâkim değil, dinlenen birisin.",
    en: "At night, the mind can turn into a courtroom: “If I can’t sleep, tomorrow is ruined.” “Why did I do that?”\n\nAt night the mind works differently. A problem that looks small in the day grows bigger at night. A tired brain sees dangers as larger and solutions as further away. This is not your fault; it is simply the nature of night.\n\nSo do not put too much trust in decisions made at night, or in sentences formed at night. In the morning, the same thought often looks smaller and more manageable.\n\nYou do not need to argue with these thoughts. Notice them, and put them on a shelf in your mind: “I will think about this tomorrow.”\n\nPutting a thought on the shelf does not mean pushing it down. You see it, you name it, and you set it aside for now. “This is a work worry. I will look at it at lunchtime tomorrow.”\n\nSometimes the thought comes back. Then repeat the same sentence in a calm voice. Without arguing, without getting angry. Put it back on the shelf.\n\nIf you opened a worry window during the day, the notebook stays closed at night. Your worries already have a place.\n\nA tired body can still get through the next day. One poor night does not ruin everything.\n\nFear of not sleeping pushes sleep further away. The harder you try to sleep, the more it slips away. So tonight, let your goal be rest, not sleep.\n\nLying with your eyes closed and your body at ease is good for the body too. If sleep comes, let it come; if it does not, you are still resting.\n\nTonight, step down from the judge’s chair. You do not have to put anyone on trial, including yourself.\n\nNow come back to your body. Soften your forehead. Let your jaw go. Feel your shoulders sinking towards the bed. Your hands are open and soft.\n\nBreathe in… and out. With each out-breath, imagine placing one thought on the shelf. The shelf is sturdy; the thoughts can wait there. Tonight you are not the judge; you are someone resting.",
    az: "Gecə yatanda ağıl bəzən məhkəməyə çevrilir: “Yata bilməsəm, sabah hər şey məhv olacaq.” “Bunu niyə etdim?”\n\nGecə ağıl fərqli işləyir. Gündüz kiçik görünən problem gecə böyüyür. Yorğun beyin təhlükələri daha böyük, həll yollarını daha uzaq görür. Bu sənin günahın deyil; gecənin təbiəti belədir.\n\nOna görə də gecə verilən qərarlara və gecə qurulan cümlələrə çox güvənmə. Səhər eyni fikir çox vaxt daha kiçik və daha idarəolunan görünür.\n\nBu fikirlərlə mübahisə etməyə ehtiyac yoxdur. Onları hiss et və ağlında bir rəfə qoy: “Bu barədə sabah düşünəcəyəm.”\n\nRəfə qoymaq fikri basdırmaq demək deyil. Onu görürsən, adını qoyursan və hələlik bir kənara qoyursan. “Bu, iş narahatlığıdır. Sabah günorta baxaram.”\n\nBəzən fikir yenidən gəlir. Onda eyni cümləni sakit səslə təkrarla. Mübahisə etmədən, hirslənmədən. Yenidən rəfə qoy.\n\nGün ərzində narahatlıq pəncərəsi açmısansa, gecə dəftər bağlıdır. Narahatlıqlarının artıq bir yeri var.\n\nYorğun bədən də ertəsi gün işini görə bilər. Bir gecəlik pis yuxu hər şeyi məhv etmir.\n\nYata bilməməkdən qorxmaq yuxunu daha da uzaqlaşdırır. Yatmağa çalışdıqca yuxu qaçır. Ona görə də bu gecə hədəfin yatmaq yox, dincəlmək olsun.\n\nGözlərin bağlı, bədənin rahat uzanması da bədənə xeyirdir. Yuxu gəlsə, qoy gəlsin; gəlməsə də, sən dincəlirsən.\n\nBu gecə hakim kreslosundan qalx. Heç kimi, özünü də, mühakimə etməyə ehtiyac yoxdur.\n\nİndi bədəninə qayıt. Alnını boşalt. Çənəni burax. Çiyinlərinin yatağa doğru endiyini hiss et. Əllərin açıq və yumşaqdır.\n\nNəfəs al… və ver. Hər nəfəs verəndə bir fikri rəfə qoyduğunu təsəvvür et. Rəf möhkəmdir, fikirlər orada gözləyə bilər. Sən bu gecə hakim yox, dincələn bir insansan.",
    ru: "Ночью ум иногда превращается в зал суда: «Если я не усну, завтра всё пропало». «Почему всё так вышло?»\n\nНочью ум работает иначе. Проблема, которая днём кажется маленькой, ночью вырастает. Уставший мозг видит опасности крупнее, а решения дальше. Это не твоя вина; такова природа ночи.\n\nПоэтому не стоит слишком доверять решениям, принятым ночью, и фразам, сложившимся ночью. Утром та же мысль часто кажется меньше и вполне решаемой.\n\nСпорить с этими мыслями не нужно. Замечай их и откладывай на полку в уме: «Подумаю об этом завтра».\n\nОтложить мысль на полку — не значит подавить её. Ты её видишь, называешь и пока откладываешь. «Это рабочая тревога. Посмотрю завтра в обед».\n\nИногда мысль возвращается. Тогда спокойно повтори ту же фразу. Без спора, без раздражения. Снова на полку.\n\nЕсли днём было открыто окно тревоги, ночью тетрадь закрыта. У тревог уже есть своё место.\n\nУставшее тело тоже справится с завтрашним днём. Одна плохая ночь не разрушает всё.\n\nСтрах не уснуть отодвигает сон ещё дальше. Чем больше стараешься уснуть, тем дальше он ускользает. Поэтому сегодня пусть целью будет не сон, а отдых.\n\nЛежать с закрытыми глазами и расслабленным телом тоже полезно. Придёт сон — хорошо; не придёт — ты всё равно отдыхаешь.\n\nЭтой ночью встань из судейского кресла. Никого не нужно судить — и себя тоже.\n\nТеперь вернись к телу. Расслабь лоб. Отпусти челюсть. Почувствуй, как плечи опускаются к кровати. Руки открыты и мягки.\n\nВдох… и выдох. С каждым выдохом представляй, что кладёшь одну мысль на полку. Полка крепкая, мысли могут там подождать. Этой ночью ты не судья, а просто человек, который отдыхает.",
  },
  "lab-4.body": {
    tr: "Bu gece yatmadan önce kısa, sakin bir ritüel kur ve her gece aynı sırayla tekrarla.\n\nRitüel yaklaşık yirmi ya da otuz dakika sürebilir. Uzun olması gerekmiyor. Önemli olan, beden için açık bir “gün bitti” işareti olması.\n\nÖrneğin: Işıkları kıs. Ekranları kapat. Ilık bir su ya da bitki çayı iç, ya da birkaç dakika yavaşça esne. Sonra yatağa geç.\n\nIşıkları kısmak gözlerine ve bedenine akşam olduğunu söyler. Ekranları kapatmak zihnine yeni bilgi akışını durdurur. Haberler, mesajlar, videolar… hepsi yarına kadar bekleyebilir.\n\nIlık bir duş da ritüelin parçası olabilir. Sıcak sudan sonra beden yavaşça serinler ve bu serinleme uykuya geçişi kolaylaştırır.\n\nEsnemeyi yaparken acele etme. Kollarını yukarı uzat, sonra yavaşça indir. Boynunu bir yana, sonra diğer yana eğ. Omuzlarını birkaç kez geriye doğru çevir.\n\nBu sihir değil, bir işaret. Beden aynı sırayı her gece gördükçe uykunun yaklaştığını öğrenir.\n\nÇocuklar için akşam rutinleri neden işe yarıyorsa, yetişkinler için de aynı nedenle işe yarar. Banyo, pijama, masal, ışıklar kapalı. Beden sırayı tanır ve kendiliğinden yavaşlar.\n\nRitüeli mükemmel yapmaya çalışma. Basit ve hep aynı olması yeterli.\n\nBazı akşamlar ritüelin tamamını yapamayabilirsin. Geç kalmışsındır ya da yorgunsundur. O zaman sadece bir adımı yap: ışıkları kıs ve birkaç yavaş nefes al. Bu da işaret verir.\n\nBu gece ritüelinin son adımı olarak birlikte nefes alalım. Burnundan dörde kadar say ve nefes al… bir, iki, üç, dört. Ağzından altıya kadar sayarak ver… bir, iki, üç, dört, beş, altı.\n\nBir kez daha. Al… ve uzun uzun ver. Bedenin yavaşlıyor. Ritüel tamam. Şimdi dinlenme zamanı.",
    en: "Tonight, create a short, calm ritual before bed, and repeat it in the same order every night.\n\nThe ritual can take about twenty or thirty minutes. It does not need to be long. What matters is that it gives the body a clear signal: the day is over.\n\nFor example: dim the lights. Switch off the screens. Drink some warm water or herbal tea, or stretch slowly for a few minutes. Then get into bed.\n\nDimming the lights tells your eyes and body that it is evening. Switching off screens stops the flow of new information into your mind. News, messages, videos… all of them can wait until tomorrow.\n\nA warm shower can be part of the ritual too. After warm water, the body slowly cools down, and that cooling makes it easier to drift into sleep.\n\nWhen you stretch, do not rush. Reach your arms up, then lower them slowly. Tilt your head to one side, then the other. Roll your shoulders back a few times.\n\nThis is not magic; it is a signal. When the body sees the same order every night, it learns that sleep is near.\n\nBedtime routines work for adults for the same reason they work for children. Bath, pyjamas, a story, lights off. The body recognises the order and slows down by itself.\n\nDo not try to make the ritual perfect. It only needs to be simple and the same.\n\nSome evenings you may not manage the whole ritual. You are late, or too tired. Then do just one step: dim the lights and take a few slow breaths. That still sends the signal.\n\nAs the last step of tonight's ritual, let us breathe together. Breathe in through your nose for four… one, two, three, four. Breathe out through your mouth for six… one, two, three, four, five, six.\n\nOnce more. In… and a long, slow out. Your body is slowing down. The ritual is complete. Now it is time to rest.",
    az: "Bu gecə yatmazdan əvvəl qısa, sakit bir ritual qur və hər gecə eyni ardıcıllıqla təkrarla.\n\nRitual təxminən iyirmi-otuz dəqiqə çəkə bilər. Uzun olması vacib deyil. Əsas odur ki, bədən üçün aydın bir “gün bitdi” işarəsi olsun.\n\nMəsələn: İşıqları azalt. Ekranları söndür. İlıq su və ya bitki çayı iç, ya da bir neçə dəqiqə yavaşca dartın. Sonra yatağa keç.\n\nİşıqları azaltmaq gözlərinə və bədəninə axşam olduğunu deyir. Ekranları söndürmək ağlına yeni məlumat axınını dayandırır. Xəbərlər, mesajlar, videolar… hamısı sabaha qədər gözləyə bilər.\n\nİlıq duş da ritualın bir hissəsi ola bilər. İsti sudan sonra bədən yavaş-yavaş sərinləyir və bu sərinləmə yuxuya keçidi asanlaşdırır.\n\nDartınanda tələsmə. Qollarını yuxarı uzat, sonra yavaşca endir. Başını bir tərəfə, sonra o biri tərəfə əy. Çiyinlərini bir neçə dəfə geriyə fırlat.\n\nBu sehr deyil, bir işarədir. Bədən hər gecə eyni ardıcıllığı görəndə yuxunun yaxınlaşdığını öyrənir.\n\nUşaqlar üçün axşam rejimi niyə işə yarayırsa, böyüklər üçün də eyni səbəbdən işə yarayır. Vanna, pijama, nağıl, işıqlar sönür. Bədən ardıcıllığı tanıyır və öz-özünə yavaşlayır.\n\nRitualı mükəmməl etməyə çalışma. Sadə və həmişə eyni olması kifayətdir.\n\nBəzi axşamlar ritualın hamısını edə bilməyəcəksən. Gecikmisən və ya yorğunsan. Onda yalnız bir addım at: işıqları azalt və bir neçə yavaş nəfəs al. Bu da işarə verir.\n\nBu gecə ritualın son addımı kimi birlikdə nəfəs alaq. Burnundan dördə qədər sayaraq nəfəs al… bir, iki, üç, dörd. Ağzından altıya qədər sayaraq ver… bir, iki, üç, dörd, beş, altı.\n\nBir dəfə də. Al… və uzun-uzun ver. Bədənin yavaşlayır. Ritual tamamdır. İndi dincəlmək vaxtıdır.",
    ru: "Этим вечером создай короткий спокойный ритуал перед сном и повторяй его каждый вечер в одном и том же порядке.\n\nРитуал может занимать минут двадцать или тридцать. Длинным ему быть не нужно. Главное, чтобы для тела это был ясный сигнал: день закончился.\n\nНапример: приглуши свет. Выключи экраны. Выпей тёплой воды или травяного чая, или несколько минут медленно потянись. Потом ложись в постель.\n\nПриглушённый свет говорит глазам и телу, что настал вечер. Выключенные экраны останавливают поток новой информации. Новости, сообщения, видео… всё это может подождать до завтра.\n\nТёплый душ тоже может быть частью ритуала. После тёплой воды тело постепенно остывает, и это остывание облегчает переход ко сну.\n\nКогда потягиваешься, не спеши. Подними руки вверх, потом медленно опусти. Наклони голову в одну сторону, потом в другую. Несколько раз покрути плечами назад.\n\nЭто не волшебство, а сигнал. Когда тело каждый вечер видит один и тот же порядок, оно понимает, что скоро сон.\n\nВечерние привычки работают для взрослых по той же причине, что и для детей. Ванна, пижама, сказка, свет выключен. Тело узнаёт порядок и само замедляется.\n\nНе старайся сделать ритуал идеальным. Достаточно, чтобы он был простым и всегда одинаковым.\n\nБывают вечера, когда весь ритуал не получается. Поздно или слишком много усталости. Тогда сделай хотя бы один шаг: приглуши свет и сделай несколько медленных вдохов. Это тоже сигнал.\n\nКак последний шаг сегодняшнего ритуала давай подышим вместе. Вдох носом на четыре… раз, два, три, четыре. Выдох ртом на шесть… раз, два, три, четыре, пять, шесть.\n\nЕщё раз. Вдох… и долгий, медленный выдох. Тело замедляется. Ритуал завершён. Теперь время отдыхать.",
  },
  "lab-5.body": {
    tr: "Bu gece uykuya tek bir sakin görüntüyle geç. Bir kartpostal gibi: kapalı bir bahçe, güneşte ısınmış bir taş, yanan bir lamba.\n\nUykuya dalmadan önceki dakikalarda zihin çoğu zaman günün kalıntılarıyla doludur. Konuşmalar, yapılacaklar, yarının planı. Tek bir sakin görüntü, bu kalabalığın yerine yumuşak bir şey koyar.\n\nGörüntüyü önceden seçebilirsin. Belki bir hikâyeden hatırladığın bir yer, belki gerçek bir anı. Önemli olan sakin, sıcak ve sade olması.\n\nÖnce bedenini yumuşat. Omuzlarını bırak, çeneni gevşet, nefesini yavaşlat.\n\nBunu yaparken acele etme. Alnından başla. Kaşlarının arası açılsın. Gözlerinin etrafı yumuşasın. Dilin damağından ayrılsın. Boynun yastığa yerleşsin.\n\nSonra omuzlar, kollar, eller. Göğüs, karın. Kalçalar, bacaklar, ayaklar. Her bölüm biraz daha ağır, biraz daha sıcak.\n\nSonra görüntüyü bir kez hatırla. Onu sürekli tekrarlamana ya da büyütmene gerek yok.\n\nGörüntünün ayrıntılarına nazikçe bak. Taşın üstündeki ışık, lambanın sarı halkası, bahçe duvarının üstünden sarkan bir dal. Sonra ayrıntıları bırak ve görüntünün genel sakinliğinde kal.\n\nZihnin başka bir yere giderse, bu çok normal. Fark ettiğinde, kendini suçlamadan görüntüye geri dön. Bir taş, bir lamba, bir bahçe.\n\nUyku bir görev değil. Sen sadece kapıyı aralık bırakıyorsun; gerisi kendiliğinden gelir.\n\nBu gece birlikte deneyelim. Gözlerini kapat. Bir nefes al ve yavaşça ver. Şimdi seçtiğin görüntünün içinde olduğunu hayal et. Orada hava ılık. Işık yumuşak. Her şey yerinde.\n\nOrada bir süre kal. Hiçbir şey yapmana gerek yok. Sadece bak… ve dinlen. Nefesin yavaş, bedenin ağır, görüntün sakin.\n\nUyku geldiğinde, görüntü yavaşça silinecek. Bunu bilmene bile gerek yok. Kapı aralık, gece seni bekliyor.",
    en: "Tonight, drift into sleep with one calm image. Like a postcard: a walled garden, a stone warm from the sun, a glowing lamp.\n\nIn the minutes before sleep, the mind is often full of leftovers from the day. Conversations, to-do lists, tomorrow's plans. A single calm image puts something soft in place of that crowd.\n\nYou can choose the image in advance. Perhaps a place you remember from a story, perhaps a real memory. What matters is that it is calm, warm and simple.\n\nFirst, soften your body. Let your shoulders drop, loosen your jaw, and slow your breathing.\n\nTake your time with this. Start at your forehead. Let the space between your eyebrows open. Let the area around your eyes soften. Let your tongue drop from the roof of your mouth. Let your neck settle into the pillow.\n\nThen your shoulders, arms and hands. Your chest, your belly. Your hips, legs and feet. Each part a little heavier, a little warmer.\n\nThen recall the image once. You do not need to keep repeating it or make it bigger.\n\nLook gently at the details of the image. The light on the stone, the yellow ring of the lamp, a branch hanging over the garden wall. Then let the details go and stay with the overall calm of the image.\n\nIf your mind wanders somewhere else, that is completely normal. When you notice, return to the image without blaming yourself. A stone, a lamp, a garden.\n\nSleep is not a task. You are simply leaving the door ajar; the rest comes by itself.\n\nLet us try it together tonight. Close your eyes. Take a breath and let it out slowly. Now imagine you are inside the image you chose. The air there is mild. The light is soft. Everything is in its place.\n\nStay there for a while. You do not need to do anything. Just look… and rest. Your breath is slow, your body is heavy, your image is calm.\n\nWhen sleep comes, the image will slowly fade. You do not even need to know when. The door is ajar, and the night is waiting for you.",
    az: "Bu gecə yuxuya tək bir sakit görüntü ilə get. Açıqca kimi: bağlı bir bağ, günəşdə qızmış bir daş, yanan bir lampa.\n\nYuxuya getməzdən əvvəlki dəqiqələrdə ağıl çox vaxt günün qalıqları ilə dolu olur. Söhbətlər, görüləsi işlər, sabahın planı. Tək bir sakit görüntü bu izdihamın yerinə yumşaq bir şey qoyur.\n\nGörüntünü əvvəlcədən seçə bilərsən. Bəlkə bir hekayədən yadında qalan bir yer, bəlkə həqiqi bir xatirə. Əsas odur ki, sakit, isti və sadə olsun.\n\nƏvvəlcə bədənini yumşalt. Çiyinlərini burax, çənəni boşalt, nəfəsini yavaşlat.\n\nBunu edəndə tələsmə. Alnından başla. Qaşlarının arası açılsın. Gözlərinin ətrafı yumşalsın. Dilin damağından ayrılsın. Boynun yastığa yerləşsin.\n\nSonra çiyinlər, qollar, əllər. Sinə, qarın. Ombalar, ayaqlar, pəncələr. Hər hissə bir az da ağır, bir az da isti.\n\nSonra görüntünü bir dəfə xatırla. Onu durmadan təkrarlamağa və ya böyütməyə ehtiyac yoxdur.\n\nGörüntünün təfərrüatlarına yumşaqca bax. Daşın üstündəki işıq, lampanın sarı halqası, bağ divarının üstündən sallanan budaq. Sonra təfərrüatları burax və görüntünün ümumi sakitliyində qal.\n\nAğlın başqa yerə getsə, bu çox normaldır. Fərqinə varanda özünü qınamadan görüntüyə qayıt. Bir daş, bir lampa, bir bağ.\n\nYuxu tapşırıq deyil. Sən sadəcə qapını aralı qoyursan; qalanı öz-özünə gəlir.\n\nBu gecə birlikdə sınayaq. Gözlərini yum. Bir nəfəs al və yavaşca ver. İndi seçdiyin görüntünün içində olduğunu təsəvvür et. Orada hava ilıqdır. İşıq yumşaqdır. Hər şey yerindədir.\n\nOrada bir müddət qal. Heç nə etməyə ehtiyac yoxdur. Sadəcə bax… və dincəl. Nəfəsin yavaş, bədənin ağır, görüntün sakitdir.\n\nYuxu gələndə görüntü yavaş-yavaş silinəcək. Bunu bilməyinə belə ehtiyac yoxdur. Qapı aralıdır, gecə səni gözləyir.",
    ru: "Этой ночью засыпай с одним спокойным образом. Как открытка: закрытый сад, нагретый солнцем камень, горящая лампа.\n\nВ минуты перед сном ум часто полон остатков дня. Разговоры, дела, планы на завтра. Один спокойный образ ставит на место этой толпы что-то мягкое.\n\nОбраз можно выбрать заранее. Может быть, место из рассказа, может быть, настоящее воспоминание. Главное, чтобы он был спокойным, тёплым и простым.\n\nСначала расслабь тело. Опусти плечи, разожми челюсть, замедли дыхание.\n\nНе торопись. Начни со лба. Пусть разгладится место между бровями. Пусть смягчится кожа вокруг глаз. Пусть язык отойдёт от нёба. Пусть шея удобно ляжет на подушку.\n\nПотом плечи, руки, кисти. Грудь, живот. Таз, ноги, стопы. Каждая часть чуть тяжелее и чуть теплее.\n\nПотом один раз вспомни образ. Не нужно постоянно повторять его или делать больше.\n\nМягко рассмотри детали образа. Свет на камне, жёлтый круг от лампы, ветка, свисающая через садовую стену. Потом отпусти детали и останься в общем спокойствии образа.\n\nЕсли ум уходит в сторону, это совершенно нормально. Когда это заметно, без упрёков возвращайся к образу. Камень, лампа, сад.\n\nСон — это не задача. Ты просто оставляешь дверь приоткрытой; остальное придёт само.\n\nДавай попробуем вместе этой ночью. Закрой глаза. Сделай вдох и медленный выдох. Теперь представь, что ты внутри выбранного образа. Воздух там мягкий. Свет приглушённый. Всё на своих местах.\n\nПобудь там немного. Ничего делать не нужно. Просто смотри… и отдыхай. Дыхание медленное, тело тяжёлое, образ спокойный.\n\nКогда придёт сон, образ медленно растает. Даже не нужно знать, когда именно. Дверь приоткрыта, ночь ждёт тебя.",
  },
  "lab-6.body": {
    tr: "Bugün öğleden sonra on dakikanı ayır ve aklındaki endişeleri bir kâğıda yaz.\n\nBu fikir şuna dayanır: Endişeler gece aniden gelmez; gün boyunca birikir. Yatağa girdiğinde, nihayet sessizlik olduğunda, hepsi birden ortaya çıkar. Onlara gündüz bir yer açarsan, gece daha az kalabalık olur.\n\nÖğleden sonra ya da akşamüstü, yatmadan en az birkaç saat önce bir zaman seç. Masaya otur, bir kâğıt ve kalem al.\n\nSüre dolunca dur. Kâğıdı katla ve kaldır.\n\nYazarken her endişenin yanına küçük bir not ekleyebilirsin. “Bununla ilgili yarın yapabileceğim tek bir küçük adım ne?” Bazen bir adım olur: bir telefon, bir e-posta. Bazen hiç olmaz; o da sorun değil.\n\nBazı endişeler senin kontrolünde değildir. Onların yanına sadece şunu yazabilirsin: “Bu benim elimde değil.” Bu cümle, onları taşımak zorunda olmadığını hatırlatır.\n\nGece o kâğıda geri dönme. Endişelerin gündüz yazıldı, yerleri belli.\n\nKâğıdı yatak odanın dışında bir yere koy. Mutfak çekmecesi, çalışma masası, bir kitabın arası. Yatak odası endişelerin değil, dinlenmenin odası olsun.\n\nBöylece yatak endişelerin değil, uykunun yeri olarak kalır. Gece aklına yine bir şey gelirse kendine hatırlat: “Bunu gündüz yazdım, yarın bakarım.”\n\nBu gece yatağa uzandığında, aklına bir endişe gelirse onu kâğıda yazılmış hâliyle düşün. Katlanmış, çekmecede duruyor. Seninle yatakta değil.\n\nBir nefes al ve yavaşça ver. Bedenin yatakta, endişelerin kâğıtta. İkisi ayrı yerlerde. Sen şimdi dinlenebilirsin.\n\nYarın aynı saatte yine on dakika ayırabilirsin. Endişeler bir randevuya sahip olunca gece daha az ısrar ederler.",
    en: "This afternoon, take ten minutes and write down the worries on your mind.\n\nThe idea behind this is simple: worries do not suddenly appear at night; they build up during the day. When you get into bed and it is finally quiet, they all come out at once. If you give them a place during the day, the night is less crowded.\n\nChoose a time in the afternoon or early evening, at least a few hours before bed. Sit at a table with a piece of paper and a pen.\n\nWhen the time is up, stop. Fold the paper and put it away.\n\nAs you write, you can add a small note next to each worry. “What is one small step I could take on this tomorrow?” Sometimes there is a step: a phone call, an email. Sometimes there is none, and that is fine too.\n\nSome worries are not in your control. Next to those, you can simply write: “This is not in my hands.” That sentence reminds you that you do not have to carry them.\n\nDo not go back to that paper at night. Your worries were written during the day; they have their place.\n\nKeep the paper somewhere outside your bedroom. A kitchen drawer, your desk, between the pages of a book. Let the bedroom be a room for rest, not for worry.\n\nThis way, the bed stays a place for sleep, not for worry. If something comes up at night, remind yourself: “I wrote this down today. I will look at it tomorrow.”\n\nTonight, when you lie down, if a worry comes to mind, think of it as written on that paper. Folded, sitting in the drawer. Not here in bed with you.\n\nTake a breath and let it out slowly. Your body is in bed, your worries are on the paper. They are in different places. Right now you can rest.\n\nTomorrow you can set aside ten minutes at the same time again. When worries have an appointment, they insist less at night.",
    az: "Bu gün günortadan sonra on dəqiqə ayır və ağlındakı narahatlıqları kağıza yaz.\n\nBu fikrin mənası belədir: narahatlıqlar gecə birdən-birə gəlmir; gün ərzində yığılır. Yatağa girəndə, nəhayət sükut olanda, hamısı birdən üzə çıxır. Onlara gündüz yer ayırsan, gecə daha az izdiham olur.\n\nGünortadan sonra və ya axşamüstü, yatmazdan ən azı bir neçə saat əvvəl bir vaxt seç. Masa arxasında otur, kağız və qələm götür.\n\nVaxt bitəndə dayan. Kağızı qatla və qaldır.\n\nYazanda hər narahatlığın yanına kiçik bir qeyd əlavə edə bilərsən. “Bununla bağlı sabah ata biləcəyim kiçik bir addım nədir?” Bəzən bir addım olur: bir zəng, bir məktub. Bəzən heç olmur; bu da problem deyil.\n\nBəzi narahatlıqlar sənin əlində deyil. Onların yanına sadəcə bunu yaza bilərsən: “Bu mənim əlimdə deyil.” Bu cümlə onları daşımağa məcbur olmadığını xatırladır.\n\nGecə o kağıza qayıtma. Narahatlıqların gündüz yazıldı, yerləri bəllidir.\n\nKağızı yataq otağından kənarda bir yerə qoy. Mətbəx siyirməsi, iş masası, bir kitabın arası. Qoy yataq otağı narahatlığın yox, dincəlməyin otağı olsun.\n\nBelə olanda yataq narahatlığın yox, yuxunun yeri olaraq qalır. Gecə ağlına yenə nəsə gəlsə, özünə xatırlat: “Bunu gündüz yazmışam, sabah baxaram.”\n\nBu gecə yatağa uzananda ağlına bir narahatlıq gəlsə, onu kağıza yazılmış halda düşün. Qatlanıb, siyirmədə durur. Səninlə yataqda deyil.\n\nBir nəfəs al və yavaşca ver. Bədənin yataqda, narahatlıqların kağızdadır. İkisi ayrı yerlərdədir. Sən indi dincələ bilərsən.\n\nSabah eyni saatda yenə on dəqiqə ayıra bilərsən. Narahatlıqların görüş vaxtı olanda, gecə daha az israr edirlər.",
    ru: "Сегодня после обеда выдели десять минут и запиши на листке всё, что тревожит.\n\nИдея здесь простая: тревоги не появляются ночью внезапно, они копятся весь день. Когда ложишься и наконец становится тихо, они выходят все разом. Если днём дать им место, ночью будет меньше толпы.\n\nВыбери время днём или ранним вечером, хотя бы за несколько часов до сна. Сядь за стол с листком бумаги и ручкой.\n\nКогда время выйдет, остановись. Сложи листок и убери его.\n\nРядом с каждой тревогой можно добавить небольшую пометку: «Какой один маленький шаг я могу сделать по этому поводу завтра?» Иногда шаг есть: звонок, письмо. Иногда его нет, и это тоже нормально.\n\nНекоторые тревоги тебе неподвластны. Рядом с ними можно просто написать: «Это не в моих руках». Эта фраза напоминает, что нести их не обязательно.\n\nНочью к этому листку не возвращайся. Тревоги записаны днём, у них есть своё место.\n\nПоложи листок где-нибудь вне спальни. В кухонный ящик, на рабочий стол, между страницами книги. Пусть спальня будет комнатой для отдыха, а не для тревог.\n\nТак кровать остаётся местом для сна, а не для тревог. Если ночью что-то снова придёт в голову, напомни себе: «Это уже записано днём, посмотрю завтра».\n\nЭтой ночью, когда ложишься, если придёт тревога, думай о ней как о записанной на том листке. Сложенной и лежащей в ящике. Не здесь, в кровати, рядом с тобой.\n\nСделай вдох и медленный выдох. Тело в кровати, тревоги на бумаге. Они в разных местах. Сейчас можно отдыхать.\n\nЗавтра в то же время можно снова выделить десять минут. Когда у тревог есть назначенная встреча, ночью они настаивают меньше.",
  },
  "lab-7.body": {
    tr: "Bu hafta küçük adımlar öğrendin. Yatak sadece uyku için. Kalkış saatin sabit. Gece mahkeme yok. Yatmadan önce aynı yavaşlama ritüeli. Uykuya tek bir görüntü. Endişeleri gündüz yazmak.\n\nBunlar küçük adımlar ama birlikte güçlüdürler. Her biri bedene ve zihne aynı mesajı verir: Gece dinlenme zamanıdır, gündüz de iş ve endişe zamanı.\n\nBir an geçen haftayı düşün. Hangi adım sana en kolay geldi? Hangisi biraz fark yarattı? Belki kalkış saatini tutmak, belki akşam ışıklarını kısmak. Onu hatırla.\n\nHepsini birden mükemmel yapmaya çalışma. Bu gece içlerinden birini seç ve ona devam et.\n\nSeçtiğin adımı bir hafta daha sürdür. Sonra istersen bir tane daha ekle. Alışkanlıklar yavaş yavaş, birbirinin üstüne kurulur.\n\nKendine küçük bir hatırlatma bırakabilirsin. Komodinin üstüne bir not, telefonda akşam için bir hatırlatıcı. “Işıkları kıs.” “Telefon başka odada.”\n\nBazı geceler yine zor olabilir. Bu, başarısız olduğun anlamına gelmez. Düzen yavaş yavaş oturur.\n\nUyku hayat gibi dalgalıdır. Stresli dönemlerde, hastalıkta, seyahatte bozulabilir. Bu adımlar o zamanlarda da geri dönebileceğin bir yol haritasıdır.\n\nUyku sorunların haftalarca sürüyor ve gününü ciddi şekilde etkiliyorsa, bir doktorla konuşmak da iyi bir adımdır. Yardım istemek de düzenin bir parçasıdır.\n\nBu gece kendine nazik ol ve bırak.\n\nŞimdi bu haftayı birlikte kapatalım. Yatağına uzan ya da rahatça otur. Işıklar kısık, ekranlar kapalı.\n\nBir nefes al… ve uzun uzun ver. Bedenini yukarıdan aşağı yumuşat: alnın, çenen, omuzların, ellerin, karnın, bacakların, ayakların.\n\nSeçtiğin sakin görüntüyü bir kez hatırla. Sonra bırak. Bu hafta kendine özen gösterdin. Bu gece de dinlenmeyi hak ediyorsun.",
    en: "This week you learned a few small steps. The bed is only for sleep. Your wake-up time is steady. No courtroom at night. The same wind-down ritual before bed. One image for sleep. Writing your worries during the day.\n\nThese are small steps, but together they are strong. Each one gives the body and mind the same message: night is for rest, and the day is for work and worry.\n\nThink back over the past week for a moment. Which step felt easiest? Which one made a bit of a difference? Perhaps keeping your wake-up time, perhaps dimming the lights in the evening. Remember that one.\n\nDo not try to do them all perfectly at once. Tonight, choose one and keep going with it.\n\nKeep going with the step you chose for another week. Then, if you like, add one more. Habits build slowly, one on top of another.\n\nYou can leave yourself a small reminder. A note on the bedside table, an evening reminder on your phone. “Dim the lights.” “Phone in the other room.”\n\nSome nights may still be hard. That does not mean you have failed. A routine settles in slowly.\n\nSleep comes in waves, like life. It can be disrupted by stress, illness or travel. These steps are a map you can return to at those times too.\n\nIf your sleep problems last for weeks and seriously affect your days, talking to a doctor is a good step as well. Asking for help is part of the routine too.\n\nTonight, be kind to yourself, and let go.\n\nNow let us close this week together. Lie down in bed or sit comfortably. The lights are low, the screens are off.\n\nTake a breath… and let it out long and slow. Soften your body from top to bottom: your forehead, your jaw, your shoulders, your hands, your belly, your legs, your feet.\n\nRecall your calm image once. Then let it go. This week you looked after yourself. Tonight, too, you deserve to rest.",
    az: "Bu həftə kiçik addımlar öyrəndin. Yataq yalnız yuxu üçündür. Oyanma vaxtın sabitdir. Gecə məhkəmə yoxdur. Yatmazdan əvvəl eyni sakitləşmə ritualı. Yuxuya tək bir görüntü. Narahatlıqları gündüz yazmaq.\n\nBunlar kiçik addımlardır, amma birlikdə güclüdürlər. Hər biri bədənə və ağla eyni mesajı verir: gecə dincəlmək vaxtıdır, gündüz isə iş və narahatlıq vaxtı.\n\nBir anlıq keçən həftəni düşün. Hansı addım sənə ən asan gəldi? Hansı bir az fərq yaratdı? Bəlkə oyanma vaxtını saxlamaq, bəlkə axşam işıqları azaltmaq. Onu xatırla.\n\nHamısını birdən mükəmməl etməyə çalışma. Bu gecə onlardan birini seç və onu davam etdir.\n\nSeçdiyin addımı bir həftə də davam etdir. Sonra istəsən, birini də əlavə et. Vərdişlər yavaş-yavaş, bir-birinin üstündə qurulur.\n\nÖzünə kiçik bir xatırlatma qoya bilərsən. Tumbanın üstündə bir qeyd, telefonda axşam üçün bir xatırladıcı. “İşıqları azalt.” “Telefon başqa otaqda.”\n\nBəzi gecələr yenə çətin ola bilər. Bu, uğursuz olduğun demək deyil. Qayda yavaş-yavaş oturur.\n\nYuxu da həyat kimi dalğalıdır. Stresli dövrlərdə, xəstəlikdə, səfərdə poza bilər. Bu addımlar o vaxtlarda da qayıda biləcəyin bir yol xəritəsidir.\n\nYuxu problemlərin həftələrlə davam edirsə və gününə ciddi təsir edirsə, həkimlə danışmaq da yaxşı addımdır. Kömək istəmək də rejimin bir hissəsidir.\n\nBu gecə özünə qarşı mehriban ol və burax.\n\nİndi bu həftəni birlikdə bağlayaq. Yatağına uzan və ya rahat otur. İşıqlar zəifdir, ekranlar sönülüb.\n\nBir nəfəs al… və uzun-uzun ver. Bədənini yuxarıdan aşağı yumşalt: alnın, çənən, çiyinlərin, əllərin, qarnın, ayaqların, pəncələrin.\n\nSeçdiyin sakit görüntünü bir dəfə xatırla. Sonra burax. Bu həftə özünə qayğı göstərdin. Bu gecə də dincəlməyə layiqsən.",
    ru: "На этой неделе было несколько маленьких шагов. Кровать — только для сна. Постоянное время подъёма. Ночью нет суда. Один и тот же ритуал замедления перед сном. Один образ для сна. Записывать тревоги днём.\n\nЭто маленькие шаги, но вместе они сильны. Каждый даёт телу и уму одно и то же послание: ночь — для отдыха, а день — для дел и тревог.\n\nВспомни на мгновение прошедшую неделю. Какой шаг дался легче всего? Какой немного что-то изменил? Может быть, постоянное время подъёма, может быть, приглушённый вечерний свет. Запомни его.\n\nНе пытайся сразу делать всё идеально. Этой ночью выбери один шаг и продолжай его.\n\nПродолжай выбранный шаг ещё неделю. Потом, если захочется, добавь ещё один. Привычки складываются постепенно, одна на другую.\n\nМожно оставить себе маленькое напоминание. Записку на тумбочке, вечернее напоминание в телефоне. «Приглушить свет». «Телефон в другой комнате».\n\nНекоторые ночи всё ещё могут быть трудными. Это не значит, что ничего не получилось. Режим складывается постепенно.\n\nСон, как и жизнь, идёт волнами. Он может сбиться от стресса, болезни или поездки. Эти шаги — карта, к которой можно вернуться и в такие времена.\n\nЕсли проблемы со сном длятся неделями и сильно влияют на твои дни, поговорить с врачом — тоже хороший шаг. Просить о помощи — тоже часть заботы о себе.\n\nЭтой ночью будь к себе добрее и отпусти.\n\nТеперь давай вместе завершим эту неделю. Ляг в постель или сядь удобно. Свет приглушён, экраны выключены.\n\nВдох… и долгий медленный выдох. Смягчи тело сверху вниз: лоб, челюсть, плечи, руки, живот, ноги, стопы.\n\nОдин раз вспомни свой спокойный образ. Потом отпусти его. На этой неделе ты заботишься о себе. И этой ночью тебе тоже можно отдохнуть.",
  },
  "lamp-cat.body": {
    tr: "Küçük, sıcak bir odadasın. Köşede sarı bir lamba yanıyor; ışığı her şeyi yumuşatıyor.\n\nDışarıda serin bir sonbahar gecesi var. Pencerenin ardında rüzgâr yaprakları hafifçe savuruyor. Ama içerisi sıcak; perdeler kapalı, kalorifer usulca tıkırdıyor.\n\nHalının üzerinde bir kedi kıvrılmış uyuyor. Karnı her nefeste yavaşça inip kalkıyor.\n\nKedinin kuyruğu burnunun üstüne kıvrılmış. Arada bir kulağı hafifçe oynuyor, sonra yine hareketsiz kalıyor. Tüyleri lambanın ışığında yumuşak bir altın rengine bürünmüş.\n\nMırıltısını duyuyorsun. Alçak, düzenli, sıcak bir ses. Bu ses odanın sessizliğini dolduruyor ve seni yavaşça içine çekiyor.\n\nSen rahat bir koltuktasın. Üzerinde ince bir örtü var.\n\nYanındaki küçük masada bir fincan ılık süt duruyor. Fincanı ellerinin arasına alıyorsun. Sıcaklık parmaklarından bileklerine yayılıyor. Bir yudum alıyor ve fincanı geri koyuyorsun.\n\nAyaklarını koltuğun altındaki pufa uzatıyorsun. Örtüyü dizlerine kadar çekiyorsun. Koltuk bedenini bütünüyle taşıyor; başın, sırtın, kolların.\n\nKedinin nefesini izle. Yavaş… derin… huzurlu. Senin nefesin de farkında olmadan onunkine uymaya başlıyor.\n\nNefes al… kedinin karnı yükseliyor. Nefes ver… alçalıyor. Bir kez daha. Odada iki nefes var ve ikisi de yavaş, ikisi de güvende.\n\nKedi uykusunda hafifçe gerinip patilerini uzatıyor, sonra yeniden kıvrılıyor. Sen de bedenini biraz uzat. Omuzlarını, kollarını, parmaklarını. Sonra yeniden yerleş.\n\nOdada saat yok, yapılacaklar listesi yok. Sadece lambanın ışığı, kedinin sıcaklığı ve sessizlik var.\n\nLambanın ışığı duvarda yumuşak bir daire çiziyor. Gölgeler kıpırdamıyor. Odanın her köşesi tanıdık ve sakin. Burada hiçbir şey seni beklemiyor.\n\nKedi uyumayı biliyor. Endişelenmiyor, bir şey planlamıyor. Sen de bu gece ondan biraz öğrenebilirsin.\n\nBir süre sonra kedi kalkıp yavaşça kucağına geliyor. Ağırlığı sıcak ve hafif. Kıvrılıp yeniden uyuyor. Elini sırtına koyuyorsun ve mırıltısı avucunda titriyor.\n\nGözlerin ağırlaşıyor. Lamba yanıyor, kedi uyuyor, gece sessiz. Sen de dinlenebilirsin.",
    en: "You are in a small, warm room. A yellow lamp glows in the corner, and its light softens everything.\n\nOutside it is a cool autumn night. Beyond the window the wind lifts the leaves gently. But inside it is warm; the curtains are drawn, and the radiator ticks softly.\n\nOn the rug, a cat lies curled up asleep. Its belly rises and falls slowly with each breath.\n\nThe cat's tail is curled over its nose. Now and then one ear twitches, then is still again. Its fur has turned a soft gold in the lamplight.\n\nYou hear it purring. A low, steady, warm sound. It fills the quiet of the room and slowly draws you in.\n\nYou are in a comfortable armchair, with a light throw over your knees.\n\nOn the small table beside you there is a cup of warm milk. You take the cup in your hands. The warmth spreads from your fingers to your wrists. You take a sip and put the cup back.\n\nYou stretch your feet out onto the footstool. You pull the throw up to your knees. The armchair holds your whole body; your head, your back, your arms.\n\nWatch the cat breathe. Slow… deep… peaceful. Without noticing, your own breath begins to match it.\n\nBreathe in… the cat's belly rises. Breathe out… it falls. Once more. There are two breaths in this room, both slow, both safe.\n\nIn its sleep the cat stretches a little, reaching out its paws, then curls up again. Stretch your body a little too. Your shoulders, your arms, your fingers. Then settle again.\n\nThere is no clock in the room and no to-do list. Only the lamplight, the warmth of the cat, and silence.\n\nThe lamplight draws a soft circle on the wall. The shadows do not move. Every corner of the room is familiar and calm. Nothing here is waiting for you.\n\nThe cat knows how to sleep. It does not worry or make plans. Tonight, you can learn a little from it.\n\nAfter a while the cat gets up and slowly climbs into your lap. Its weight is warm and light. It curls up and falls asleep again. You rest your hand on its back, and its purr trembles in your palm.\n\nYour eyes grow heavy. The lamp is glowing, the cat is sleeping, the night is quiet. You can rest too.",
    az: "Kiçik, isti bir otaqdasan. Küncdə sarı bir lampa yanır; işığı hər şeyi yumşaldır.\n\nÇöldə sərin bir payız gecəsidir. Pəncərənin arxasında külək yarpaqları yüngülcə sovurur. Amma içəri istidir; pərdələr çəkilib, radiator yavaşca tıqqıldayır.\n\nXalçanın üstündə bir pişik qıvrılıb yatıb. Qarnı hər nəfəsdə yavaşca qalxıb enir.\n\nPişiyin quyruğu burnunun üstünə qıvrılıb. Arabir qulağı yüngülcə tərpənir, sonra yenə hərəkətsiz qalır. Tükləri lampanın işığında yumşaq qızılı rəngə çalır.\n\nOnun mırıltısını eşidirsən. Alçaq, ahəngdar, isti bir səs. Bu səs otağın sükutunu doldurur və səni yavaş-yavaş özünə çəkir.\n\nSən rahat bir kresloda oturmusan. Dizlərinin üstündə nazik bir örtük var.\n\nYanındakı kiçik masada bir fincan ilıq süd durur. Fincanı əllərinin arasına alırsan. İstilik barmaqlarından biləklərinə yayılır. Bir qurtum içib fincanı yerinə qoyursan.\n\nAyaqlarını kreslonun qarşısındakı puffa uzadırsan. Örtüyü dizlərinə qədər çəkirsən. Kreslo bədənini bütünlüklə saxlayır; başını, kürəyini, qollarını.\n\nPişiyin nəfəsinə bax. Yavaş… dərin… rahat. Sənin nəfəsin də hiss etmədən onunkuna uyğunlaşmağa başlayır.\n\nNəfəs al… pişiyin qarnı qalxır. Nəfəs ver… enir. Bir dəfə də. Otaqda iki nəfəs var, ikisi də yavaş, ikisi də təhlükəsiz.\n\nPişik yuxuda yüngülcə gərnəşib pəncələrini uzadır, sonra yenə qıvrılır. Sən də bədənini bir az uzat. Çiyinlərini, qollarını, barmaqlarını. Sonra yenə yerləş.\n\nOtaqda saat yoxdur, görüləsi işlərin siyahısı yoxdur. Sadəcə lampanın işığı, pişiyin istiliyi və sükut.\n\nLampanın işığı divarda yumşaq bir dairə çəkir. Kölgələr tərpənmir. Otağın hər küncü tanış və sakitdir. Burada heç nə səni gözləmir.\n\nPişik yatmağı bilir. Narahat olmur, heç nə planlaşdırmır. Bu gecə sən də ondan bir az öyrənə bilərsən.\n\nBir azdan pişik qalxıb yavaşca qucağına gəlir. Ağırlığı isti və yüngüldür. Qıvrılıb yenə yuxuya gedir. Əlini onun belinə qoyursan və mırıltısı ovucunda titrəyir.\n\nGözlərin ağırlaşır. Lampa yanır, pişik yatır, gecə sakitdir. Sən də dincələ bilərsən.",
    ru: "Ты в маленькой тёплой комнате. В углу горит жёлтая лампа, и её свет смягчает всё вокруг.\n\nЗа окном прохладная осенняя ночь. Ветер тихо шевелит листья. Но в комнате тепло: шторы задёрнуты, батарея негромко постукивает.\n\nНа ковре, свернувшись клубком, спит кошка. Её живот медленно поднимается и опускается с каждым вдохом.\n\nХвост кошки обвит вокруг носа. Иногда у неё подрагивает ухо, потом она снова неподвижна. Шерсть в свете лампы отливает мягким золотом.\n\nСлышно, как она мурлычет. Низкий, ровный, тёплый звук. Он заполняет тишину комнаты и потихоньку убаюкивает тебя.\n\nТы сидишь в удобном кресле, на коленях лёгкий плед.\n\nНа столике рядом стоит чашка тёплого молока. Ты берёшь её в руки. Тепло переходит от пальцев к запястьям. Глоток — и чашка снова на столе.\n\nНоги можно вытянуть на пуфик. Плед поднимается до колен. Кресло держит всё тело: голову, спину, руки.\n\nПосмотри, как дышит кошка. Медленно… глубоко… спокойно. Твоё дыхание незаметно начинает подстраиваться под её.\n\nВдох… живот кошки поднимается. Выдох… опускается. Ещё раз. В комнате два дыхания, оба медленные, оба в безопасности.\n\nВо сне кошка слегка потягивается, вытягивает лапы и снова сворачивается клубком. Потянись немного и ты. Плечи, руки, пальцы. А потом снова устройся поудобнее.\n\nВ комнате нет часов и нет списка дел. Только свет лампы, тепло кошки и тишина.\n\nСвет лампы рисует на стене мягкий круг. Тени не двигаются. Каждый уголок комнаты знакомый и спокойный. Здесь ничто тебя не ждёт.\n\nКошка умеет спать. Она не тревожится и ничего не планирует. Этой ночью можно немного поучиться у неё.\n\nЧерез какое-то время кошка встаёт и медленно забирается к тебе на колени. Её вес тёплый и лёгкий. Она сворачивается и снова засыпает. Ты кладёшь руку ей на спину, и мурлыканье дрожит под ладонью.\n\nВеки тяжелеют. Лампа горит, кошка спит, ночь тихая. Тебе тоже можно отдохнуть.",
  },
  "library.body": {
    tr: "Yüksek bir vadide, dağların arasında taştan eski bir kütüphane var. Kapısı açık, içerisi serin ve sessiz.\n\nOraya ulaşmak için dar bir patikadan yürüyorsun. Hava ince ve temiz, çam ağaçlarının kokusu seninle birlikte yukarı tırmanıyor. Kütüphanenin taş duvarları akşam güneşinde hafifçe ısınmış.\n\nİçeri giriyorsun. Raflar tavana kadar uzanıyor; sayısız kitap yan yana, sabırla bekliyor. Kimseyi aceleye getirmiyorlar.\n\nKitapların sırtlarına göz gezdiriyorsun. Bazıları deri kaplı, bazılarının yazısı silinmiş. Hepsinin bir hikâyesi var ama bu gece hiçbiri senden dikkat istemiyor. Parmak uçlarınla bir rafın kenarına dokunuyorsun; ahşap pürüzsüz ve ılık.\n\nAdımların taş zeminde yumuşak bir yankı bırakıyor. Yavaşça yürüyorsun, sırf yürümek için. Koridorun sonunda geniş bir pencere var ve oradan vadinin aşağısı görünüyor.\n\nPencerenin yanında ahşap bir masa buluyorsun. Üzerinde kapalı bir kitap duruyor. Onu açmana gerek yok. Ellerini masanın ılık ahşabına koyuyorsun.\n\nPencereden dışarı bakıyorsun. Vadinin dibinde ince bir nehir kıvrılıyor, karşı yamaçta birkaç ev ışığı yanıyor. Dağların tepeleri hâlâ biraz pembe; gün yavaşça çekiliyor.\n\nSandalye seni rahatça taşıyor. Omuzların aşağı iniyor, çenen gevşiyor. Bir süre sadece çeşmenin sesini dinliyorsun. Su akıyor, akmaya devam ediyor; bir yere yetişmeye çalışmıyor.\n\nUzaklarda bir yerde bir sayfa çevriliyor, sonra yine sessizlik. Avluda küçük bir çeşme ince ince akıyor.\n\nPencereden süzülen ışığın içinde toz zerreleri yavaşça dans ediyor. Onları izliyorsun. Hiçbiri acele etmiyor.\n\nBiri, belki kütüphanenin yaşlı bekçisi, masanın köşesine bir fincan ıhlamur bırakmış. Buharı yavaşça yükseliyor. Fincanı iki elinle tutuyorsun ve sıcaklığı avuçlarına yayılıyor.\n\nIşık giderek azalıyor. Bekçi koridorun ucundaki küçük lambaları birer birer yakıyor. Her lamba rafların bir köşesini sarı bir ışıkla dolduruyor. Kütüphane daha da sessiz, daha da sıcak bir yer hâline geliyor.\n\nAyakların yerde, sırtın sandalyeye yaslanmış. Burada okunması, bitirilmesi ya da hatırlanması gereken hiçbir şey yok. Sadece sessiz raflar… ve sen.\n\nGözlerini kapatırsan bile raflar orada. Kitaplar bekliyor, çeşme akıyor, lambalar yanıyor. Bütün bu sessizlik seni yavaşça sarıyor. Nefesin uzuyor, bedenin ağırlaşıyor.\n\nBu gece hiçbir şey öğrenmen gerekmiyor. Sadece burada, yüksek vadinin sessiz kütüphanesinde, sıcak bir fincan ve kapalı bir kitapla dinlen.",
    en: "High in a valley between the mountains stands an old stone library. The door is open, and inside it is cool and quiet.\n\nTo reach it, you walk up a narrow path. The air is thin and clean, and the smell of pine climbs with you. The library's stone walls are still a little warm from the evening sun.\n\nYou step in. The shelves rise all the way to the ceiling, with countless books side by side, waiting patiently. They are in no hurry, and neither is anyone here.\n\nYou let your eyes wander along the spines of the books. Some are bound in leather; on others the lettering has faded. Each one has a story, but tonight none of them asks for your attention. You touch the edge of a shelf with your fingertips; the wood is smooth and warm.\n\nYour footsteps leave a soft echo on the stone floor. You walk slowly, just for the sake of walking. At the end of the hall there is a wide window, and through it you can see down into the valley.\n\nBy the window you find a wooden table. A closed book rests on it. You do not need to open it. You lay your hands on the warm wood.\n\nYou look out of the window. At the bottom of the valley a thin river winds along, and on the far slope a few house lights are glowing. The mountain tops are still a little pink; the day is slowly drawing back.\n\nThe chair holds you comfortably. Your shoulders drop, your jaw loosens. For a while you simply listen to the fountain. The water flows, and keeps on flowing; it is not trying to get anywhere.\n\nSomewhere far off a page turns, and then there is silence again. In the courtyard a small fountain trickles softly.\n\nIn the light from the window, specks of dust drift slowly. You watch them. None of them is in a hurry.\n\nSomeone, perhaps the library's old keeper, has left a cup of linden tea at the corner of the table. Its steam rises slowly. You hold the cup in both hands, and the warmth spreads into your palms.\n\nThe light is fading. The keeper lights the small lamps at the end of the hall, one by one. Each lamp fills a corner of the shelves with a soft yellow glow. The library becomes even quieter, even warmer.\n\nYour feet are on the floor, your back against the chair. There is nothing here to read, to finish, or to remember. Only the quiet shelves… and you.\n\nEven if you close your eyes, the shelves are still there. The books are waiting, the fountain is flowing, the lamps are glowing. All this quiet slowly wraps around you. Your breath grows longer, your body heavier.\n\nTonight there is nothing you need to learn. Just rest here, in the quiet library of the high valley, with a warm cup and a closed book.",
    az: "Dağların arasında, yüksək bir dərədə daşdan tikilmiş köhnə bir kitabxana var. Qapısı açıqdır, içəri sərin və sakitdir.\n\nOra çatmaq üçün dar bir cığırla yuxarı qalxırsan. Hava incə və təmizdir, şam ağaclarının qoxusu da səninlə birlikdə yuxarı dırmaşır. Kitabxananın daş divarları axşam günəşində hələ də bir az istidir.\n\nİçəri girirsən. Rəflər tavana qədər uzanır; saysız-hesabsız kitab yan-yana səbirlə gözləyir. Heç kimi tələsdirmirlər.\n\nKitabların cildlərinə göz gəzdirirsən. Bəziləri dəri cildlidir, bəzilərinin yazısı silinib. Hər birinin öz hekayəsi var, amma bu gecə heç biri səndən diqqət istəmir. Barmaqlarının ucu ilə rəfin kənarına toxunursan; taxta hamar və ilıqdır.\n\nAddımların daş döşəmədə yumşaq bir əks-səda buraxır. Yavaş-yavaş, sadəcə yeriyə-yeriyə gedirsən. Dəhlizin sonunda geniş bir pəncərə var və oradan dərənin aşağısı görünür.\n\nPəncərənin yanında taxta bir masa tapırsan. Üstündə bağlı bir kitab durur. Onu açmağa ehtiyac yoxdur. Əllərini masanın ilıq taxtasına qoyursan.\n\nPəncərədən bayıra baxırsan. Dərənin dibində incə bir çay qıvrılır, qarşı yamacda bir neçə evin işığı yanır. Dağların zirvələri hələ də bir az çəhrayıdır; gün yavaş-yavaş çəkilir.\n\nStul səni rahatca saxlayır. Çiyinlərin aşağı enir, çənən boşalır. Bir müddət sadəcə bulağın səsini dinləyirsən. Su axır, axmağa davam edir; heç yerə çatmağa tələsmir.\n\nUzaqda haradasa bir səhifə çevrilir, sonra yenə sükut. Həyətdə kiçik bir bulaq incə-incə axır.\n\nPəncərədən süzülən işığın içində toz zərrələri yavaşca süzülür. Onlara baxırsan. Heç biri tələsmir.\n\nKimsə, bəlkə də kitabxananın qoca gözətçisi, masanın küncünə bir fincan cökə çayı qoyub. Buxarı yavaşca qalxır. Fincanı iki əllə tutursan və istilik ovuclarına yayılır.\n\nİşıq getdikcə azalır. Gözətçi dəhlizin sonundakı kiçik lampaları bir-bir yandırır. Hər lampa rəflərin bir küncünü sarı işıqla doldurur. Kitabxana daha da sakit, daha da isti olur.\n\nAyaqların yerdədir, kürəyin stula söykənib. Burada oxumalı, bitirməli və ya yadda saxlamalı heç nə yoxdur. Sadəcə sakit rəflər… və sən.\n\nGözlərini yumsan da, rəflər oradadır. Kitablar gözləyir, bulaq axır, lampalar yanır. Bütün bu sükut səni yavaş-yavaş bürüyür. Nəfəsin uzanır, bədənin ağırlaşır.\n\nBu gecə heç nə öyrənməyə ehtiyac yoxdur. Sadəcə burada, yüksək dərənin sakit kitabxanasında, isti bir fincan və bağlı bir kitabla dincəl.",
    ru: "Высоко в долине, среди гор, стоит старая каменная библиотека. Дверь открыта, внутри прохладно и тихо.\n\nТуда ведёт узкая тропинка. Воздух тонкий и чистый, запах сосен поднимается вместе с тобой. Каменные стены библиотеки ещё хранят тепло вечернего солнца.\n\nТы входишь. Полки поднимаются до самого потолка; бесчисленные книги стоят рядом и терпеливо ждут. Они никуда не спешат.\n\nТы скользишь взглядом по корешкам. Одни в кожаных переплётах, на других надписи почти стёрлись. У каждой книги своя история, но этой ночью ни одна не просит твоего внимания. Ты касаешься края полки кончиками пальцев; дерево гладкое и тёплое.\n\nШаги отзываются мягким эхом на каменном полу. Ты идёшь медленно, просто чтобы идти. В конце зала широкое окно, и из него видно долину внизу.\n\nУ окна ты находишь деревянный стол. На нём лежит закрытая книга. Открывать её не нужно. Ты кладёшь ладони на тёплое дерево.\n\nТы смотришь в окно. На дне долины вьётся тонкая река, на дальнем склоне горят огни нескольких домов. Вершины гор ещё немного розовые; день медленно уходит.\n\nСтул удобно держит тебя. Плечи опускаются, челюсть расслабляется. Какое-то время ты просто слушаешь фонтан. Вода течёт и продолжает течь; ей некуда спешить.\n\nГде-то вдалеке переворачивается страница, и снова тишина. Во дворе тихо журчит маленький фонтан.\n\nВ свете из окна медленно кружатся пылинки. Ты смотришь на них. Ни одна не торопится.\n\nКто-то, может быть, старый смотритель библиотеки, оставил на краю стола чашку липового чая. Пар медленно поднимается. Ты берёшь чашку обеими руками, и тепло расходится по ладоням.\n\nСвет понемногу гаснет. Смотритель одну за другой зажигает маленькие лампы в конце зала. Каждая наполняет уголок полок мягким жёлтым светом. Библиотека становится ещё тише и ещё теплее.\n\nНоги стоят на полу, спина опирается на спинку стула. Здесь не нужно ничего читать, заканчивать или запоминать. Только тихие полки… и ты.\n\nДаже если закрыть глаза, полки остаются здесь. Книги ждут, фонтан журчит, лампы горят. Вся эта тишина медленно окутывает тебя. Дыхание становится длиннее, тело тяжелее.\n\nЭтой ночью не нужно ничему учиться. Просто отдыхай здесь, в тихой библиотеке высокой долины, с тёплой чашкой и закрытой книгой.",
  },
  "lighthouse.body": {
    tr: "Sakin bir gece. Kayalık bir burnun ucunda beyaz bir deniz feneri duruyor ve bu gece onun bekçisi sensin. Rüzgâr dinmiş, deniz neredeyse kıpırtısız.\n\nFeneri ilk kez yakından görüyorsun. Beyaz duvarları gece karanlığında hafifçe parlıyor, kapısının üstünde eski bir demir halka asılı. Kapıyı itiyorsun; menteşeler alçak bir sesle gıcırdıyor ve içeriden serin taş kokusu geliyor.\n\nTaş merdivenden yavaşça çıkıyorsun. Bir elin serin duvarda, havada hafif bir tuz kokusu var. Her basamakta adımların biraz daha yavaşlıyor.\n\nMerdiven döne döne yukarı çıkıyor. Arada bir dar bir pencere beliriyor ve her pencereden denizin başka bir parçasını görüyorsun. Biraz duruyorsun, nefesini dinliyorsun, sonra yeniden yavaşça çıkmaya devam ediyorsun.\n\nYukarıda, lamba odasında camlar tertemiz. Pencerenin önündeki eski sandalyeye oturuyorsun. Aşağıda koy boş, birkaç tekne usulca sallanıyor.\n\nMontunu çıkarıp sandalyenin arkasına asıyorsun. Ayaklarını küçük bir tabureye uzatıyorsun. Odada yalnızca lambanın derinden gelen hafif uğultusu var; düzenli, tanıdık, güven veren bir ses.\n\nLamba ağır ağır dönüyor. Işık denizin üstünden geçiyor, kıyıyı okşuyor, sonra yeniden karanlığa karışıyor. Her dönüş aynı sakin düzenle.\n\nIşığı gözünle takip ediyorsun. Önce sağdaki kayalara dokunuyor, sonra açık denize uzanıyor, sonra yavaşça geri dönüyor. Her geçişte deniz bir an gümüş gibi parlıyor, sonra yeniden koyulaşıyor.\n\nUzakta, ufka yakın bir yerde, tek bir geminin ışığı görünüyor. Yavaş yavaş ilerliyor. Fenerin ışığı onun da yolunu aydınlatıyor. Kimse acele etmiyor; gemi de, deniz de, sen de.\n\nTermostan ılık bir yudum alıyorsun. Göğsün sakin, omuzların aşağıda. Paltonun cebinde yuvarlak, pürüzsüz bir taş var; parmakların onu buluyor.\n\nTaşı avucunun içinde çeviriyorsun. Serin ve pürüzsüz. Yıllarca dalgaların arasında kalmış, kenarları yumuşamış. Onu tutarken ellerin de yumuşuyor.\n\nNefesin lambanın dönüşüne uyuyor. Işık denize uzanırken nefes alıyorsun… ışık karanlığa karışırken yavaşça veriyorsun. Bir kez daha. Işık gidiyor, nefes gidiyor.\n\nFener işini biliyor. Sen hiçbir şey yapmasan da ışık dönmeye devam edecek. Gece kendi yolunda ilerliyor. Sen sadece burada oturuyorsun… ve bu yeterli.\n\nGözlerin ağırlaşıyor. Camın ardındaki deniz, dönen ışık ve ılık oda yavaş yavaş birbirine karışıyor. Sandalye seni taşıyor, fener geceyi taşıyor.\n\nSabah olunca güneş denizin üstünden doğacak ve lamba kendiliğinden sönecek. O zamana kadar yapman gereken hiçbir şey yok. Işık dönüyor… deniz sakin… sen dinleniyorsun.",
    en: "It is a calm night. At the tip of a rocky headland stands a white lighthouse, and tonight you are its keeper. The wind has dropped, and the sea is almost perfectly still.\n\nYou see the lighthouse up close for the first time. Its white walls glow faintly in the dark, and an old iron ring hangs above the door. You push the door open; the hinges creak softly, and the cool smell of stone drifts out.\n\nYou climb the stone stairs slowly. One hand rests on the cool wall, and there is a faint smell of salt in the air. With every step, you move a little more slowly.\n\nThe stairs wind round and round. Every so often a narrow window appears, and each one shows you a different piece of the sea. You pause for a moment, listen to your breath, and then carry on slowly.\n\nAt the top, in the lamp room, the windows are clean and clear. You sit down in the old chair by the glass. Below, the cove is empty, and a few boats rock gently.\n\nYou take off your coat and hang it over the back of the chair. You rest your feet on a small stool. The only sound in the room is the low hum of the lamp; steady, familiar, reassuring.\n\nThe lamp turns, slow and steady. Its beam passes over the water, brushes the shore, and fades back into the dark. Every turn keeps the same quiet rhythm.\n\nYou follow the beam with your eyes. First it touches the rocks on the right, then reaches out across the open sea, then slowly comes back. Each time it passes, the water shines like silver for a moment, then darkens again.\n\nFar away, close to the horizon, the light of a single ship appears. It moves slowly. The lighthouse beam lights its way too. No one is hurrying; not the ship, not the sea, not you.\n\nYou take a warm sip from a flask. Your chest is calm, your shoulders low. In your coat pocket there is a smooth, round stone, and your fingers find it.\n\nYou turn the stone over in your palm. It is cool and smooth. Years among the waves have softened its edges. As you hold it, your hands soften too.\n\nYour breath falls into step with the turning lamp. As the light reaches out over the sea, you breathe in… as it fades into the dark, you breathe out slowly. Once more. The light goes, the breath goes.\n\nThe lighthouse knows its work. Even if you do nothing at all, the light will keep turning. The night moves along on its own. You simply sit here… and that is enough.\n\nYour eyes grow heavy. The sea behind the glass, the turning light and the warm room slowly blend into one. The chair is holding you, and the lighthouse is holding the night.\n\nIn the morning the sun will rise over the sea and the lamp will switch itself off. Until then there is nothing you need to do. The light turns… the sea is calm… you are resting.",
    az: "Sakit bir gecədir. Qayalı burnun ucunda ağ bir mayak dayanıb və bu gecə onun gözətçisi sənsən. Külək kəsilib, dəniz demək olar ki, tərpənmir.\n\nMayakı ilk dəfə yaxından görürsən. Ağ divarları gecə qaranlığında yüngülcə parıldayır, qapısının üstündə köhnə dəmir halqa asılıb. Qapını itələyirsən; rəzələr alçaq səslə cırıldayır və içəridən sərin daş qoxusu gəlir.\n\nDaş pilləkənlə yavaş-yavaş yuxarı qalxırsan. Bir əlin sərin divardadır, havada yüngül duz qoxusu var. Hər pillədə addımların bir az da yavaşlayır.\n\nPilləkən fırlana-fırlana yuxarı qalxır. Arabir dar bir pəncərə görünür və hər pəncərədən dənizin başqa bir parçası görünür. Bir az dayanırsan, nəfəsini dinləyirsən, sonra yenə yavaş-yavaş qalxmağa davam edirsən.\n\nYuxarıda, lampa otağında şüşələr tər-təmizdir. Pəncərənin önündəki köhnə stulda oturursan. Aşağıda körfəz boşdur, bir neçə qayıq yavaşca yırğalanır.\n\nPaltonu çıxarıb stulun söykənəcəyinə asırsan. Ayaqlarını kiçik bir kətilin üstünə uzadırsan. Otaqda yalnız lampanın dərindən gələn yüngül uğultusu var; ahəngdar, tanış, güvən verən bir səs.\n\nLampa ağır-ağır fırlanır. İşıq dənizin üstündən keçir, sahili sığallayır, sonra yenidən qaranlığa qarışır. Hər dövrə eyni sakit ahənglə.\n\nİşığı gözünlə izləyirsən. Əvvəl sağdakı qayalara toxunur, sonra açıq dənizə uzanır, sonra yavaşca geri qayıdır. Hər keçəndə dəniz bir anlıq gümüş kimi parlayır, sonra yenə tündləşir.\n\nUzaqda, üfüqə yaxın bir yerdə tək bir gəminin işığı görünür. Yavaş-yavaş irəliləyir. Mayakın işığı onun da yolunu işıqlandırır. Heç kim tələsmir; nə gəmi, nə dəniz, nə də sən.\n\nTermosdan ilıq bir qurtum içirsən. Sinən sakitdir, çiyinlərin aşağıdadır. Paltonun cibində yumru, hamar bir daş var; barmaqların onu tapır.\n\nDaşı ovucunda çevirirsən. Sərin və hamardır. İllərlə dalğaların arasında qalıb, kənarları yumşalıb. Onu tutduqca əllərin də yumşalır.\n\nNəfəsin lampanın fırlanmasına uyğunlaşır. İşıq dənizə uzananda nəfəs alırsan… işıq qaranlığa qarışanda yavaşca verirsən. Bir dəfə də. İşıq gedir, nəfəs gedir.\n\nMayak öz işini bilir. Sən heç nə etməsən də, işıq fırlanmağa davam edəcək. Gecə öz yolu ilə irəliləyir. Sən sadəcə burada oturursan… və bu kifayətdir.\n\nGözlərin ağırlaşır. Şüşənin arxasındakı dəniz, fırlanan işıq və ilıq otaq yavaş-yavaş bir-birinə qarışır. Stul səni saxlayır, mayak isə gecəni saxlayır.\n\nSəhər olanda günəş dənizin üstündən doğacaq və lampa özü sönəcək. O vaxta qədər etməli olduğun heç nə yoxdur. İşıq fırlanır… dəniz sakitdir… sən dincəlirsən.",
    ru: "Тихая ночь. На краю скалистого мыса стоит белый маяк, и этой ночью его смотритель — ты. Ветер стих, море почти не шевелится.\n\nТы видишь маяк вблизи. Его белые стены слабо светятся в темноте, над дверью висит старое железное кольцо. Ты толкаешь дверь; петли тихо поскрипывают, и изнутри веет прохладой камня.\n\nТы медленно поднимаешься по каменной лестнице. Одна рука лежит на прохладной стене, в воздухе лёгкий запах соли. С каждой ступенькой шаги становятся чуть медленнее.\n\nЛестница поднимается по кругу, виток за витком. Время от времени появляется узкое окно, и в каждом видна другая часть моря. Ты ненадолго останавливаешься, прислушиваешься к дыханию и снова медленно идёшь вверх.\n\nНаверху, в комнате с лампой, стёкла чистые и прозрачные. Ты садишься на старый стул у окна. Внизу бухта пуста, несколько лодок тихо покачиваются.\n\nТы снимаешь пальто и вешаешь его на спинку стула. Ноги можно положить на маленькую скамеечку. В комнате слышно только низкое гудение лампы — ровное, знакомое, успокаивающее.\n\nЛампа поворачивается медленно и ровно. Луч проходит над водой, касается берега и снова растворяется в темноте. Каждый круг — в одном и том же спокойном ритме.\n\nТы провожаешь луч взглядом. Сначала он касается скал справа, потом уходит в открытое море, потом медленно возвращается. Каждый раз вода на мгновение вспыхивает серебром и снова темнеет.\n\nДалеко, почти у горизонта, виден огонёк одного корабля. Он движется медленно. Свет маяка освещает и его путь. Никто не спешит — ни корабль, ни море, ни ты.\n\nТы делаешь тёплый глоток из термоса. Грудь спокойна, плечи опущены. В кармане пальто лежит гладкий круглый камешек, и пальцы находят его.\n\nТы переворачиваешь камешек в ладони. Он прохладный и гладкий. Годы среди волн смягчили его края. Пока ты держишь его, руки тоже становятся мягче.\n\nДыхание подстраивается под вращение лампы. Когда луч уходит в море, ты вдыхаешь… когда он растворяется в темноте, медленно выдыхаешь. Ещё раз. Свет уходит, и дыхание уходит.\n\nМаяк знает своё дело. Даже если ты ничего не будешь делать, свет продолжит вращаться. Ночь идёт своим путём. Ты просто сидишь здесь… и этого достаточно.\n\nВеки тяжелеют. Море за стеклом, вращающийся свет и тёплая комната понемногу сливаются в одно. Стул держит тебя, а маяк держит ночь.\n\nУтром солнце поднимется над морем, и лампа погаснет сама. До тех пор ничего делать не нужно. Свет вращается… море спокойно… ты отдыхаешь.",
  },
  "meadow.body": {
    tr: "Yüksek bir yayladasın. Gece serin ama rüzgâr yok. Kalın bir battaniyenin üstüne sırtüstü uzanmışsın.\n\nBuraya gün batarken geldin. Patika otların arasından kıvrılarak çıkıyordu ve yayla tam tepede düz bir yer gibi açılıyordu. Battaniyeyi yere serdin, ayakkabılarını çıkarıp kenara koydun.\n\nAy henüz doğmamış, gökyüzü yıldızlarla dolu. Onları saymana gerek yok. Sadece bak.\n\nBir süre sonra gözlerin karanlığa alışıyor ve daha fazla yıldız beliriyor. Bazıları parlak ve net, bazıları o kadar soluk ki sadece göz ucuyla görebiliyorsun. Samanyolu gökyüzünün ortasından ince bir sis gibi geçiyor.\n\nBir yıldız kayıyor; kısa, sessiz bir çizgi. Bir dilek tutmana gerek yok. Sadece fark et ve bırak.\n\nUzaklardan bir derenin sesi geliyor; ince, sürekli ve sakin. Çimenlerin serin kokusu havaya karışmış.\n\nBir yerde bir cırcır böceği ötmeye başlıyor, sonra bir başkası ona katılıyor. Sesleri yumuşak ve düzenli. Gece, kendi küçük şarkısını söylüyor.\n\nHafif bir serinlik geliyor. Battaniyenin kenarını üzerine çekiyorsun. Yün kalın ve sıcak; bedenin içinde güvenli bir yer buluyor.\n\nEllerin iki yanında, battaniyenin kenarında dinleniyor. Altındaki toprak sağlam ve seni bütünüyle taşıyor.\n\nSırtının bütün uzunluğunu hisset. Başının arkası, kürek kemiklerin, belin, kalçaların… hepsi yere değiyor. Toprak bütün gün güneşte ısınmış; o sıcaklığı yavaşça sana veriyor.\n\nŞimdi yıldızlardan birini seç. Ona bir isim vermene gerek yok. Sadece onu izle. Ne kadar uzakta, ne kadar sakin parlıyor.\n\nYıldıza bakarken nefesin yavaşlıyor. Nefes alıyorsun… gökyüzü genişliyor. Nefes veriyorsun… beden yere biraz daha yerleşiyor. Bir kez daha, kendi hızında.\n\nUzaklarda bir köpek havlıyor, sonra susuyor. Bir köyün son ışığı da sönüyor. Şimdi yalnızca yıldızlar, dere ve sen varsınız.\n\nGökyüzü geniş, toprak sağlam, dere akmaya devam ediyor. Her nefesinle biraz daha ağırlaşıyor, yere biraz daha yerleşiyorsun.\n\nGözlerin kapanmak isterse kapanmalarına izin ver. Yıldızlar yine orada olacak. Dere akmaya devam edecek. Toprak seni sabaha kadar taşıyacak.",
    en: "You are in a high mountain meadow. The night is cool, but there is no wind. You are lying on your back on a thick blanket.\n\nYou came up here at sunset. The path wound through the grass, and at the very top the high meadow opened out like a wide, flat floor. You spread the blanket on the ground, took off your shoes and set them to one side.\n\nThe moon has not risen yet, and the sky is full of stars. You do not need to count them. Just look.\n\nAfter a while your eyes get used to the dark, and more stars appear. Some are bright and clear; others are so faint you can only see them from the corner of your eye. The Milky Way crosses the middle of the sky like a thin mist.\n\nA star falls; a short, silent line. You do not need to make a wish. Just notice it, and let it go.\n\nFrom far away comes the sound of a stream, thin, steady, and calm. The cool scent of grass hangs in the air.\n\nSomewhere a cricket begins to sing, and then another joins in. Their sound is soft and steady. The night is singing its own small song.\n\nA slight chill comes. You pull the edge of the blanket over you. The wool is thick and warm, and your body finds a safe place inside it.\n\nYour hands rest at your sides, at the edge of the blanket. The ground beneath you is solid and holds all of you.\n\nFeel the whole length of your back. The back of your head, your shoulder blades, your lower back, your hips… all of them touching the ground. The earth has been warmed by the sun all day, and it slowly gives that warmth to you.\n\nNow choose one star. You do not need to name it. Just watch it, so far away, shining so calmly.\n\nAs you watch the star, your breath slows down. You breathe in… and the sky grows wider. You breathe out… and your body settles a little deeper into the ground. Once more, at your own pace.\n\nFar away a dog barks, then falls silent. The last light in a village goes out. Now there are only the stars, the stream, and you.\n\nThe sky is wide, the earth is steady, and the stream keeps flowing. With every breath you grow a little heavier and settle a little deeper into the ground.\n\nIf your eyes want to close, let them. The stars will still be there. The stream will keep flowing. The earth will hold you until morning.",
    az: "Yüksək bir yayladasan. Gecə sərindir, amma külək yoxdur. Qalın bir yorğanın üstündə arxası üstə uzanmısan.\n\nBura gün batanda gəldin. Cığır otların arasından qıvrılaraq qalxırdı və ən yuxarıda yayla geniş, düz bir meydan kimi açılırdı. Yorğanı yerə sərdin, ayaqqabılarını çıxarıb kənara qoydun.\n\nAy hələ çıxmayıb, səma ulduzlarla doludur. Onları saymağa ehtiyac yoxdur. Sadəcə bax.\n\nBir az sonra gözlərin qaranlığa öyrəşir və daha çox ulduz görünür. Bəziləri parlaq və aydındır, bəziləri isə elə solğundur ki, onları yalnız göz ucu ilə görə bilirsən. Süd yolu səmanın ortasından incə bir duman kimi keçir.\n\nBir ulduz axır; qısa, səssiz bir xətt. Arzu tutmağa ehtiyac yoxdur. Sadəcə fərqinə var və burax.\n\nUzaqdan bir çayın səsi gəlir; incə, fasiləsiz və sakit. Otların sərin qoxusu havaya qarışıb.\n\nHaradasa bir cırcırama oxumağa başlayır, sonra başqası da ona qoşulur. Səsləri yumşaq və ahəngdardır. Gecə öz kiçik mahnısını oxuyur.\n\nYüngül bir sərinlik gəlir. Yorğanın kənarını üstünə çəkirsən. Yun qalın və istidir; bədənin onun içində təhlükəsiz bir yer tapır.\n\nƏllərin yanlarında, yorğanın kənarında dincəlir. Altındakı torpaq möhkəmdir və səni bütünlüklə saxlayır.\n\nKürəyinin bütün uzunluğunu hiss et. Başının arxası, kürək sümüklərin, belin, ombaların… hamısı yerə toxunur. Torpaq bütün günü günəşdə qızıb; o istiliyi yavaş-yavaş sənə verir.\n\nİndi ulduzlardan birini seç. Ona ad verməyə ehtiyac yoxdur. Sadəcə ona bax. Nə qədər uzaqdadır, nə qədər sakit işıldayır.\n\nUlduza baxdıqca nəfəsin yavaşlayır. Nəfəs alırsan… səma genişlənir. Nəfəs verirsən… bədən yerə bir az da yerləşir. Bir dəfə də, öz sürətinlə.\n\nUzaqda bir it hürür, sonra susur. Kəndin son işığı da sönür. İndi yalnız ulduzlar, çay və sən varsınız.\n\nSəma genişdir, torpaq möhkəmdir, çay axmağa davam edir. Hər nəfəslə bir az da ağırlaşır, yerə bir az da yerləşirsən.\n\nGözlərin yumulmaq istəsə, qoy yumulsun. Ulduzlar yenə orada olacaq. Çay axmağa davam edəcək. Torpaq səni səhərə qədər saxlayacaq.",
    ru: "Ты на высоком горном лугу. Ночь прохладная, но ветра нет. Ты лежишь на спине на толстом пледе.\n\nСюда ведёт тропинка, которая вьётся среди травы, а на самом верху луг раскрывается широкой ровной поляной. Плед расстелен на земле, обувь стоит рядом.\n\nЛуна ещё не взошла, и небо полно звёзд. Считать их не нужно. Просто смотри.\n\nГлаза привыкают к темноте, и звёзд становится больше. Одни яркие и чёткие, другие такие бледные, что их видно только краем глаза. Млечный Путь тянется через середину неба, как тонкая дымка.\n\nПадает звезда — короткая беззвучная черта. Загадывать желание не нужно. Просто заметь её и отпусти.\n\nИздалека доносится шум ручья — тонкий, ровный и спокойный. В воздухе прохладный запах травы.\n\nГде-то начинает стрекотать сверчок, потом к нему присоединяется другой. Их голоса мягкие и ровные. Ночь поёт свою маленькую песню.\n\nПриходит лёгкая прохлада. Ты натягиваешь на себя край пледа. Шерсть толстая и тёплая, и тело находит в ней надёжное место.\n\nРуки лежат вдоль тела, на краю пледа. Земля под тобой твёрдая и держит тебя целиком.\n\nПочувствуй всю длину спины. Затылок, лопатки, поясница, таз… всё касается земли. Земля весь день грелась на солнце и теперь медленно отдаёт тебе это тепло.\n\nТеперь выбери одну звезду. Давать ей имя не нужно. Просто смотри на неё. Как далеко она и как спокойно светит.\n\nПока ты смотришь на звезду, дыхание замедляется. Вдох… и небо становится шире. Выдох… и тело чуть глубже ложится на землю. Ещё раз, в своём темпе.\n\nДалеко лает собака, потом замолкает. Гаснет последний огонёк в деревне. Теперь есть только звёзды, ручей и ты.\n\nНебо широкое, земля надёжная, ручей продолжает течь. С каждым вдохом ты становишься чуть тяжелее и глубже опускаешься на землю.\n\nЕсли глаза хотят закрыться, позволь им. Звёзды никуда не денутся. Ручей будет течь дальше. Земля будет держать тебя до самого утра.",
  },
  "night-seed-note.body": {
    tr: "Gün bitmek üzere. Işıkları biraz kıs, ekranları bir kenara bırak. Yatağın kenarına ya da sakin bir köşeye otur. Yanında küçük bir kâğıt ve kalem olsun.\n\nBir nefes al ve yavaşça ver. Bugünün bütün sesleri yavaş yavaş geride kalıyor. Şimdi geceye götüreceğin tek bir görüntü seçeceğiz.\n\nYatmadan önce küçük bir kâğıda tek bir cümle yaz. Bu cümle sakin bir sahneyi anlatsın.\n\nSakin bir sahne düşün. Gerçek bir yer olabilir; çocukluğundan bir bahçe, bir tatil sabahı, büyükannenin mutfağı. Ya da hiç görmediğin, hayal ettiğin bir yer olabilir.\n\nGözlerini kapat ve o sahneye bak. Orada ne renkler var? Işık nereden geliyor? Hava nasıl? Bir ses var mı?\n\nÖrneğin: “Kapalı bir bahçe, güneşte ısınmış bir taş, yanan bir lamba.”\n\nSenin cümlen de böyle sade olabilir. Üç ya da dört küçük görüntü yeter. Fiillere, açıklamalara gerek yok.\n\nUzun bir hikâye değil; bir kartpostal gibi tek bir kare.\n\nYazarken yavaşla. Her kelimeyi yazdığında o görüntüyü zihninde biraz daha net gör. Taşın sıcaklığını, lambanın ışığını, bahçenin sessizliğini.\n\nKâğıdı katla, telefonunu ters çevir ve ışığı kapat.\n\nKâğıdı yastığının altına ya da başucuna koyabilirsin. Orada olduğunu bilmek yeterli.\n\nYatağa uzan. Bedenini yerleştir. Omuzlarını bırak, çeneni gevşet, ellerini yanına koy. Bir nefes al… ve uzun uzun ver.\n\nGözlerini kapattığında o sahneyi hatırla. Onu tekrar tekrar düşünmene gerek yok. Bir kez hatırla ve bırak; gerisini gece halleder.\n\nZihnin başka bir yere giderse, kızmadan o sahneye geri dön. Bir taş, bir lamba, bir bahçe. Sahne seni bekliyor.\n\nUyku gelmezse de sorun değil. Sahnenin içinde dinlenmek de bedenine iyi gelir. Nefesin yavaş, odan karanlık, sahnen sakin.",
    en: "The day is nearly over. Dim the lights a little and put your screens to one side. Sit on the edge of the bed or in a quiet corner. Have a small piece of paper and a pen with you.\n\nTake a breath and let it out slowly. All of today's noise is slowly falling behind you. Now we will choose a single image to take into the night.\n\nBefore bed, write one sentence on a small piece of paper. Let it describe a calm scene.\n\nThink of a calm scene. It could be a real place; a garden from your childhood, a holiday morning, your grandmother's kitchen. Or a place you have never seen, only imagined.\n\nClose your eyes and look at that scene. What colours are there? Where is the light coming from? What is the air like? Is there a sound?\n\nFor example: “A walled garden, a stone warm from the sun, a glowing lamp.”\n\nYour sentence can be just as simple. Three or four small images are enough. No need for verbs or explanations.\n\nNot a long story; a single frame, like a postcard.\n\nSlow down as you write. With each word, see that image a little more clearly in your mind. The warmth of the stone, the light of the lamp, the quiet of the garden.\n\nFold the paper, turn your phone face down, and switch off the light.\n\nYou can put the paper under your pillow or by your bed. Knowing it is there is enough.\n\nLie down. Settle your body. Let your shoulders go, loosen your jaw, rest your hands by your sides. Take a breath… and let it out long and slow.\n\nWhen you close your eyes, recall that scene. You do not need to go over it again and again. Recall it once and let it go; the night will do the rest.\n\nIf your mind wanders somewhere else, return to the scene without getting cross with yourself. A stone, a lamp, a garden. The scene is waiting for you.\n\nIf sleep does not come, that is fine too. Resting inside the scene is good for your body as well. Your breath is slow, your room is dark, your scene is calm.",
    az: "Gün bitmək üzrədir. İşıqları bir az azalt, ekranları bir kənara qoy. Çarpayının kənarında və ya sakit bir küncdə otur. Yanında kiçik bir kağız və qələm olsun.\n\nBir nəfəs al və yavaşca ver. Bugünün bütün səsləri yavaş-yavaş geridə qalır. İndi gecəyə aparacağın tək bir görüntü seçəcəyik.\n\nYatmazdan əvvəl kiçik bir kağıza tək bir cümlə yaz. Bu cümlə sakit bir səhnəni təsvir etsin.\n\nSakit bir səhnə düşün. Həqiqi bir yer ola bilər; uşaqlığından bir bağ, bir tətil səhəri, nənənin mətbəxi. Ya da heç görmədiyin, xəyal etdiyin bir yer ola bilər.\n\nGözlərini yum və o səhnəyə bax. Orada hansı rənglər var? İşıq haradan gəlir? Hava necədir? Bir səs varmı?\n\nMəsələn: “Bağlı bir bağ, günəşdə qızmış bir daş, yanan bir lampa.”\n\nSənin cümlən də belə sadə ola bilər. Üç-dörd kiçik görüntü kifayətdir. Fellərə, izahlara ehtiyac yoxdur.\n\nUzun bir hekayə yox; açıqca kimi tək bir kadr.\n\nYazanda yavaşla. Hər sözü yazanda o görüntünü ağlında bir az da aydın gör. Daşın istiliyini, lampanın işığını, bağın sükutunu.\n\nKağızı qatla, telefonunu üzüaşağı çevir və işığı söndür.\n\nKağızı yastığının altına və ya baş tərəfinə qoya bilərsən. Orada olduğunu bilmək kifayətdir.\n\nÇarpayıya uzan. Bədənini yerləşdir. Çiyinlərini burax, çənəni boşalt, əllərini yanına qoy. Bir nəfəs al… və uzun-uzun ver.\n\nGözlərini yumanda o səhnəni xatırla. Onu təkrar-təkrar düşünməyə ehtiyac yoxdur. Bir dəfə xatırla və burax; qalanını gecə özü həll edəcək.\n\nAğlın başqa yerə getsə, özünü danlamadan o səhnəyə qayıt. Bir daş, bir lampa, bir bağ. Səhnə səni gözləyir.\n\nYuxu gəlməsə də, problem deyil. Səhnənin içində dincəlmək də bədəninə xeyirdir. Nəfəsin yavaş, otağın qaranlıq, səhnən sakitdir.",
    ru: "День почти закончился. Приглуши свет, отложи экраны. Сядь на край кровати или в тихий угол. Пусть рядом будут маленький листок и ручка.\n\nСделай вдох и медленный выдох. Весь шум сегодняшнего дня понемногу остаётся позади. Сейчас мы выберем один образ, который возьмём с собой в ночь.\n\nПеред сном напиши на маленьком листке одно предложение. Пусть оно описывает спокойную сцену.\n\nПодумай о спокойной сцене. Это может быть настоящее место: сад из детства, утро в отпуске, бабушкина кухня. Или место, которое существует только в воображении.\n\nЗакрой глаза и посмотри на эту сцену. Какие там цвета? Откуда падает свет? Какой там воздух? Есть ли звук?\n\nНапример: «Закрытый сад, нагретый солнцем камень, горящая лампа».\n\nТвоё предложение может быть таким же простым. Трёх-четырёх маленьких образов достаточно. Глаголы и объяснения не нужны.\n\nНе длинная история, а один кадр, как открытка.\n\nПока пишешь, замедлись. С каждым словом пусть этот образ становится чуть яснее. Тепло камня, свет лампы, тишина сада.\n\nСложи листок, переверни телефон экраном вниз и выключи свет.\n\nЛисток можно положить под подушку или у изголовья. Достаточно знать, что он там.\n\nЛожись. Устрой тело удобно. Отпусти плечи, расслабь челюсть, положи руки вдоль тела. Вдох… и долгий медленный выдох.\n\nКогда закроешь глаза, вспомни эту сцену. Не нужно прокручивать её снова и снова. Вспомни один раз и отпусти; остальное сделает ночь.\n\nЕсли ум уходит куда-то ещё, без упрёков возвращайся к сцене. Камень, лампа, сад. Сцена ждёт тебя.\n\nЕсли сон не приходит, это тоже нормально. Отдыхать внутри этой сцены тоже полезно для тела. Дыхание медленное, в комнате темно, сцена спокойна.",
  },
  "olive-gate.body": {
    tr: "Akşamüstü, yumuşak bir tepenin üzerindesin. Etrafında yaşlı zeytin ağaçları var; yaprakları rüzgârda gümüş gibi parlıyor.\n\nTepeye taşlı bir patikadan çıktın. Yol boyunca kekik ve adaçayı kokusu sana eşlik etti. Ağustosböcekleri günün son şarkılarını söylüyor; sesleri yavaş yavaş azalıyor.\n\nTepede eski taş sütunlar duruyor. İki sütunun arası açık, bir kapı gibi.\n\nSütunların taşı zamanla aşınmış, köşeleri yuvarlaklaşmış. Bir zamanlar burada bir tapınak ya da bir kapı vardı belki. Şimdi geriye sadece bu iki sütun ve aradaki boşluk kaldı.\n\nKapının ardından aşağıdaki vadi görünüyor. Bağlar, küçük bir köy, uzakta mavi bir deniz şeridi. Her şey akşam ışığında yumuşamış.\n\nSütunlardan birinin dibine oturuyorsun. Sırtını güneşte ısınmış taşa yaslıyorsun.\n\nTaşın sıcaklığı sırtından yavaşça içine yayılıyor. Avuçlarını yanındaki kuru toprağa koyuyorsun. Toprak da ılık, güneşin bütün gün bıraktığı sıcaklığı tutuyor.\n\nNefes al… kekik ve zeytin yaprağı kokusu. Nefes ver… omuzların taşın üstünde biraz daha iniyor. Bir kez daha, yavaşça.\n\nAkşam ışığı her şeyi altın rengine boyuyor. Havada ince bir toz ve kuru otların kokusu var.\n\nGüneş denizin üstüne doğru iniyor. Gökyüzü önce altın, sonra turuncu, sonra pembe oluyor. Zeytin yapraklarının gümüşü yavaşça koyulaşıyor.\n\nUzakta bir çan sesi duyuluyor. Bir sürü eve dönüyor. Çobanın ıslığı tepeden tepeye yankılanıyor, sonra sessizlik geri geliyor.\n\nKapıdan geçmek için acele etmene gerek yok. Burada, taşın sıcaklığında oturabilirsin.\n\nKapı orada, açık duruyor. Ne zaman istersen geçebilirsin. Ya da hiç geçmeyebilirsin. İki seçenek de iyi. Bu akşam karar vermen gerekmiyor.\n\nZeytin ağaçları yüzlerce yıldır burada. Kaç akşam, kaç gece gördüler… sabırla ve sessizce. Sen de şimdi onlar gibi sadece buradasın.\n\nHava serinlemeye başlıyor. İlk yıldız, iki sütunun tam arasında beliriyor. Taş hâlâ sıcak, toprak hâlâ ılık. Gözlerini kapatıyorsun ve zeytin ağaçlarının hışırtısını dinliyorsun.\n\nGece tepeye yavaşça iniyor ve seni de yumuşakça sarıyor. Burada güvendesin, burada dinlenebilirsin.",
    en: "It is late afternoon, and you are on a gentle hill. Old olive trees surround you, their leaves shining like silver in the breeze.\n\nYou climbed the hill along a stony path. The scent of thyme and sage kept you company all the way. The cicadas are singing the last songs of the day, and their sound is slowly fading.\n\nOn the hilltop stand ancient stone columns. The space between two of them is open, like a gate.\n\nThe stone of the columns has worn with time, its corners rounded. Perhaps there was once a temple here, or a gate. Now only these two columns are left, and the space between them.\n\nThrough the gate you can see the valley below. Vineyards, a small village, and far away a blue strip of sea. Everything is softened by the evening light.\n\nYou sit down at the foot of one column and lean your back against the stone, warm from the sun.\n\nThe warmth of the stone slowly spreads from your back into your body. You rest your palms on the dry earth beside you. The earth is warm too, holding the heat the sun has left all day.\n\nBreathe in… the scent of thyme and olive leaves. Breathe out… your shoulders sink a little further against the stone. Once more, slowly.\n\nThe evening light turns everything gold. The air carries fine dust and the scent of dry grass.\n\nThe sun is going down over the sea. The sky turns gold, then orange, then pink. The silver of the olive leaves slowly deepens.\n\nIn the distance you hear a bell. A flock is heading home. The shepherd's whistle echoes from hill to hill, and then the quiet returns.\n\nThere is no need to hurry through the gate. You can sit here, in the warmth of the stone.\n\nThe gate is there, standing open. You can walk through whenever you like. Or you may never walk through it at all. Both are fine. You do not need to decide this evening.\n\nThe olive trees have stood here for hundreds of years. How many evenings, how many nights they have seen… patiently, quietly. And now, like them, you are simply here.\n\nThe air begins to cool. The first star appears exactly between the two columns. The stone is still warm, the earth still mild. You close your eyes and listen to the rustle of the olive trees.\n\nThe night comes down slowly over the hill and wraps around you gently too. Here you are safe, here you can rest.",
    az: "Axşamüstüdür, yumşaq bir təpənin üstündəsən. Ətrafında qoca zeytun ağacları var; yarpaqları küləkdə gümüş kimi parıldayır.\n\nTəpəyə daşlı bir cığırla qalxdın. Yol boyu kəklikotu və adaçayı qoxusu sənə yoldaşlıq etdi. Cırcıramalar günün son mahnılarını oxuyur; səsləri yavaş-yavaş azalır.\n\nTəpədə köhnə daş sütunlar dayanıb. İki sütunun arası açıqdır, qapı kimi.\n\nSütunların daşı zamanla aşınıb, kənarları yumrulaşıb. Bəlkə nə vaxtsa burada bir məbəd və ya darvaza olub. İndi yalnız bu iki sütun və aradakı boşluq qalıb.\n\nQapının o tayında aşağıdakı dərə görünür. Üzüm bağları, kiçik bir kənd, uzaqda isə mavi bir dəniz zolağı. Hər şey axşam işığında yumşalıb.\n\nSütunlardan birinin dibində oturursan. Kürəyini günəşdə qızmış daşa söykəyirsən.\n\nDaşın istiliyi kürəyindən yavaş-yavaş içinə yayılır. Ovuclarını yanındakı quru torpağa qoyursan. Torpaq da ilıqdır, günəşin bütün gün buraxdığı istiliyi saxlayır.\n\nNəfəs al… kəklikotu və zeytun yarpağı qoxusu. Nəfəs ver… çiyinlərin daşın üstündə bir az da enir. Bir dəfə də, yavaşca.\n\nAxşam işığı hər şeyi qızılı rəngə boyayır. Havada incə toz və quru ot qoxusu var.\n\nGünəş dənizin üstünə doğru enir. Səma əvvəl qızılı, sonra narıncı, sonra çəhrayı olur. Zeytun yarpaqlarının gümüşü yavaş-yavaş tündləşir.\n\nUzaqdan bir zəng səsi gəlir. Bir sürü evə qayıdır. Çobanın fiti təpədən təpəyə əks-səda verir, sonra sükut geri qayıdır.\n\nQapıdan keçmək üçün tələsməyə ehtiyac yoxdur. Burada, daşın istiliyində otura bilərsən.\n\nQapı oradadır, açıq dayanıb. Nə vaxt istəsən, keçə bilərsən. Ya da heç keçməyə bilərsən. İkisi də yaxşıdır. Bu axşam qərar verməyə ehtiyac yoxdur.\n\nZeytun ağacları yüz illərdir buradadır. Neçə axşam, neçə gecə görüblər… səbirlə və sakitcə. İndi sən də onlar kimi sadəcə buradasan.\n\nHava sərinləməyə başlayır. İlk ulduz düz iki sütunun arasında görünür. Daş hələ də istidir, torpaq hələ də ilıqdır. Gözlərini yumursan və zeytun ağaclarının xışıltısını dinləyirsən.\n\nGecə təpəyə yavaş-yavaş enir və səni də yumşaqca bürüyür. Burada təhlükəsizsən, burada dincələ bilərsən.",
    ru: "Ранний вечер. Ты на пологом холме. Вокруг растут старые оливы; их листья серебрятся на ветру.\n\nНа холм ведёт каменистая тропа. Всю дорогу рядом запах тимьяна и шалфея. Цикады поют последние песни дня, и их голоса понемногу стихают.\n\nНа вершине стоят древние каменные колонны. Пространство между двумя из них открыто, как ворота.\n\nКамень колонн стёрся от времени, углы округлились. Может быть, когда-то здесь был храм или ворота. Теперь остались только эти две колонны и пространство между ними.\n\nЗа воротами видна долина внизу. Виноградники, маленькая деревня, а вдали синяя полоска моря. Всё смягчено вечерним светом.\n\nТы садишься у подножия одной колонны и прислоняешься спиной к камню, нагретому солнцем.\n\nТепло камня медленно переходит от спины внутрь. Ладони лежат на сухой земле рядом. Земля тоже тёплая, она хранит жар, оставленный солнцем за день.\n\nВдох… запах тимьяна и оливковых листьев. Выдох… плечи чуть глубже опускаются к камню. Ещё раз, медленно.\n\nВечерний свет окрашивает всё в золотой цвет. В воздухе мелкая пыль и запах сухой травы.\n\nСолнце опускается к морю. Небо становится золотым, потом оранжевым, потом розовым. Серебро оливковых листьев медленно темнеет.\n\nВдали слышен колокольчик. Стадо возвращается домой. Свист пастуха откликается эхом от холма к холму, и снова наступает тишина.\n\nНе нужно спешить пройти через ворота. Можно посидеть здесь, в тепле камня.\n\nВорота здесь, они открыты. Через них можно пройти когда угодно. А можно и не проходить вовсе. И то и другое хорошо. Решать этим вечером не нужно.\n\nОливы стоят здесь сотни лет. Сколько вечеров и ночей они видели… терпеливо и тихо. И сейчас ты, как они, просто здесь.\n\nВоздух начинает остывать. Первая звезда появляется точно между двумя колоннами. Камень всё ещё тёплый, земля всё ещё мягкая. Ты закрываешь глаза и слушаешь шелест олив.\n\nНочь медленно опускается на холм и бережно окутывает и тебя. Здесь безопасно, здесь можно отдохнуть.",
  },
  "paper-boat.body": {
    tr: "Küçük bir göletin kıyısında oturuyorsun. Akşam olmuş, hava ılık. Su neredeyse hiç kıpırdamıyor.\n\nGöletin kenarında sazlar hafifçe sallanıyor. Suyun üstünde birkaç nilüfer yaprağı yüzüyor. Gökyüzü yavaş yavaş turuncudan pembeye, pembeden mora dönüyor.\n\nElinde kâğıttan küçük bir tekne var. Onu yavaşça suya bırakıyorsun.\n\nTekneyi kendi ellerinle katlamıştın. Kâğıdın kenarlarını düzeltmiş, köşelerini dikkatle bastırmıştın. Şimdi küçük ve hafif, suyun üstünde dimdik duruyor.\n\nİstersen içine bir şey koyabilirsin; seni bugün yoran bir düşünce, aklında dönüp duran bir cümle. Onu tekneye yerleştirdiğini hayal et. Teknenin taşıyamayacağı kadar ağır değil.\n\nTekne kıyıdan usulca uzaklaşıyor. Acelesi yok, bir yere yetişmeye çalışmıyor. Hafif bir esinti onu kendi hızında götürüyor.\n\nTekne bir nilüfer yaprağının yanından geçiyor, hafifçe ona değiyor, sonra yoluna devam ediyor. Bir kurbağa sessizce suya atlıyor; küçük halkalar yayılıyor ve yavaşça kayboluyor.\n\nSen toprağın üzerinde oturuyorsun; altındaki yer ılık ve sağlam. Tekneyi yönetmene gerek yok. Sadece izle.\n\nNefesini izle. Tekne uzaklaşırken nefesini ver. Biraz daha uzaklaşırken bir kez daha ver. Her verişte omuzların biraz daha iniyor, ellerin biraz daha gevşiyor.\n\nSu akşam ışığını yumuşakça yansıtıyor. Tekne yavaşça dönüyor, sonra yine süzülüyor.\n\nTekne şimdi göletin ortasında. Küçük bir beyaz nokta gibi. Gözlerini ondan ayırmadan derin bir nefes alıyorsun ve uzun uzun veriyorsun.\n\nHava kararıyor. İlk yıldızlar göletin yüzeyine yansıyor. Tekne yıldızların arasında süzülüyor gibi. Artık neredeyse görünmüyor.\n\nBazı şeyleri bırakmak böyledir: Suya koyarsın ve kendi yoluna gitmesine izin verirsin.\n\nBir süre daha kıyıda oturuyorsun. Ellerin boş ve hafif. Gölet sakin, gece ılık. Tekne gittiği yere kendi hızında varacak. Senin onu takip etmen gerekmiyor.\n\nKalkıp eve dönerken adımların yumuşak. İçinde bir yer biraz daha ferah. Bu gece bırakabildiğin kadarını bıraktın ve bu yeterli.",
    en: "You are sitting at the edge of a small pond. Evening has come, and the air is mild. The water barely moves.\n\nAt the edge of the pond the reeds sway gently. A few lily pads float on the water. The sky is slowly turning from orange to pink, and from pink to purple.\n\nIn your hand is a small paper boat. You set it gently on the water.\n\nYou folded the boat with your own hands. You smoothed the edges of the paper and pressed the corners carefully. Now it is small and light, sitting upright on the water.\n\nIf you like, you can put something inside it; a thought that has tired you today, a sentence that keeps going round in your head. Imagine placing it in the boat. It is not too heavy for the boat to carry.\n\nThe boat drifts slowly away from the shore. It is in no hurry and has nowhere to be. A light breeze carries it at its own pace.\n\nThe boat passes a lily pad, brushes against it lightly, then carries on its way. A frog slips quietly into the water; small rings spread out and slowly disappear.\n\nYou are sitting on the ground, which is warm and steady beneath you. You do not need to steer the boat. Just watch.\n\nWatch your breath. As the boat drifts away, breathe out. As it drifts a little further, breathe out once more. With each out-breath your shoulders drop a little, and your hands loosen a little more.\n\nThe water softly reflects the evening light. The boat turns slowly, then glides on.\n\nThe boat is now in the middle of the pond, like a small white dot. Without taking your eyes off it, you take a deep breath and let it out long and slow.\n\nIt is getting dark. The first stars are reflected on the surface of the pond. The boat seems to be floating among the stars. Now you can hardly see it.\n\nLetting go of some things is like this: you place them on the water and allow them to find their own way.\n\nYou sit on the bank a little longer. Your hands are empty and light. The pond is calm, the night is warm. The boat will reach wherever it is going at its own pace. You do not need to follow it.\n\nAs you get up and walk home, your steps are soft. A place inside you feels a little more spacious. Tonight you let go of as much as you could, and that is enough.",
    az: "Kiçik bir gölməçənin kənarında oturursan. Axşamdır, hava ilıqdır. Su demək olar ki, tərpənmir.\n\nGölməçənin kənarında qamışlar yüngülcə yırğalanır. Suyun üstündə bir neçə suzanbağı yarpağı üzür. Səma yavaş-yavaş narıncıdan çəhrayıya, çəhrayıdan bənövşəyiyə dönür.\n\nƏlində kağızdan kiçik bir qayıq var. Onu yavaşca suya buraxırsan.\n\nQayığı öz əllərinlə qatlamışdın. Kağızın kənarlarını düzəltmiş, künclərini diqqətlə basmışdın. İndi kiçik və yüngüldür, suyun üstündə dik dayanır.\n\nİstəsən, içinə bir şey qoya bilərsən; bu gün səni yoran bir fikir, ağlında fırlanıb duran bir cümlə. Onu qayığa qoyduğunu təsəvvür et. Qayığın daşıya bilməyəcəyi qədər ağır deyil.\n\nQayıq sahildən yavaşca uzaqlaşır. Tələsmir, haraya isə çatmağa çalışmır. Yüngül meh onu öz sürəti ilə aparır.\n\nQayıq bir suzanbağı yarpağının yanından keçir, ona yüngülcə toxunur, sonra yoluna davam edir. Bir qurbağa səssizcə suya tullanır; kiçik halqalar yayılır və yavaş-yavaş itir.\n\nSən torpağın üstündə oturursan; altındakı yer ilıq və möhkəmdir. Qayığı idarə etməyə ehtiyac yoxdur. Sadəcə bax.\n\nNəfəsini izlə. Qayıq uzaqlaşdıqca nəfəsini ver. Bir az da uzaqlaşanda bir dəfə də ver. Hər nəfəs verəndə çiyinlərin bir az da enir, əllərin bir az da boşalır.\n\nSu axşam işığını yumşaqca əks etdirir. Qayıq yavaşca fırlanır, sonra yenə süzülür.\n\nQayıq indi gölməçənin ortasındadır, kiçik ağ bir nöqtə kimi. Gözünü ondan çəkmədən dərin nəfəs alırsan və uzun-uzun verirsən.\n\nHava qaralır. İlk ulduzlar gölməçənin səthində əks olunur. Qayıq sanki ulduzların arasında üzür. Artıq onu demək olar ki, görmək olmur.\n\nBəzi şeyləri buraxmaq belədir: onları suya qoyursan və öz yolu ilə getməsinə icazə verirsən.\n\nBir az da sahildə oturursan. Əllərin boş və yüngüldür. Gölməçə sakit, gecə ilıqdır. Qayıq getdiyi yerə öz sürəti ilə çatacaq. Onu izləməyinə ehtiyac yoxdur.\n\nQalxıb evə qayıdanda addımların yumşaqdır. İçində bir yer bir az da genişlənib. Bu gecə buraxa bildiyin qədər buraxdın və bu kifayətdir.",
    ru: "Ты сидишь на берегу маленького пруда. Наступил вечер, воздух тёплый. Вода почти не движется.\n\nУ края пруда тихо покачиваются камыши. На воде лежат несколько листьев кувшинки. Небо медленно переходит от оранжевого к розовому, от розового к лиловому.\n\nВ руке у тебя маленький бумажный кораблик. Ты осторожно опускаешь его на воду.\n\nКораблик сложен твоими руками. Края бумаги разглажены, уголки аккуратно прижаты. Теперь он маленький и лёгкий и ровно стоит на воде.\n\nЕсли хочется, можно положить в него что-нибудь: мысль, которая утомила тебя сегодня, фразу, которая всё крутится в голове. Представь, что кладёшь её в кораблик. Она не слишком тяжела для него.\n\nКораблик медленно отплывает от берега. Он не спешит и никуда не опаздывает. Лёгкий ветерок несёт его в своём темпе.\n\nКораблик проплывает мимо листа кувшинки, слегка задевает его и плывёт дальше. Лягушка бесшумно прыгает в воду; маленькие круги расходятся и медленно исчезают.\n\nТы сидишь на земле, тёплой и надёжной. Управлять корабликом не нужно. Просто смотри.\n\nСледи за дыханием. Кораблик отплывает — выдох. Отплывает чуть дальше — ещё один выдох. С каждым выдохом плечи опускаются ещё немного, и руки становятся мягче.\n\nВода мягко отражает вечерний свет. Кораблик медленно поворачивается и снова скользит дальше.\n\nКораблик уже посреди пруда, как маленькая белая точка. Не отводя от него взгляда, ты делаешь глубокий вдох и долго, медленно выдыхаешь.\n\nТемнеет. Первые звёзды отражаются в пруду. Кажется, кораблик плывёт среди звёзд. Его уже почти не видно.\n\nОтпускать что-то бывает именно так: кладёшь на воду и позволяешь ему найти свой путь.\n\nТы ещё немного сидишь на берегу. Руки пустые и лёгкие. Пруд спокоен, ночь тёплая. Кораблик доплывёт туда, куда ему нужно, в своём темпе. Следить за ним не обязательно.\n\nПо дороге домой шаги мягкие. Внутри становится чуть просторнее. Этим вечером отпущено столько, сколько получилось, и этого достаточно.",
  },
  "quiet-well.body": {
    tr: "Eski bir evin avlusundasın. Akşam gölgeleri uzamış, hava serinlemiş.\n\nAvlunun duvarlarına sarmaşıklar tırmanmış. Köşede bir incir ağacı var; yaprakları büyük ve geniş. Yerdeki taşlar gün boyu güneşte ısınmış, şimdi yavaş yavaş serinliyor.\n\nAvlunun ortasında taş bir kuyu var. Kenarları yıllar içinde pürüzsüzleşmiş.\n\nKuyunun üstünde eski bir makara ve ince bir ip duruyor. İpin ucunda bakır bir kova asılı. Kova hafifçe sallanıyor, sonra duruyor.\n\nKuyunun yanına gidiyorsun ve avucunu serin taş kenara koyuyorsun.\n\nTaş serin ve pürüzsüz. Onu yüzyıllardır kaç el tuttu, kaç kişi buradan su çekti… Hepsi gelip geçti, kuyu yerinde kaldı. Avucunu taşın üstünde biraz daha bırakıyorsun.\n\nKuyunun kenarına oturuyorsun. Sırtın dik ama rahat, ayakların yerde. Nefes alıyorsun; serin, nemli bir hava. Veriyorsun ve omuzların aşağı iniyor.\n\nAşağıda su sakin. Derinliğini merak etmene, dibini yoklamana gerek yok. Sadece serinliğini hisset.\n\nKovayı yavaşça aşağı sarkıtıyorsun. İp makaranın üstünden usulca kayıyor. Aşağıdan, çok derinden, kovanın suya değdiği yumuşak bir ses geliyor.\n\nKovayı yukarı çekiyorsun. Su berrak ve buz gibi. Avucunu suya daldırıyorsun ve serinlik bileğine kadar yayılıyor. Biraz suyu yüzüne serpiyorsun. Alnın, gözlerin, yanakların ferahlıyor.\n\nAvluda bir kuş son kez ötüyor, sonra her şey sessizleşiyor. Taşın serinliği avucundan koluna yayılıyor.\n\nGökyüzü koyulaşıyor. Avlunun üstünde ilk yıldızlar beliriyor. Kuyunun suyunda da küçük bir yıldız parlıyor; aşağıda, derinde, sakin.\n\nİncir ağacının yaprakları hafif bir esintiyle hışırdıyor. Sonra rüzgâr da duruyor. Avlu tamamen sessiz.\n\nKuyu yüzyıllardır burada, suyunu sabırla tutuyor. Sen de kenarında oturup dinlenebilirsin.\n\nBu gece içinde ne varsa, kuyunun derinliği gibi, onu da sabırla tutabilirsin. Hepsini şimdi anlaman gerekmiyor. Su orada, sakin. Sen de buradasın, sakin.\n\nGözlerini kapat. Taşın serinliği, suyun sessizliği ve yıldızların ışığı seninle. Avlu seni koruyor, gece seni sarıyor.",
    en: "You are in the courtyard of an old house. The evening shadows have grown long, and the air has cooled.\n\nIvy has climbed the walls of the courtyard. In the corner there is a fig tree with big, broad leaves. The stones on the ground have been warmed by the sun all day, and now they are slowly cooling.\n\nIn the middle of the courtyard there is a stone well. Its rim has been worn smooth over the years.\n\nAbove the well there is an old pulley and a thin rope. A copper bucket hangs from the end of the rope. It sways a little, then is still.\n\nYou walk over and rest your palm on the cool stone edge.\n\nThe stone is cool and smooth. How many hands have held it over the centuries, how many people have drawn water here… They all came and went, and the well stayed where it is. You leave your palm on the stone a little longer.\n\nYou sit down on the edge of the well. Your back is upright but relaxed, your feet on the ground. You breathe in; cool, damp air. You breathe out, and your shoulders drop.\n\nBelow, the water is still. You do not need to wonder how deep it is or reach for the bottom. Just feel its coolness.\n\nYou lower the bucket slowly. The rope slides gently over the pulley. From far below, very deep, comes the soft sound of the bucket touching the water.\n\nYou pull the bucket up. The water is clear and ice cold. You dip your hand in, and the coolness spreads up to your wrist. You splash a little water on your face. Your forehead, your eyes, your cheeks feel fresh.\n\nA bird sings once more in the courtyard, and then everything grows quiet. The coolness of the stone spreads from your palm up your arm.\n\nThe sky darkens. The first stars appear above the courtyard. A small star shines in the water of the well too; down below, deep, and still.\n\nThe leaves of the fig tree rustle in a light breeze. Then even the wind stops. The courtyard is completely quiet.\n\nThe well has been here for centuries, patiently holding its water. You can sit beside it and rest.\n\nWhatever you are carrying tonight, you can hold it patiently too, like the depth of the well. You do not need to understand all of it now. The water is there, calm. And you are here, calm.\n\nClose your eyes. The coolness of the stone, the stillness of the water and the light of the stars are with you. The courtyard is keeping you safe, and the night is wrapping around you.",
    az: "Köhnə bir evin həyətindəsən. Axşam kölgələri uzanıb, hava sərinləyib.\n\nHəyətin divarlarına sarmaşıq dırmaşıb. Küncdə iri, enli yarpaqlı bir əncir ağacı var. Yerdəki daşlar bütün günü günəşdə qızıb, indi yavaş-yavaş sərinləyir.\n\nHəyətin ortasında daş bir quyu var. Kənarları illər ərzində hamarlanıb.\n\nQuyunun üstündə köhnə bir çarx və nazik bir ip var. İpin ucunda mis bir vedrə asılıb. Vedrə yüngülcə yırğalanır, sonra dayanır.\n\nQuyunun yanına gedib ovucunu sərin daş kənara qoyursan.\n\nDaş sərin və hamardır. Əsrlər boyu onu neçə əl tutub, neçə adam buradan su çəkib… Hamısı gəlib keçib, quyu isə yerində qalıb. Ovucunu daşın üstündə bir az da saxlayırsan.\n\nQuyunun kənarında oturursan. Kürəyin düz, amma rahatdır, ayaqların yerdədir. Nəfəs alırsan; sərin, nəmli bir hava. Nəfəs verirsən və çiyinlərin aşağı enir.\n\nAşağıda su sakitdir. Onun dərinliyini düşünməyə, dibini yoxlamağa ehtiyac yoxdur. Sadəcə sərinliyini hiss et.\n\nVedrəni yavaşca aşağı sallayırsan. İp çarxın üstündən yavaşca sürüşür. Aşağıdan, çox dərindən, vedrənin suya toxunduğu yumşaq bir səs gəlir.\n\nVedrəni yuxarı çəkirsən. Su dumduru və buz kimidir. Ovucunu suya salırsan və sərinlik biləyinə qədər yayılır. Bir az suyu üzünə çiləyirsən. Alnın, gözlərin, yanaqların təravətlənir.\n\nHəyətdə bir quş son dəfə oxuyur, sonra hər şey susur. Daşın sərinliyi ovucundan qoluna yayılır.\n\nSəma tündləşir. Həyətin üstündə ilk ulduzlar görünür. Quyunun suyunda da kiçik bir ulduz parlayır; aşağıda, dərində, sakit.\n\nƏncir ağacının yarpaqları yüngül bir mehlə xışıldayır. Sonra külək də dayanır. Həyət tamamilə sakitdir.\n\nQuyu əsrlərdir buradadır, suyunu səbirlə saxlayır. Sən də onun kənarında oturub dincələ bilərsən.\n\nBu gecə içində nə varsa, quyunun dərinliyi kimi onu da səbirlə saxlaya bilərsən. Hamısını indi anlamağa ehtiyac yoxdur. Su oradadır, sakit. Sən də buradasan, sakit.\n\nGözlərini yum. Daşın sərinliyi, suyun sükutu və ulduzların işığı səninlədir. Həyət səni qoruyur, gecə səni bürüyür.",
    ru: "Ты во дворе старого дома. Вечерние тени стали длинными, воздух посвежел.\n\nСтены двора увиты плющом. В углу растёт инжир с большими широкими листьями. Камни под ногами весь день грелись на солнце и теперь медленно остывают.\n\nПосреди двора стоит каменный колодец. Его края за долгие годы стали гладкими.\n\nНад колодцем старый ворот и тонкая верёвка. На её конце висит медное ведро. Оно чуть покачивается и замирает.\n\nТы подходишь к колодцу и кладёшь ладонь на прохладный каменный край.\n\nКамень прохладный и гладкий. Сколько рук касалось его за века, сколько людей черпали здесь воду… Все приходили и уходили, а колодец оставался на месте. Ты ещё немного держишь ладонь на камне.\n\nТы садишься на край колодца. Спина прямая, но расслабленная, ноги на земле. Вдох — прохладный влажный воздух. Выдох — и плечи опускаются.\n\nВнизу вода неподвижна. Не нужно гадать, насколько он глубок, и не нужно искать дно. Просто почувствуй прохладу.\n\nТы медленно опускаешь ведро. Верёвка тихо скользит по вороту. Снизу, из самой глубины, доносится мягкий звук: ведро касается воды.\n\nТы поднимаешь ведро. Вода прозрачная и ледяная. Ты опускаешь в неё ладонь, и прохлада поднимается до запястья. Немного воды на лицо — и лоб, глаза, щёки освежаются.\n\nВо дворе ещё раз поёт птица, а потом всё затихает. Прохлада камня поднимается от ладони вверх по руке.\n\nНебо темнеет. Над двором появляются первые звёзды. В воде колодца тоже светится маленькая звезда — там, внизу, в глубине, спокойная.\n\nЛистья инжира шелестят от лёгкого ветерка. Потом и ветер стихает. Во дворе совсем тихо.\n\nКолодец стоит здесь веками и терпеливо хранит свою воду. И ты можешь посидеть у его края и отдохнуть.\n\nЧто бы ни было у тебя внутри этой ночью, это тоже можно терпеливо держать, как колодец держит свою глубину. Не нужно понимать всё прямо сейчас. Вода там, спокойная. И ты здесь, спокойно.\n\nЗакрой глаза. Прохлада камня, тишина воды и свет звёзд с тобой. Двор бережёт тебя, ночь укрывает.",
  },
  "safe-list.body": {
    tr: "Zor anlarda düşünmek zorlaşır. Neye ihtiyacın olduğunu bulmak bile yorucu gelebilir. Bu yüzden listeyi sakin bir zamanda, şimdi hazırlıyoruz.\n\nBir kalem ve kâğıt al. Rahat bir yere otur. Bir nefes al ve yavaşça ver.\n\nBeş satırlık bir liste yaz. Her satırda bugün ulaşabileceğin, seni sakinleştiren somut bir şey olsun.\n\nHer maddeyi yazmadan önce bir an düşün. Bu şeye gerçekten ulaşabilir misin? Uzak bir hayal değil, bugün elinin uzanabileceği bir şey olsun.\n\nBir: Ayaklarının bastığı sağlam bir yer. İki: Bir bardak su. Üç: Arayabileceğin bir insan ya da sarılabileceğin yumuşak bir kumaş. Dört: Sevdiğin bir ses. Beş: Seni ısıtan bir şey.\n\nBirinci madde için evinde ya da çevrende sağlam bir yer düşün. Bir sandalye, bir köşe, mutfak masası. Oraya oturduğunda ayakların yere sağlam basıyor.\n\nİkinci madde basit: bir bardak su. Soğuk ya da ılık, hangisi sana iyi geliyorsa. Su içmek bedene “buradayım” der.\n\nÜçüncüsü bir insan ya da bir doku. Telefonla arayabileceğin birinin adını yaz. Ya da sarılabileceğin bir battaniyeyi, yumuşak bir kazağı.\n\nDördüncüsü bir ses. Bir şarkı, bir ses kaydı, yağmur sesi, sevdiğin birinin sesi. Beşincisi seni ısıtan bir şey: sıcak bir duş, bir fincan çay, güneşli bir pencere kenarı.\n\nYarın için değil, bugün için yaz.\n\nBugün yazdığın liste yarın değişebilir. Bu iyi. Liste seninle birlikte büyür ve değişir.\n\nListeyi kolay bulacağın bir yere koy. Zor bir anda ona bakman yeterli.\n\nListeyi telefonunun not kısmına da yazabilirsin. Ya da cüzdanına, buzdolabının kapağına koyabilirsin. Gözünün kolayca değeceği bir yer olsun.\n\nŞimdi listene bir kez daha bak. Beş satır, beş küçük yardımcı. Her birini okurken bir nefes al.\n\nBir dahaki zor anda tek bir satırı seçmen yeterli. Hepsini yapmana gerek yok. Bir bardak su bile bir başlangıçtır.",
    en: "In hard moments, thinking becomes difficult. Even working out what you need can feel exhausting. That is why we make this list at a calm time, now.\n\nTake a pen and paper. Sit somewhere comfortable. Take a breath and let it out slowly.\n\nWrite a list of five lines. Each line should be something concrete and calming that you can reach today.\n\nBefore writing each item, think for a moment. Can you really reach this? Let it not be a distant dream, but something your hand can reach today.\n\nOne: a solid place to stand. Two: a glass of water. Three: a person you can call, or a soft fabric you can hold. Four: a sound you like. Five: something that warms you.\n\nFor the first item, think of a solid place in your home or nearby. A chair, a corner, the kitchen table. When you sit there, your feet are firmly on the ground.\n\nThe second item is simple: a glass of water. Cold or lukewarm, whichever does you good. Drinking water tells the body, “I am here.”\n\nThe third is a person or a texture. Write the name of someone you can phone. Or a blanket you can wrap around you, a soft jumper.\n\nThe fourth is a sound. A song, a recording, the sound of rain, the voice of someone you love. The fifth is something that warms you: a hot shower, a cup of tea, a sunny spot by the window.\n\nWrite it for today, not for tomorrow.\n\nThe list you write today may change tomorrow. That is good. The list grows and changes with you.\n\nKeep the list somewhere easy to find. In a hard moment, simply looking at it is enough.\n\nYou can also write the list in the notes on your phone. Or keep it in your wallet, or on the fridge door. Somewhere your eyes will easily land.\n\nNow look at your list once more. Five lines, five small helpers. Take a breath as you read each one.\n\nIn your next hard moment, choosing a single line is enough. You do not need to do all of them. Even a glass of water is a beginning.",
    az: "Çətin anlarda düşünmək çətinləşir. Nəyə ehtiyacın olduğunu tapmaq belə yorucu gələ bilər. Ona görə də siyahını sakit bir vaxtda, indi hazırlayırıq.\n\nQələm və kağız götür. Rahat bir yerdə otur. Bir nəfəs al və yavaşca ver.\n\nBeş sətirlik bir siyahı yaz. Hər sətirdə bu gün əlinin çata biləcəyi, səni sakitləşdirən konkret bir şey olsun.\n\nHər bəndi yazmazdan əvvəl bir an düşün. Bu şeyə həqiqətən çata bilərsənmi? Uzaq bir xəyal yox, bu gün əlinin çata biləcəyi bir şey olsun.\n\nBir: Ayaqlarının basdığı möhkəm bir yer. İki: Bir stəkan su. Üç: Zəng edə biləcəyin bir insan və ya qucaqlaya biləcəyin yumşaq bir parça. Dörd: Sevdiyin bir səs. Beş: Səni isidən bir şey.\n\nBirinci bənd üçün evində və ya yaxınlıqda möhkəm bir yer düşün. Bir stul, bir künc, mətbəx masası. Orada oturanda ayaqların yerə möhkəm basır.\n\nİkinci bənd sadədir: bir stəkan su. Soyuq və ya ilıq, hansı sənə xoş gəlirsə. Su içmək bədənə “buradayam” deyir.\n\nÜçüncüsü bir insan və ya bir toxumadır. Telefonla zəng edə biləcəyin birinin adını yaz. Ya da bürünə biləcəyin bir yorğanı, yumşaq bir sviteri.\n\nDördüncüsü bir səsdir. Bir mahnı, bir səs yazısı, yağış səsi, sevdiyin birinin səsi. Beşincisi səni isidən bir şeydir: isti duş, bir fincan çay, günəşli bir pəncərə kənarı.\n\nSabah üçün yox, bu gün üçün yaz.\n\nBu gün yazdığın siyahı sabah dəyişə bilər. Bu yaxşıdır. Siyahı səninlə birlikdə böyüyür və dəyişir.\n\nSiyahını asan tapacağın bir yerə qoy. Çətin anda ona baxmaq kifayətdir.\n\nSiyahını telefonunun qeydlərinə də yaza bilərsən. Ya da pul kisəndə, soyuducunun qapısında saxlaya bilərsən. Gözünün asanlıqla düşəcəyi bir yer olsun.\n\nİndi siyahına bir dəfə də bax. Beş sətir, beş kiçik köməkçi. Hər birini oxuyanda bir nəfəs al.\n\nNövbəti çətin anda tək bir sətir seçmək kifayətdir. Hamısını etməyə ehtiyac yoxdur. Bir stəkan su da bir başlanğıcdır.",
    ru: "В трудные минуты думать становится тяжело. Даже понять, что тебе нужно, бывает утомительно. Поэтому список мы составляем в спокойное время, сейчас.\n\nВозьми ручку и бумагу. Сядь удобно. Сделай вдох и медленный выдох.\n\nНапиши список из пяти строк. В каждой — что-то конкретное и успокаивающее, до чего можно дотянуться сегодня.\n\nПрежде чем записать каждый пункт, подумай немного. Это правда доступно? Пусть это будет не далёкая мечта, а то, до чего можно дотянуться сегодня.\n\nПервое: надёжное место, где можно стоять. Второе: стакан воды. Третье: человек, которому можно позвонить, или мягкая ткань, которую можно обнять. Четвёртое: звук, который тебе нравится. Пятое: то, что тебя согревает.\n\nДля первого пункта подумай о надёжном месте дома или рядом. Стул, угол, кухонный стол. Когда садишься туда, ступни крепко стоят на полу.\n\nВторой пункт простой: стакан воды. Холодной или тёплой, какая тебе приятнее. Когда пьёшь воду, тело слышит: «Я здесь».\n\nТретий — человек или текстура. Запиши имя того, кому можно позвонить. Или плед, в который можно завернуться, мягкий свитер.\n\nЧетвёртый — звук. Песня, запись, шум дождя, голос любимого человека. Пятый — то, что согревает: горячий душ, чашка чая, солнечное место у окна.\n\nПиши для сегодняшнего дня, а не для завтрашнего.\n\nСписок, написанный сегодня, завтра может измениться. Это хорошо. Он растёт и меняется вместе с тобой.\n\nПоложи список туда, где его легко найти. В трудный момент достаточно просто на него посмотреть.\n\nСписок можно записать и в заметки телефона. Или держать в кошельке, на дверце холодильника. Там, куда легко падает взгляд.\n\nТеперь посмотри на список ещё раз. Пять строк, пять маленьких помощников. На каждой строке сделай вдох.\n\nВ следующую трудную минуту достаточно выбрать одну строку. Делать всё не нужно. Даже стакан воды — это начало.",
  },
  "three-colors.body": {
    tr: "Zihin çok hızlı çalıştığında ya da kaygı yükseldiğinde, gözlerin bile bir yere odaklanmakta zorlanabilir. Bu küçük alıştırma dikkatini yavaşça dış dünyaya çevirir.\n\nBir kalem ve kâğıt al. Rahat bir yere otur. Ayaklarını yere bas ve bir nefes al.\n\nEtrafına bak ve üç renk seç. Her biri için bir satır yaz: rengi ve o renkteki eşyayı.\n\nGözlerini acele etmeden odada gezdir. Önce yakındaki şeylere bak, sonra uzaktakilere. Bir renk gözüne takıldığında orada dur.\n\nÖrneğin: “Mavi, fincan.” “Yeşil, bitki.” “Beyaz, kapı.”\n\nİlk rengi yazdıktan sonra o eşyaya biraz daha bak. Rengin bütün eşyada aynı mı, yoksa bir yerde daha açık, bir yerde daha koyu mu? Işık ona nasıl düşüyor?\n\nSonra ikinci renge geç. Farklı bir renk seç ki gözlerin odada biraz dolaşsın. Ardından üçüncüsü.\n\nSüslü sıfatlara gerek yok; renk ve eşya yeterli.\n\nSadece iki kelime. Bu sadelik zihne iyi gelir. Düşünceler yavaşlar, dikkat gözlerine ve eline iner.\n\nBitirince yazdıklarını bir kez yüksek sesle oku ve defteri kapat.\n\nOkurken her rengin olduğu yere bak. Mavi… fincan. Yeşil… bitki. Beyaz… kapı. Sesinin odada yankılanmasını dinle.\n\nBir nefes al ve yavaşça ver. Omuzların biraz indi mi? Nefesin biraz yavaşladı mı? Küçük bir fark bile yeter.\n\nŞimdi gözlerini bir an kapat ve seçtiğin üç rengi içinden hatırla. Mavi, yeşil, beyaz. Sonra gözlerini aç ve onları yeniden bul. Hepsi yerinde, seni bekliyor.\n\nBu küçük alıştırma, dikkatini yeniden bulunduğun odaya getirir.\n\nİstersen bir tur daha yap. Bu kez farklı üç renk bul. Ya da aynı renklerin başka eşyalarda nerede olduğunu ara.\n\nBu alıştırmayı gün içinde her yerde yapabilirsin: otobüste, işte, bir bekleme salonunda. Kâğıt olmasa da içinden söylemek yeter. Üç renk… ve sen buradasın.",
    en: "When the mind is racing or anxiety is rising, even your eyes can struggle to settle on anything. This small exercise slowly turns your attention to the world outside.\n\nTake a pen and paper. Sit somewhere comfortable. Put your feet on the floor and take a breath.\n\nLook around and choose three colors. Write one line for each: the color and an object of that color.\n\nLet your eyes wander around the room without hurrying. First look at things nearby, then things further away. When a colour catches your eye, stop there.\n\nFor example: “Blue, cup.” “Green, plant.” “White, door.”\n\nAfter you write the first colour, look at that object a little longer. Is the colour the same all over, or lighter in one place and darker in another? How does the light fall on it?\n\nThen move on to the second colour. Choose a different one, so your eyes travel around the room a little. Then the third.\n\nNo fancy adjectives needed; the color and the object are enough.\n\nJust two words. This simplicity is good for the mind. Thoughts slow down, and attention moves into your eyes and your hand.\n\nWhen you finish, read the lines aloud once, then close the notebook.\n\nAs you read, look at where each colour is. Blue… cup. Green… plant. White… door. Listen to your voice in the room.\n\nTake a breath and let it out slowly. Have your shoulders dropped a little? Has your breath slowed a little? Even a small difference is enough.\n\nNow close your eyes for a moment and recall the three colours you chose. Blue, green, white. Then open your eyes and find them again. They are all in their places, waiting for you.\n\nThis small exercise brings your attention back to the room you are in.\n\nIf you like, do one more round. This time find three different colours. Or look for where the same colours appear on other objects.\n\nYou can do this anywhere during the day: on the bus, at work, in a waiting room. Even without paper, saying it silently is enough. Three colours… and you are here.",
    az: "Ağıl çox sürətlə işləyəndə və ya narahatlıq artanda, hətta gözlər də bir yerə fokuslanmaqda çətinlik çəkə bilər. Bu kiçik məşq diqqətini yavaş-yavaş xarici dünyaya çevirir.\n\nQələm və kağız götür. Rahat bir yerdə otur. Ayaqlarını yerə bas və bir nəfəs al.\n\nƏtrafına bax və üç rəng seç. Hər biri üçün bir sətir yaz: rəngi və o rəngdə olan əşyanı.\n\nGözlərini tələsmədən otaqda gəzdir. Əvvəlcə yaxındakı şeylərə bax, sonra uzaqdakılara. Bir rəng gözünə dəyəndə orada dayan.\n\nMəsələn: “Mavi, fincan.” “Yaşıl, gül dibçəyi.” “Ağ, qapı.”\n\nİlk rəngi yazandan sonra o əşyaya bir az da bax. Rəng bütün əşyada eynidirmi, yoxsa bir yerdə daha açıq, bir yerdə daha tünd? İşıq ona necə düşür?\n\nSonra ikinci rəngə keç. Fərqli bir rəng seç ki, gözlərin otaqda bir az gəzsin. Sonra üçüncüsü.\n\nBəzəkli sifətlərə ehtiyac yoxdur; rəng və əşya kifayətdir.\n\nSadəcə iki söz. Bu sadəlik ağla xeyirdir. Fikirlər yavaşlayır, diqqət gözlərinə və əlinə enir.\n\nBitirəndə yazdıqlarını bir dəfə ucadan oxu və dəftəri bağla.\n\nOxuyanda hər rəngin olduğu yerə bax. Mavi… fincan. Yaşıl… gül dibçəyi. Ağ… qapı. Səsinin otaqda necə eşidildiyinə qulaq as.\n\nBir nəfəs al və yavaşca ver. Çiyinlərin bir az endimi? Nəfəsin bir az yavaşladımı? Kiçik bir fərq də kifayətdir.\n\nİndi gözlərini bir anlıq yum və seçdiyin üç rəngi içində xatırla. Mavi, yaşıl, ağ. Sonra gözlərini aç və onları yenidən tap. Hamısı yerindədir, səni gözləyir.\n\nBu kiçik məşq diqqətini yenidən olduğun otağa qaytarır.\n\nİstəsən, bir dəfə də et. Bu dəfə fərqli üç rəng tap. Ya da eyni rənglərin başqa əşyalarda harada olduğunu axtar.\n\nBu məşqi gün ərzində hər yerdə edə bilərsən: avtobusda, işdə, gözləmə zalında. Kağız olmasa da, içində demək kifayətdir. Üç rəng… və sən buradasan.",
    ru: "Когда ум мчится или тревога растёт, даже глазам бывает трудно на чём-то остановиться. Это маленькое упражнение мягко поворачивает внимание к внешнему миру.\n\nВозьми ручку и бумагу. Сядь удобно. Поставь ступни на пол и сделай вдох.\n\nОглянись и выбери три цвета. Для каждого напиши строку: цвет и предмет этого цвета.\n\nНе спеша веди взгляд по комнате. Сначала смотри на то, что рядом, потом на то, что дальше. Когда какой-то цвет привлечёт внимание, остановись на нём.\n\nНапример: «Синий — чашка». «Зелёный — растение». «Белый — дверь».\n\nЗаписав первый цвет, посмотри на этот предмет чуть дольше. Цвет везде одинаковый или где-то светлее, а где-то темнее? Как на него падает свет?\n\nПотом переходи ко второму цвету. Выбери другой, чтобы взгляд немного прошёлся по комнате. Потом третий.\n\nКрасивые прилагательные не нужны; цвета и предмета достаточно.\n\nВсего два слова. Эта простота полезна для ума. Мысли замедляются, внимание опускается в глаза и в руку.\n\nКогда закончишь, один раз прочитай написанное вслух и закрой тетрадь.\n\nПока читаешь, смотри туда, где находится каждый цвет. Синий… чашка. Зелёный… растение. Белый… дверь. Послушай, как звучит твой голос в комнате.\n\nСделай вдох и медленный выдох. Плечи немного опустились? Дыхание чуть замедлилось? Даже маленькой разницы достаточно.\n\nТеперь на мгновение закрой глаза и вспомни три выбранных цвета. Синий, зелёный, белый. Потом открой глаза и найди их снова. Все на своих местах и ждут тебя.\n\nЭто небольшое упражнение возвращает внимание в комнату, где ты находишься.\n\nЕсли хочется, сделай ещё один круг. На этот раз найди три других цвета. Или поищи, где те же цвета встречаются на других предметах.\n\nЭто можно делать где угодно в течение дня: в автобусе, на работе, в зале ожидания. Даже без бумаги достаточно назвать про себя. Три цвета… и ты здесь.",
  },
  "unsend.body": {
    tr: "Bazen bir konuşma ya da tartışma aklımızda bitmek bilmez. Bu yazı onu kapatmana yardım eder.\n\nBunu yapmadan önce rahat bir yere otur. Bir defter ya da birkaç boş kâğıt al. Bir nefes al ve yavaşça ver. Aklında dönüp duran konuşmayı hatırla, ama içine çekilmeden, uzaktan bakar gibi.\n\nBirine ya da kendine bir mektup yaz. Bu mektup hiçbir zaman gönderilmeyecek; o yüzden aklından geçeni olduğu gibi yazabilirsin.\n\nMektuba “Sevgili…” diye başlayabilirsin ya da doğrudan yazmaya geçebilirsin. Kime yazdığın önemli; ama nasıl yazdığın önemli değil. Kurallara uyman gerekmiyor.\n\nİstersen kaydı burada durdur ve yazmaya başla. Bitirdiğinde geri dön.\n\nKızgınlık, üzüntü, keşke dediklerin… hepsine yer var.\n\nYazarken bedenini fark et. Belki çenen kasılıyor, belki ellerin ısınıyor, belki gözlerin doluyor. Hepsi olabilir. Duygular kâğıda aktıkça bedende biraz yer açılır.\n\nBir yerde takılırsan bir nefes al. Sonra aklına gelen ilk kelimeyle devam et. Doğru kelimeyi bulman gerekmiyor.\n\nSon paragrafa şunu yaz: “Bunu bu gece çözmeyeceğim.”\n\nBu cümle bir kapı kapatır. Konuşma bitmemiş olabilir, ama bu gecelik bitti. Sorun yarın da orada olacak; ama şu an onu taşımak zorunda değilsin.\n\nCümleyi yazdıktan sonra kalemi bırak. Ellerini kâğıdın üstüne koy. Bir nefes al… ve ver.\n\nSonra mektubu katla ve kaldır. Tekrar okumana gerek yok. Bu gece için yeterince söyledin.\n\nMektubu bir çekmeceye, bir kutuya ya da defterin arasına koyabilirsin. Bazı insanlar onu birkaç gün sonra yırtıp atmayı sever. Bu da senin kararın.\n\nŞimdi kendine küçük bir iyilik yap. Bir bardak su iç, yüzünü yıka ya da omuzlarını birkaç kez çevir. Bedenine bu gecenin bittiğini haber ver.\n\nKonuşma yeniden aklına gelirse, kendine nazikçe hatırlat: “Bunu yazdım. Bu gece çözmeyeceğim.” Ve nefesine dön.",
    en: "Sometimes a conversation or an argument keeps going in our heads. This exercise helps you close it.\n\nBefore you start, sit somewhere comfortable. Take a notebook or a few blank sheets. Take a breath and let it out slowly. Remember the conversation that keeps going round in your head, but without being pulled into it; look at it as if from a distance.\n\nWrite a letter to someone, or to yourself. It will never be sent, so you can write exactly what is on your mind.\n\nYou can begin with “Dear…”, or simply start writing. Who you are writing to matters; how you write does not. You do not have to follow any rules.\n\nIf you like, pause the recording here and start writing. Come back when you have finished.\n\nAnger, sadness, the things you wish had been different… there is room for all of it.\n\nAs you write, notice your body. Perhaps your jaw is clenching, perhaps your hands are warming up, perhaps your eyes are filling with tears. All of that is fine. As feelings flow onto the paper, a little space opens up in the body.\n\nIf you get stuck, take a breath. Then carry on with the first word that comes. You do not need to find the right word.\n\nIn the last paragraph, write: “I will not solve this tonight.”\n\nThis sentence closes a door. The conversation may not be finished, but it is finished for tonight. The problem will still be there tomorrow; but right now you do not have to carry it.\n\nAfter you write the sentence, put the pen down. Rest your hands on the paper. Breathe in… and out.\n\nThen fold the letter and put it away. You do not need to read it again. You have said enough for tonight.\n\nYou can put the letter in a drawer, a box, or between the pages of a notebook. Some people like to tear it up a few days later. That is your choice too.\n\nNow do something small and kind for yourself. Drink a glass of water, wash your face, or roll your shoulders a few times. Let your body know that tonight is over.\n\nIf the conversation comes back to mind, gently remind yourself: “I have written this. I will not solve it tonight.” And return to your breath.",
    az: "Bəzən bir söhbət və ya mübahisə ağlımızda heç bitmir. Bu yazı onu bağlamağa kömək edir.\n\nBaşlamazdan əvvəl rahat bir yerdə otur. Bir dəftər və ya bir neçə boş vərəq götür. Bir nəfəs al və yavaşca ver. Ağlında fırlanan söhbəti xatırla, amma onun içinə çəkilmədən, sanki uzaqdan baxırsan.\n\nKiməsə və ya özünə məktub yaz. Bu məktub heç vaxt göndərilməyəcək; ona görə də ağlından keçəni olduğu kimi yaza bilərsən.\n\nMəktuba “Əziz…” deyə başlaya bilərsən, ya da birbaşa yazmağa keçə bilərsən. Kimə yazdığın vacibdir; necə yazdığın isə vacib deyil. Qaydalara əməl etməli deyilsən.\n\nİstəsən, səsi burada dayandır və yazmağa başla. Bitirəndə geri qayıt.\n\nHirs, kədər, “kaş” dediklərin… hamısına yer var.\n\nYazanda bədəninin fərqinə var. Bəlkə çənən sıxılır, bəlkə əllərin isinir, bəlkə gözlərin dolur. Hamısı ola bilər. Hisslər kağıza axdıqca bədəndə bir az yer açılır.\n\nBir yerdə ilişib qalsan, bir nəfəs al. Sonra ağlına gələn ilk sözlə davam et. Doğru sözü tapmağa ehtiyac yoxdur.\n\nSon abzasa bunu yaz: “Bunu bu gecə həll etməyəcəyəm.”\n\nBu cümlə bir qapını bağlayır. Söhbət bitməmiş ola bilər, amma bu gecəlik bitdi. Məsələ sabah da orada olacaq; amma indi onu daşımaq məcburiyyətində deyilsən.\n\nCümləni yazandan sonra qələmi burax. Əllərini kağızın üstünə qoy. Nəfəs al… və ver.\n\nSonra məktubu qatla və qaldır. Yenidən oxumağa ehtiyac yoxdur. Bu gecə üçün kifayət qədər dedin.\n\nMəktubu bir siyirməyə, bir qutuya və ya dəftərin arasına qoya bilərsən. Bəziləri onu bir neçə gün sonra cırıb atmağı sevir. Bu da sənin qərarındır.\n\nİndi özünə kiçik bir yaxşılıq et. Bir stəkan su iç, üzünü yu və ya çiyinlərini bir neçə dəfə fırlat. Bədəninə bu gecənin bitdiyini xəbər ver.\n\nSöhbət yenə ağlına gəlsə, özünə yumşaqca xatırlat: “Bunu yazdım. Bu gecə həll etməyəcəyəm.” Və nəfəsinə qayıt.",
    ru: "Иногда разговор или спор продолжается в голове без конца. Это упражнение помогает его закрыть.\n\nПеред началом сядь удобно. Возьми тетрадь или несколько чистых листов. Сделай вдох и медленный выдох. Вспомни разговор, который крутится в голове, но не погружайся в него, а смотри как будто издалека.\n\nНапиши письмо кому-то или себе. Оно никогда не будет отправлено, поэтому можно написать всё как есть.\n\nМожно начать со слов «Дорогой…» или «Дорогая…», а можно сразу писать. Важно, кому ты пишешь; как именно пишешь — неважно. Никаких правил соблюдать не нужно.\n\nЕсли хочется, поставь запись на паузу и начни писать. Вернись, когда закончишь.\n\nЗлость, грусть, то, что хотелось бы изменить… для всего этого есть место.\n\nПока пишешь, замечай тело. Может быть, сжимается челюсть, теплеют руки, на глаза наворачиваются слёзы. Всё это возможно. Когда чувства переходят на бумагу, в теле освобождается немного места.\n\nЕсли где-то застреваешь, сделай вдох. Потом продолжи с первого слова, которое придёт. Искать правильное слово не нужно.\n\nВ последнем абзаце напиши: «Сегодня ночью я это не решаю».\n\nЭта фраза закрывает дверь. Разговор, может быть, не окончен, но на эту ночь он закончен. Вопрос будет на месте и завтра, но сейчас нести его не обязательно.\n\nКогда фраза написана, отложи ручку. Положи ладони на лист. Вдох… и выдох.\n\nПотом сложи письмо и убери. Перечитывать его не нужно. На сегодня сказано достаточно.\n\nПисьмо можно положить в ящик, в коробку или между страницами тетради. Некоторым нравится через несколько дней его порвать. Это тоже твоё решение.\n\nТеперь сделай для себя что-нибудь маленькое и доброе. Выпей стакан воды, умойся или несколько раз покрути плечами. Дай телу знать, что этот вечер закончен.\n\nЕсли разговор снова придёт на ум, мягко напомни себе: «Я это записываю. Сегодня ночью я это не решаю». И возвращайся к дыханию.",
  },
  "wagon.body": {
    tr: "Bir gece treninin orta vagonundasın. Pencere kenarındaki koltuğa yerleşmişsin; vagonda senden başka kimse yok.\n\nİstasyonda birkaç yolcu vardı ama hepsi başka vagonlara dağıldı. Kompartımanın kapısını kapattın. Yanındaki koltuğa hafif bir çanta bıraktın ve paltonu askıya astın.\n\nVagonun içi loş. Tavandaki küçük lambalar yumuşak, sarımsı bir ışık veriyor. Koltuğun kumaşı kalın ve sıcak. Başını yaslayabileceğin yumuşak bir yastık var.\n\nTekerlekler raylarda düzenli bir ritimle tıkırdıyor. Tık tık… tık tık. Bu ses hiç değişmiyor ve seni yavaşça sallıyor.\n\nBir süre sadece bu ritmi dinliyorsun. Tık tık… tık tık. Nefesin, fark etmeden bu ritme uyuyor. Nefes al… tık tık… nefes ver… tık tık.\n\nDışarıda karanlık ovalar akıp gidiyor. Arada bir uzak bir köyün ışığı görünüyor, sonra kayboluyor. Camda nefesinin bıraktığı ince bir buğu var.\n\nBir köprünün üstünden geçiyorsun. Aşağıda karanlık bir nehir parlıyor, üstünde ayın ince bir yansıması var. Köprüden sonra tren yeniden ovaya iniyor ve ritim tekrar yumuşuyor.\n\nKondüktör koridordan sessizce geçiyor. Biletine bakmıyor bile; sadece başıyla selam veriyor ve kapıyı usulca kapatıyor. Her şey yolunda. Senin bir şey kontrol etmen gerekmiyor.\n\nAyakların yere basıyor; trenin hafif titreşimi seni koltuğuna yerleştiriyor. Koridor boş ve loş.\n\nTermosundan biraz ılık çay döküyorsun. Bardağı iki elinle tutuyorsun; sıcaklık parmaklarından avuçlarına yayılıyor. Küçük bir yudum alıyorsun ve bardağı masaya bırakıyorsun.\n\nTren kısa bir tünele giriyor, ses bir an değişiyor… sonra yine açık havaya çıkıyor ve ritim geri geliyor.\n\nUzakta küçük bir istasyonun ışıkları görünüyor. Tren yavaşlamıyor bile; ışıklar camın önünden kayıp geçiyor ve yeniden karanlık geliyor. Bu gece inmen gereken bir durak yok.\n\nBattaniyeyi dizlerine çekiyorsun. Omuzların koltuğa gömülüyor. Trenin sallantısı bir beşik gibi, yavaş ve düzenli. Her sallantıda biraz daha ağırlaşıyorsun.\n\nNereye vardığını düşünmene gerek yok. Tren yolu biliyor. Gözlerin ağırlaşırsa kapanmalarına izin ver. Raylar seni taşıyor.\n\nTık tık… tık tık. Ova uzanıyor, gece uzanıyor. Sen de uzanıyorsun. Sabaha kadar tren yol alacak, sen dinleneceksin.",
    en: "You are in the middle carriage of a night train. You have settled into a window seat, and there is no one else in the carriage.\n\nThere were a few passengers at the station, but they all went to other carriages. You closed the compartment door. You put a light bag on the seat beside you and hung your coat on the hook.\n\nThe carriage is dimly lit. Small lamps in the ceiling give a soft, yellowish light. The fabric of the seat is thick and warm. There is a soft pillow where you can rest your head.\n\nThe wheels click on the rails in a steady rhythm. Click-clack… click-clack. The sound never changes, and it rocks you gently.\n\nFor a while you simply listen to this rhythm. Click-clack… click-clack. Without noticing, your breath begins to follow it. Breathe in… click-clack… breathe out… click-clack.\n\nOutside, dark fields roll past. Now and then the light of a distant village appears, then disappears. Your breath leaves a faint mist on the glass.\n\nYou cross a bridge. Below, a dark river gleams with a thin reflection of the moon. After the bridge, the train comes down onto the plain again, and the rhythm softens once more.\n\nThe conductor walks quietly down the aisle. He does not even check your ticket; he just nods and slides the door gently shut. Everything is in order. There is nothing you need to check.\n\nYour feet rest on the floor, and the soft hum of the train settles you into your seat. The aisle is empty and dim.\n\nYou pour a little warm tea from your flask. You hold the cup in both hands; the warmth spreads from your fingers into your palms. You take a small sip and set the cup down on the little table.\n\nThe train slips into a short tunnel, and the sound changes for a moment… then it comes out into the open air again, and the rhythm returns.\n\nIn the distance you see the lights of a small station. The train does not even slow down; the lights slide past the window, and then it is dark again. There is no stop where you need to get off tonight.\n\nYou pull the blanket over your knees. Your shoulders sink into the seat. The sway of the train is like a cradle, slow and even. With every sway you grow a little heavier.\n\nYou do not need to think about where you will arrive. The train knows the way. If your eyes grow heavy, let them close. The rails are carrying you.\n\nClick-clack… click-clack. The plain stretches out, the night stretches out. And you stretch out too. The train will travel until morning, and you will rest.",
    az: "Gecə qatarının orta vaqonundasan. Pəncərə kənarındakı oturacağa yerləşmisən; vaqonda səndən başqa heç kim yoxdur.\n\nStansiyada bir neçə sərnişin var idi, amma hamısı başqa vaqonlara keçdi. Kupenin qapısını bağladın. Yanındakı oturacağa yüngül bir çanta qoydun, paltonu da asılqana asdın.\n\nVaqonun içi yarıqaranlıqdır. Tavandakı kiçik lampalar yumşaq, sarımtıl işıq saçır. Oturacağın parçası qalın və istidir. Başını söykəyə biləcəyin yumşaq bir yastıq var.\n\nTəkərlər relslərdə ahəngdar səslə taqqıldayır. Taq-taq… taq-taq. Bu səs heç dəyişmir və səni yavaşca yırğalayır.\n\nBir müddət sadəcə bu ahəngi dinləyirsən. Taq-taq… taq-taq. Nəfəsin də hiss etmədən bu ahəngə uyğunlaşır. Nəfəs al… taq-taq… nəfəs ver… taq-taq.\n\nÇöldə qaranlıq düzənliklər axıb gedir. Arabir uzaq bir kəndin işığı görünür, sonra itir. Şüşədə nəfəsinin buraxdığı incə bir buğu var.\n\nBir körpünün üstündən keçirsən. Aşağıda qaranlıq bir çay parlayır, üstündə ayın incə əksi var. Körpüdən sonra qatar yenə düzənliyə enir və ahəng yenidən yumşalır.\n\nBələdçi dəhlizdən səssizcə keçir. Biletinə baxmır da; sadəcə başı ilə salam verir və qapını yavaşca bağlayır. Hər şey qaydasındadır. Sənin heç nəyi yoxlamağına ehtiyac yoxdur.\n\nAyaqların yerə basır; qatarın yüngül titrəyişi səni oturacağına yerləşdirir. Dəhliz boş və yarıqaranlıqdır.\n\nTermosundan bir az ilıq çay tökürsən. Stəkanı iki əllə tutursan; istilik barmaqlarından ovuclarına yayılır. Kiçik bir qurtum içib stəkanı masaya qoyursan.\n\nQatar qısa bir tunelə girir, səs bir anlıq dəyişir… sonra yenə açıq havaya çıxır və ahəng geri qayıdır.\n\nUzaqda kiçik bir stansiyanın işıqları görünür. Qatar heç yavaşımır da; işıqlar şüşənin önündən sürüşüb keçir və yenə qaranlıq gəlir. Bu gecə düşməli olduğun dayanacaq yoxdur.\n\nYorğanı dizlərinə çəkirsən. Çiyinlərin oturacağa gömülür. Qatarın yırğalanması beşik kimidir, yavaş və ahəngdar. Hər yırğalanmada bir az da ağırlaşırsan.\n\nHara çatacağını düşünməyə ehtiyac yoxdur. Qatar yolu bilir. Gözlərin ağırlaşsa, qoy yumulsun. Relslər səni aparır.\n\nTaq-taq… taq-taq. Düzənlik uzanır, gecə uzanır. Sən də uzanırsan. Səhərə qədər qatar yol gedəcək, sən isə dincələcəksən.",
    ru: "Ты в среднем вагоне ночного поезда. Ты сидишь у окна, и кроме тебя в вагоне никого нет.\n\nНа станции было несколько пассажиров, но все они разошлись по другим вагонам. Дверь купе закрыта. На соседнем сиденье лежит лёгкая сумка, пальто висит на крючке.\n\nВ вагоне полумрак. Маленькие лампы под потолком дают мягкий желтоватый свет. Ткань сиденья плотная и тёплая. Есть мягкая подушка, на которую можно положить голову.\n\nКолёса ровно стучат по рельсам. Тук-тук… тук-тук. Звук не меняется и тихо убаюкивает.\n\nКакое-то время ты просто слушаешь этот ритм. Тук-тук… тук-тук. Дыхание незаметно подстраивается под него. Вдох… тук-тук… выдох… тук-тук.\n\nЗа окном проплывают тёмные поля. Иногда вдали появляется огонёк деревни и снова исчезает. На стекле — лёгкий след от дыхания.\n\nПоезд идёт по мосту. Внизу блестит тёмная река, в ней тонкое отражение луны. После моста поезд снова спускается на равнину, и ритм опять становится мягче.\n\nПроводник тихо проходит по коридору. Он даже не спрашивает билет; просто кивает и бесшумно закрывает дверь. Всё в порядке. Тебе ничего не нужно проверять.\n\nНоги стоят на полу; мягкая дрожь вагона усаживает тебя глубже в кресло. Проход пуст и полутёмен.\n\nТы наливаешь из термоса немного тёплого чая. Держишь стакан обеими руками; тепло переходит от пальцев к ладоням. Небольшой глоток, и стакан снова стоит на столике.\n\nПоезд ныряет в короткий туннель, звук на мгновение меняется… потом снова открытый воздух, и ритм возвращается.\n\nВдали видны огни маленькой станции. Поезд даже не замедляет ход; огни проплывают мимо окна, и снова темнота. Этой ночью нет остановки, на которой нужно выходить.\n\nТы натягиваешь плед на колени. Плечи утопают в сиденье. Покачивание поезда похоже на колыбель — медленное и ровное. С каждым покачиванием тело становится чуть тяжелее.\n\nНе нужно думать о том, куда ты приедешь. Поезд знает дорогу. Если веки тяжелеют, пусть они закроются. Рельсы несут тебя.\n\nТук-тук… тук-тук. Равнина тянется, ночь тянется. И ты вытягиваешься поудобнее. Поезд будет идти до утра, а ты будешь отдыхать.",
  },
  "weight.body": {
    tr: "Kendini bedeninden uzak, bir izleyici gibi hissettiğin anlar için kısa bir yazı.\n\nBu his bazen yorgunluktan, bazen yoğun stresten sonra gelir. Rahatsız edici olabilir ama tehlikeli değildir. Beden hâlâ burada, sen de buradasın. Sadece bağlantıyı yeniden hissetmek için biraz yardıma ihtiyaç var.\n\nSağlam bir sandalyeye otur. Sırtın yaslansın, ayakların yere değsin. Bir nefes al ve yavaşça ver.\n\nOtur ve dört noktaya dikkat et: sol kalçan, sağ kalçan, sırtın ve ayakların. Her biri için tek kelime yaz: “Var” ya da “Az.”\n\nÖnce sol kalçana odaklan. Sandalyeye ne kadar bastığını fark et. Sonra sağ kalçana. Biri diğerinden daha ağır mı? Sonra sırtını hisset; yaslandığın yerin sertliğini ya da yumuşaklığını. En son ayaklarını; tabanlarının yere değdiği yeri.\n\nHer nokta için durup kelimeni yaz. “Var.” “Az.” Hızlı karar vermene gerek yok.\n\n“Hiç” yazmamaya çalış; çok az da olsa bir temas mutlaka vardır.\n\nBir noktayı hissetmekte zorlanıyorsan, o tarafı biraz hareket ettir. Kalçanı hafifçe kaydır, ayak parmaklarını oynat, sırtını sandalyeye biraz daha bastır. Hareket teması hatırlatır.\n\nSonra adını, bugünün tarihini ve bulunduğun şehri yaz.\n\nAdını yazarken harflerin şekline bak. Kalemin kâğıtta çıkardığı sesi duy. Tarihi yazarken bugünün hangi gün olduğunu düşün. Şehrin adını yazarken penceren dışarıda nasıl görünüyor, hatırla.\n\nBu üç bilgi seni zamana ve yere bağlar. Ben buyum, bugün bugün, burası burası.\n\nBu sayfada aynaya bakmana ya da kendini incelemene gerek yok. Sadece ağırlığını ve nerede olduğunu not ediyorsun.\n\nŞimdi yazdıklarını bir kez sesli oku. Kendi sesini duy. Ardından ellerini dizlerine koy ve avuçlarının sıcaklığını hisset.\n\nBir nefes al… göğsün yükselsin. Ver… omuzların insin. Ağırlığın sandalyede, ayakların yerde. Bu sayfayı katla ve yakınında tut. Gerektiğinde yeniden açabilirsin.",
    en: "A short exercise for moments when you feel detached from your body, like an observer.\n\nThis feeling sometimes comes after tiredness, sometimes after a lot of stress. It can be unsettling, but it is not dangerous. Your body is still here, and so are you. You just need a little help to feel the connection again.\n\nSit on a sturdy chair. Let your back rest against it and your feet touch the floor. Take a breath and let it out slowly.\n\nSit down and notice four points: your left hip, your right hip, your back, and your feet. For each one, write a single word: “There” or “Faint.”\n\nFirst, focus on your left hip. Notice how much it presses into the chair. Then your right hip. Is one heavier than the other? Then feel your back; the firmness or softness of what you are leaning on. Last, your feet; where your soles touch the floor.\n\nPause at each point and write your word. “There.” “Faint.” You do not need to decide quickly.\n\nTry not to write “nothing”; there is always at least a little contact.\n\nIf you are finding it hard to feel a point, move that side a little. Shift your hip slightly, wiggle your toes, press your back a little more into the chair. Movement reminds the body of contact.\n\nThen write your name, today’s date, and the city you are in.\n\nAs you write your name, look at the shape of the letters. Listen to the sound the pen makes on the paper. As you write the date, think about what day it is today. As you write the name of your city, remember how it looks outside your window.\n\nThese three facts connect you to time and place. This is me, today is today, here is here.\n\nOn this page you do not need to look in a mirror or examine yourself. You are only noting your weight and where you are.\n\nNow read what you wrote aloud once. Hear your own voice. Then put your hands on your knees and feel the warmth of your palms.\n\nBreathe in… let your chest rise. Breathe out… let your shoulders drop. Your weight is on the chair, your feet are on the floor. Fold this page and keep it nearby. You can open it again whenever you need to.",
    az: "Özünü bədənindən uzaq, bir tamaşaçı kimi hiss etdiyin anlar üçün qısa bir yazı.\n\nBu hiss bəzən yorğunluqdan, bəzən güclü stressdən sonra gəlir. Narahat edici ola bilər, amma təhlükəli deyil. Bədən hələ buradadır, sən də buradasan. Sadəcə əlaqəni yenidən hiss etmək üçün bir az köməyə ehtiyac var.\n\nMöhkəm bir stulda otur. Kürəyin söykənsin, ayaqların yerə toxunsun. Bir nəfəs al və yavaşca ver.\n\nOtur və dörd nöqtəyə diqqət et: sol omba, sağ omba, kürək və ayaqlar. Hər biri üçün bir söz yaz: “Var” və ya “Az.”\n\nƏvvəlcə sol ombana diqqət et. Stula nə qədər basdığını hiss et. Sonra sağ ombana. Biri o birindən ağırdırmı? Sonra kürəyini hiss et; söykəndiyin yerin sərtliyini və ya yumşaqlığını. Ən sonda ayaqlarını; ayaqaltılarının yerə toxunduğu yeri.\n\nHər nöqtədə dayanıb sözünü yaz. “Var.” “Az.” Tez qərar verməyə ehtiyac yoxdur.\n\n“Heç” yazmamağa çalış; çox az da olsa, mütləq bir təmas var.\n\nBir nöqtəni hiss etməkdə çətinlik çəkirsənsə, o tərəfi bir az tərpət. Ombanı yüngülcə sürüşdür, ayaq barmaqlarını oynat, kürəyini stula bir az da bas. Hərəkət təması xatırladır.\n\nSonra adını, bugünkü tarixi və olduğun şəhəri yaz.\n\nAdını yazanda hərflərin şəklinə bax. Qələmin kağızda çıxardığı səsi eşit. Tarixi yazanda bu günün hansı gün olduğunu düşün. Şəhərin adını yazanda pəncərənin o tayının necə göründüyünü xatırla.\n\nBu üç məlumat səni zamana və məkana bağlayır. Bu mənəm, bu gün bu gündür, bura buradır.\n\nBu səhifədə güzgüyə baxmağa və ya özünü incələməyə ehtiyac yoxdur. Sadəcə ağırlığını və harada olduğunu qeyd edirsən.\n\nİndi yazdıqlarını bir dəfə ucadan oxu. Öz səsini eşit. Sonra əllərini dizlərinə qoy və ovuclarının istiliyini hiss et.\n\nNəfəs al… qoy sinən qalxsın. Ver… qoy çiyinlərin ensin. Ağırlığın stulda, ayaqların yerdədir. Bu səhifəni qatla və yaxınında saxla. Lazım olanda yenidən aça bilərsən.",
    ru: "Короткое упражнение для моментов, когда ощущаешь себя отстранённо от тела, словно наблюдаешь со стороны.\n\nЭто ощущение иногда приходит после усталости, иногда после сильного стресса. Оно может тревожить, но оно не опасно. Тело всё ещё здесь, и ты здесь. Нужно лишь немного помощи, чтобы снова почувствовать связь.\n\nСядь на устойчивый стул. Пусть спина опирается, а ступни касаются пола. Сделай вдох и медленный выдох.\n\nСядь и обрати внимание на четыре точки: левое бедро, правое бедро, спина и стопы. Для каждой напиши одно слово: «Есть» или «Слабо».\n\nСначала сосредоточься на левом бедре. Заметь, насколько оно давит на стул. Потом на правом. Одно тяжелее другого? Потом почувствуй спину: твёрдость или мягкость того, на что опираешься. И в конце стопы, то место, где подошвы касаются пола.\n\nНа каждой точке остановись и запиши своё слово. «Есть». «Слабо». Решать быстро не нужно.\n\nПостарайся не писать «нет»; хоть немного контакта есть всегда.\n\nЕсли какую-то точку трудно почувствовать, немного пошевели этой стороной. Чуть сдвинь бедро, пошевели пальцами ног, сильнее прижми спину к стулу. Движение напоминает о контакте.\n\nПотом напиши своё имя, сегодняшнюю дату и город, в котором находишься.\n\nКогда пишешь имя, посмотри на форму букв. Послушай, как ручка шуршит по бумаге. Когда пишешь дату, подумай, какой сегодня день. Когда пишешь название города, вспомни, как он выглядит за окном.\n\nЭти три сведения связывают тебя со временем и местом. Это я, сегодня — это сегодня, здесь — это здесь.\n\nНа этой странице не нужно смотреть в зеркало или изучать себя. Ты просто отмечаешь свой вес и то, где ты сейчас.\n\nТеперь прочитай написанное вслух один раз. Услышь свой голос. Потом положи ладони на колени и почувствуй их тепло.\n\nВдох… пусть грудь поднимется. Выдох… пусть плечи опустятся. Вес на стуле, ступни на полу. Сложи эту страницу и держи рядом. Её можно открыть снова, когда понадобится.",
  },
  "worry-window.body": {
    tr: "Endişeleri tamamen silmeye çalışmak çoğu zaman işe yaramaz. Onun yerine onlara küçük bir zaman ayır.\n\nBu alıştırmaya başlamadan önce rahat bir yer seç. Masada, yatağın kenarında ya da mutfakta olabilir. Önüne bir defter ve kalem koy. Telefonunu sessize al ama sayaç için yanında tut.\n\nBir nefes al. Endişelerin şu an zihninde dağınık hâlde dolaşıyor olabilir. Birazdan onlara bir yer açacağız. Bir pencere gibi: belli bir süre açık, sonra kapalı.\n\nOn dakikalık bir sayaç kur. Bu sürede aklındaki endişeleri yaz: Seni korkutan ne? Neyi kontrol etmeye çalışıyorsun? Hangisi bugün çözülmeyecek?\n\nSorulara tek tek bakabilirsin. Önce seni korkutan şeyi yaz. Sonra kontrol etmeye çalıştığın şeyi. En son da bugün çözülmeyecek olanları. Liste uzun olabilir, kısa da olabilir.\n\nBazı endişeler cümle hâline gelince küçülür. Bazıları aynı kalır. İkisi de olur. Senin işin sadece onları kâğıda aktarmak.\n\nDüzgün yazmaya çalışma. Aklına geldiği gibi yaz.\n\nYazım yanlışları, yarım cümleler, karalamalar… hiçbiri önemli değil. Bu sayfayı kimse okumayacak. Eline gelen ilk kelimeyle başla ve kalemin durmamasına izin ver.\n\nİstersen kaydı burada durdur ve on dakikanı kullan. Bitince devam et.\n\nSüre dolunca son satıra şunu yaz: “Pencere kapandı.”\n\nBu cümle bir sınır çizer. Zihnine bugünkü sürenin bittiğini söyler. Kelimeleri yazarken yavaşla ve her harfi hisset.\n\nSonra bir nefes al ve uzun uzun ver. Omuzlarını aşağı bırak. Çeneni gevşet.\n\nSonra defteri kapat ve kaldır. Endişeler kaybolmasa bile artık onlara ayrılmış bir yer var. Yarın gerekirse pencereyi yeniden açabilirsin.\n\nEndişeler gün içinde yeniden kapını çalabilir. O zaman onlara nazikçe şunu söyleyebilirsin: “Seni yarın pencerede dinleyeceğim.” Bu onları yok saymak değil; onlara bir randevu vermek.\n\nPencere kapandıktan sonra bedenine küçük bir iyilik yap. Bir bardak su iç, pencereyi aç, birkaç adım yürü. Zihnin, endişeden başka bir şeye de yer olduğunu hatırlasın.\n\nBu alıştırmayı birkaç gün tekrarlarsan, endişelerin hep aynı saatte toplanmaya başladığını fark edebilirsin. Geri kalan saatler biraz daha hafif kalır.",
    en: "Trying to erase worries completely rarely works. Instead, give them a small window of time.\n\nBefore you begin, choose a comfortable spot. It could be at a table, on the edge of the bed, or in the kitchen. Put a notebook and a pen in front of you. Silence your phone, but keep it nearby for the timer.\n\nTake a breath. Your worries may be drifting around your mind in no particular order right now. In a moment, we will make a place for them. Like a window: open for a set time, then closed.\n\nSet a timer for ten minutes. In that time, write down what is on your mind: What scares you? What are you trying to control? Which of these will not be solved today?\n\nYou can take the questions one at a time. First, write what scares you. Then what you are trying to control. Last of all, the things that will not be solved today. The list might be long, or it might be short.\n\nSome worries shrink once they become a sentence. Others stay the same size. Both are fine. Your only job is to move them onto the paper.\n\nDo not try to write neatly. Just write it as it comes.\n\nSpelling mistakes, half sentences, scribbles… none of it matters. No one will read this page. Start with the first word that comes, and let the pen keep moving.\n\nIf you like, pause the recording here and use your ten minutes. Come back when you are done.\n\nWhen the time is up, write this on the last line: “The window is closed.”\n\nThis sentence draws a line. It tells your mind that today's time is over. As you write the words, slow down and feel each letter.\n\nThen take a breath and let it out long and slow. Let your shoulders drop. Loosen your jaw.\n\nThen close the notebook and put it away. Even if the worries do not disappear, they now have a place of their own. Tomorrow you can open the window again if you need to.\n\nWorries may knock on your door again during the day. When they do, you can gently tell them: “I will listen to you at the window tomorrow.” That is not ignoring them; it is giving them an appointment.\n\nOnce the window is closed, do something small and kind for your body. Drink a glass of water, open a window, walk a few steps. Let your mind remember that there is room for things other than worry.\n\nIf you repeat this for a few days, you may notice your worries starting to gather at the same time each day. The rest of the hours feel a little lighter.",
    az: "Narahatlıqları tamamilə silməyə çalışmaq çox vaxt işə yaramır. Bunun əvəzinə onlara kiçik bir vaxt ayır.\n\nBaşlamazdan əvvəl rahat bir yer seç. Masa arxası, çarpayının kənarı və ya mətbəx ola bilər. Qarşına bir dəftər və qələm qoy. Telefonunu səssizə al, amma taymer üçün yanında saxla.\n\nBir nəfəs al. Narahatlıqların indi ağlında dağınıq halda dolaşa bilər. Bir azdan onlara yer açacağıq. Pəncərə kimi: müəyyən vaxt açıq, sonra bağlı.\n\nOn dəqiqəlik taymer qur. Bu müddətdə ağlındakı narahatlıqları yaz: Səni qorxudan nədir? Nəyi idarə etməyə çalışırsan? Hansı bu gün həll olunmayacaq?\n\nSuallara bir-bir baxa bilərsən. Əvvəlcə səni qorxudan şeyi yaz. Sonra idarə etməyə çalışdığın şeyi. Ən sonda da bu gün həll olunmayacaq şeyləri. Siyahı uzun da ola bilər, qısa da.\n\nBəzi narahatlıqlar cümləyə çevriləndə kiçilir. Bəziləri eyni qalır. İkisi də olar. Sənin işin sadəcə onları kağıza köçürməkdir.\n\nSəliqəli yazmağa çalışma. Ağlına necə gəlirsə, elə yaz.\n\nYazı səhvləri, yarımçıq cümlələr, cızma-qaralar… heç biri vacib deyil. Bu səhifəni heç kim oxumayacaq. Ağlına gələn ilk sözlə başla və qələmin dayanmasına imkan vermə.\n\nİstəsən, səsi burada dayandır və on dəqiqəni istifadə et. Bitirəndə davam et.\n\nVaxt bitəndə son sətirə bunu yaz: “Pəncərə bağlandı.”\n\nBu cümlə bir sərhəd çəkir. Ağlına bugünkü vaxtın bitdiyini deyir. Sözləri yazanda yavaşla və hər hərfi hiss et.\n\nSonra bir nəfəs al və uzun-uzun ver. Çiyinlərini aşağı burax. Çənəni boşalt.\n\nSonra dəftəri bağla və qaldır. Narahatlıqlar yox olmasa da, artıq onlara ayrılmış bir yer var. Sabah lazım olsa, pəncərəni yenidən aça bilərsən.\n\nNarahatlıqlar gün ərzində yenə qapını döyə bilər. Onda onlara yumşaqca belə deyə bilərsən: “Səni sabah pəncərədə dinləyəcəyəm.” Bu, onlara məhəl qoymamaq deyil; onlara görüş vaxtı vermək deməkdir.\n\nPəncərə bağlanandan sonra bədəninə kiçik bir yaxşılıq et. Bir stəkan su iç, pəncərəni aç, bir neçə addım at. Qoy ağlın narahatlıqdan başqa şeylərə də yer olduğunu xatırlasın.\n\nBu məşqi bir neçə gün təkrarlasan, narahatlıqlarının hər gün eyni saatda toplanmağa başladığını görə bilərsən. Qalan saatlar bir az daha yüngül keçir.",
    ru: "Пытаться полностью стереть тревогу обычно бесполезно. Вместо этого дай ей немного времени.\n\nПеред началом выбери удобное место. Стол, край кровати или кухня. Положи перед собой тетрадь и ручку. Выключи звук на телефоне, но оставь его рядом для таймера.\n\nСделай вдох. Тревоги сейчас могут беспорядочно бродить в голове. Сейчас мы выделим для них место. Как окно: открыто на определённое время, потом закрыто.\n\nПоставь таймер на десять минут. За это время запиши всё, что беспокоит: Что тебя пугает? Что ты пытаешься контролировать? Что из этого сегодня не решится?\n\nВопросы можно брать по одному. Сначала запиши то, что пугает. Потом то, что пытаешься контролировать. И в конце то, что сегодня не решится. Список может быть длинным, а может быть коротким.\n\nНекоторые тревоги уменьшаются, когда становятся предложением. Другие остаются прежними. И то и другое нормально. Твоя задача только перенести их на бумагу.\n\nНе старайся писать красиво. Пиши так, как приходит в голову.\n\nОшибки, обрывки фраз, каракули… всё это неважно. Эту страницу никто не прочитает. Начни с первого слова, которое придёт, и позволь ручке двигаться.\n\nЕсли хочется, поставь запись на паузу и используй свои десять минут. Потом возвращайся.\n\nКогда время выйдет, напиши последней строкой: «Окно закрыто».\n\nЭта фраза проводит границу. Она говорит уму, что на сегодня время вышло. Пока пишешь эти слова, замедлись и почувствуй каждую букву.\n\nПотом сделай вдох и долгий медленный выдох. Опусти плечи. Расслабь челюсть.\n\nПотом закрой тетрадь и убери её. Даже если тревога не исчезла, у неё теперь есть своё место. Завтра при необходимости окно можно открыть снова.\n\nВ течение дня тревоги могут снова постучаться. Тогда им можно мягко сказать: «Я выслушаю тебя завтра у окна». Это не значит отмахнуться от них; это значит назначить им встречу.\n\nКогда окно закрыто, сделай что-нибудь доброе для тела. Выпей стакан воды, открой форточку, пройдись немного. Пусть ум вспомнит, что в нём есть место не только тревоге.\n\nЕсли повторять это несколько дней, можно заметить, что тревоги начинают собираться в одно и то же время. А остальные часы становятся немного легче.",
  },
}
